	'Turn it on, then hit' => 'Aktivieren Sie es und klicken Sie dann auf',
	'Turn off to hide this page from the admin menu without deleting it.' => 'Deaktivieren Sie dies, um diese Seite aus dem Admin-Menü auszublenden, ohne sie zu löschen.',
	'Turn on in Settings' => 'In den Einstellungen aktivieren',
	'Turn this on to create and manage backups. Nothing runs until you ask for it.' => 'Aktivieren Sie dies, um Sicherungen zu erstellen und zu verwalten. Es wird nichts ausgeführt, bis Sie es anfordern.',
	'Turn this on to scan your site and generate themes. Nothing is changed on your live site — it only reads the rendered pages.' => 'Aktivieren Sie dies, um Ihre Website zu scannen und Themes zu generieren. An Ihrer Live-Website wird nichts geändert — es werden nur die gerenderten Seiten gelesen.',
	'Turn this on to show the consent banner on your site\'s front end and unlock the editor below.' => 'Aktivieren Sie dies, um das Einwilligungs-Banner im Frontend Ihrer Website anzuzeigen und den Editor unten freizuschalten.',
	'Type' => 'Typ',
