	'What to back up' => 'Was gesichert werden soll',
	'When' => 'Wann',
	'Which page builder do you use?' => 'Welchen Page-Builder verwenden Sie?',
	'While maintenance is on, everything is hidden from search.' => 'Während der Wartungsmodus aktiv ist, wird alles vor der Suche verborgen.',
	'Width' => 'Breite',
	'WordPress' => 'WordPress',
	'Working…' => 'Wird ausgeführt…',
	'Write to physical file' => 'In physische Datei schreiben',
	'XML sitemap' => 'XML-Sitemap',
	'Yes' => 'Ja',
	'You\'re all set' => 'Alles eingerichtet',
	'Your backups' => 'Ihre Sicherungen',
	'A bad rule here can take the whole site down with a 500 error. Unlocking takes a snapshot first, so' => 'Eine fehlerhafte Regel kann hier die gesamte Website mit einem 500-Fehler lahmlegen. Beim Entsperren wird zuerst eine Sicherungskopie erstellt, damit',
	'Add, remove and reorder buttons. Each one can be a button or a link, do something (accept, reject, open preferences, save) or point to a URL, and be styled individually.' => 'Schaltflächen hinzufügen, entfernen und neu anordnen. Jede kann eine Schaltfläche oder ein Link sein, eine Aktion ausführen (Annehmen, Ablehnen, Einstellungen öffnen, Speichern) oder auf eine URL verweisen und individuell gestaltet werden.',
	'An extra AVIF twin, usually 15–30% smaller again. Capable browsers get AVIF, everyone else falls back to WebP, then the original. Slower to encode.' => 'Ein zusätzliches AVIF-Gegenstück, meist nochmals 15–30 % kleiner. Fähige Browser erhalten AVIF, alle anderen greifen auf WebP und dann auf das Original zurück. Langsamer zu kodieren.',
	'Appends a ready-made block to the editor above — review, then save.' => 'Fügt dem Editor oben einen fertigen Block hinzu — prüfen, dann speichern.',
	'Applies the standard robots.txt, switches on the sitemap and generates it right now — everything wired in one click.' => 'Wendet die Standard-robots.txt an, aktiviert die Sitemap und generiert sie sofort — alles mit einem Klick eingerichtet.',
	'Auto picks the best available engine. Force one only if you have a reason to.' => 'Automatisch wählt die beste verfügbare Engine. Erzwingen Sie eine nur, wenn Sie einen Grund dazu haben.',
	'Auto-learn builds itself from real traffic — no setup needed. Cloudflare/Local can be scanned manually below.' => 'Auto-Lernen baut sich aus echtem Traffic auf — keine Einrichtung nötig. Cloudflare/Lokal können unten manuell gescannt werden.',
	'Auto-learn data and cached CSS cleared. Learning will restart from your next visitors.' => 'Auto-Lern-Daten und zwischengespeichertes CSS geleert. Das Lernen beginnt mit Ihren nächsten Besuchern neu.',
	'Auto-learn needs no action — it optimizes each page after a few visits and keeps improving. Use Scan only for the Cloudflare or Local engines. Clear/Reset after a design change or if something looks off.' => 'Auto-Lernen erfordert keine Aktion — es optimiert jede Seite nach einigen Besuchen und verbessert sich fortlaufend. Verwenden Sie „Scannen“ nur für die Cloudflare- oder Lokal-Engine. Leeren/Zurücksetzen nach einer Designänderung oder wenn etwas nicht stimmt.',
	'Back up your database and files, download them, restore in a click, or import a backup from another site. Backups live in a protected folder under' => 'Sichern Sie Ihre Datenbank und Dateien, laden Sie sie herunter, stellen Sie sie mit einem Klick wieder her oder importieren Sie eine Sicherung von einer anderen Website. Sicherungen liegen in einem geschützten Ordner unter',
	'Built %1$s (%2$s)' => 'Erstellt %1$s (%2$s)',
	'Bulk import — pipe format' => 'Massenimport — Pipe-Format',
	'By default WordPress sends mail as' => 'Standardmäßig versendet WordPress E-Mails als',
	'Changes the language of Velox\'s own screens only — WordPress and your other plugins are unaffected. English and German are complete; other languages are being translated and fall back to English until finished.' => 'Ändert nur die Sprache der Velox-eigenen Bildschirme — WordPress und Ihre anderen Plugins sind nicht betroffen. Englisch und Deutsch sind vollständig; andere Sprachen werden übersetzt und greifen bis zur Fertigstellung auf Englisch zurück.',
	'Cleared %d cached used-CSS file(s).' => '%d zwischengespeicherte Used-CSS-Datei(en) geleert.',
	'Cloudflare daily browser limit reached (10 min/day on the free plan). Try again tomorrow or upgrade to Workers Paid.' => 'Tägliches Cloudflare-Browser-Limit erreicht (10 Min./Tag im kostenlosen Tarif). Versuchen Sie es morgen erneut oder wechseln Sie zu Workers Paid.',
	'Cloudflare render failed: %s' => 'Cloudflare-Rendering fehlgeschlagen: %s',
	'Could not create the local fonts folder. Check uploads permissions.' => 'Der lokale Schriftarten-Ordner konnte nicht erstellt werden. Prüfen Sie die Upload-Berechtigungen.',
	'Could not create the used-CSS folder.' => 'Der Used-CSS-Ordner konnte nicht erstellt werden.',
	'Could not create the zip file.' => 'Die ZIP-Datei konnte nicht erstellt werden.',
	'Could not read the front page to scan for fonts.' => 'Die Startseite konnte nicht gelesen werden, um nach Schriftarten zu suchen.',
	'Could not rename %s. Check file permissions.' => '%s konnte nicht umbenannt werden. Prüfen Sie die Dateiberechtigungen.',
	'Create your first field group to start adding custom fields.' => 'Erstellen Sie Ihre erste Feldgruppe, um benutzerdefinierte Felder hinzuzufügen.',
	'Custom address…' => 'Benutzerdefinierte Adresse…',
	'Custom fields is on' => 'Benutzerdefinierte Felder sind aktiv',
	'Custom post types appear in the admin sidebar next to Posts and Pages.' => 'Benutzerdefinierte Beitragstypen erscheinen in der Admin-Seitenleiste neben Beiträgen und Seiten.',
	'Dim background (modal)' => 'Hintergrund abdunkeln (Modal)',
	'Don\'t run a second full-page cache plugin (WP Rocket, W3 Total Cache) alongside it — Cloudflare recommends turning those off. Velox\'s own page cache is fine.' => 'Betreiben Sie kein zweites Full-Page-Cache-Plugin (WP Rocket, W3 Total Cache) daneben — Cloudflare empfiehlt, diese zu deaktivieren. Velox’ eigener Seiten-Cache ist unproblematisch.',
	'Drag the slider or type an exact value. 80% is a good balance; lossless mode below ignores this.' => 'Ziehen Sie den Schieberegler oder geben Sie einen genauen Wert ein. 80 % sind ein guter Kompromiss; der verlustfreie Modus unten ignoriert diesen Wert.',
	'Edit your robots.txt, control how each page appears in Google, and keep an XML sitemap in sync — the essentials, without a second heavyweight SEO plugin.' => 'Bearbeiten Sie Ihre robots.txt, steuern Sie, wie jede Seite in Google erscheint, und halten Sie eine XML-Sitemap synchron — das Wesentliche, ohne ein zweites schwergewichtiges SEO-Plugin.',
	'Enable WebP output in Images settings first.' => 'Aktivieren Sie zuerst die WebP-Ausgabe in den Bild-Einstellungen.',
	'Every page and post is set to noindex, nofollow, and anything you create or duplicate meanwhile starts hidden too. Pages you had already set to noindex are left alone. When you switch maintenance back off, Velox asks what to do with them.' => 'Jede Seite und jeder Beitrag wird auf noindex, nofollow gesetzt, und alles, was Sie währenddessen erstellen oder duplizieren, beginnt ebenfalls verborgen. Seiten, die Sie bereits auf noindex gesetzt hatten, bleiben unberührt. Wenn Sie den Wartungsmodus wieder deaktivieren, fragt Velox, was damit geschehen soll.',
	'Export pipe list' => 'Pipe-Liste exportieren',
	'Finds images nothing in your content or page-builder data points at. It\'s deliberately cautious — it won\'t list a file that looks referenced anywhere — but always eyeball the list before deleting, since some references (external CSS, exports) can\'t be detected.' => 'Findet Bilder, auf die nichts in Ihren Inhalten oder Page-Builder-Daten verweist. Es geht bewusst vorsichtig vor — es listet keine Datei auf, die irgendwo referenziert scheint — prüfen Sie die Liste dennoch immer vor dem Löschen, da manche Referenzen (externes CSS, Exporte) nicht erkannt werden können.',
	'First-party visitor counts, measured by Velox\'s own lightweight beacon — no third-party analytics.' => 'First-Party-Besucherzählung, gemessen durch Velox’ eigenen leichtgewichtigen Beacon — keine Drittanbieter-Analyse.',
	'First-party, aggregate only. Mention it in your privacy policy.' => 'First-Party, nur aggregiert. Erwähnen Sie es in Ihrer Datenschutzerklärung.',
	'Form canvas' => 'Formular-Arbeitsfläche',
	'Found the Google Fonts CSS but could not download any font files. The server may be blocking outbound requests to fonts.gstatic.com.' => 'Das Google-Fonts-CSS wurde gefunden, aber es konnten keine Schriftdateien heruntergeladen werden. Der Server blockiert möglicherweise ausgehende Anfragen an fonts.gstatic.com.',
	'Get keys from your provider, paste them below, then switch on “Require CAPTCHA” per form. No keys = the option stays unusable.' => 'Holen Sie sich die Schlüssel von Ihrem Anbieter, fügen Sie sie unten ein und aktivieren Sie dann „CAPTCHA erforderlich“ pro Formular. Keine Schlüssel = die Option bleibt unbenutzbar.',
	'Hosted %1$d font file(s) across %2$d family/families locally.' => '%1$d Schriftdatei(en) aus %2$d Familie(n) lokal gehostet.',
	'If the site is ever compromised, revoke the token in Cloudflare (My Profile → API Tokens) and issue a new one.' => 'Falls die Website jemals kompromittiert wird, widerrufen Sie das Token in Cloudflare (Mein Profil → API-Token) und stellen Sie ein neues aus.',
	'Image, GIF, or Lottie (.json / .lottie) URL. Leave empty to use the default Velox mark.' => 'Bild-, GIF- oder Lottie-URL (.json / .lottie). Leer lassen, um das Standard-Velox-Zeichen zu verwenden.',
	'Images wider than this are scaled down to it; the height follows automatically to keep the aspect ratio. Images already narrower are left at their own size (never upscaled). 0 = never resize.' => 'Bilder, die breiter sind, werden darauf verkleinert; die Höhe folgt automatisch, um das Seitenverhältnis zu wahren. Bereits schmalere Bilder behalten ihre eigene Größe (nie hochskaliert). 0 = nie skalieren.',
	'Install a whole stack at once — paste wordpress.org slugs or links, or upload plugin ZIPs straight from your computer. Save a list as a blueprint to re-apply on the next site.' => 'Installieren Sie einen ganzen Stack auf einmal — fügen Sie wordpress.org-Slugs oder -Links ein oder laden Sie Plugin-ZIPs direkt von Ihrem Computer hoch. Speichern Sie eine Liste als Blueprint, um sie auf der nächsten Website erneut anzuwenden.',
	'Logging is off. Flip it on to start recording events from this point forward.' => 'Die Protokollierung ist aus. Aktivieren Sie sie, um ab diesem Zeitpunkt Ereignisse aufzuzeichnen.',
	'Mail not reaching Gmail or Microsoft? Run this to see exactly which authentication record your domain is missing.' => 'E-Mails erreichen Gmail oder Microsoft nicht? Führen Sie dies aus, um genau zu sehen, welcher Authentifizierungseintrag Ihrer Domain fehlt.',
	'No CSS found to scan. If your host blocks loopback, Velox reads the builder CSS cache instead — open your site once so it gets generated, then try again.' => 'Kein CSS zum Scannen gefunden. Wenn Ihr Host Loopback blockiert, liest Velox stattdessen den Builder-CSS-Cache — öffnen Sie Ihre Website einmal, damit er generiert wird, und versuchen Sie es dann erneut.',
	'No Google Fonts were found on the front page. If your fonts load elsewhere, link a page that uses them.' => 'Auf der Startseite wurden keine Google Fonts gefunden. Wenn Ihre Schriftarten anderswo geladen werden, verlinken Sie eine Seite, die sie verwendet.',
	'No HTML came back for that path.' => 'Für diesen Pfad kam kein HTML zurück.',
	'No backups yet. Create one above, import one, or set up a schedule below.' => 'Noch keine Sicherungen. Erstellen Sie oben eine, importieren Sie eine oder richten Sie unten einen Zeitplan ein.',
	'No custom post types yet. Add one and it shows up in the sidebar straight away.' => 'Noch keine benutzerdefinierten Beitragstypen. Fügen Sie einen hinzu, und er erscheint sofort in der Seitenleiste.',
	'No image engine (Imagick or GD with WebP) was found on this server. Conversion is disabled until one is enabled in your PHP settings — see the compatibility list below.' => 'Auf diesem Server wurde keine Bild-Engine (Imagick oder GD mit WebP) gefunden. Die Konvertierung ist deaktiviert, bis eine in Ihren PHP-Einstellungen aktiviert ist — siehe die Kompatibilitätsliste unten.',
	'No local stylesheets to trim on that page.' => 'Auf dieser Seite gibt es keine lokalen Stylesheets zum Kürzen.',
	'No output format selected — enable WebP and/or AVIF in Images settings.' => 'Kein Ausgabeformat ausgewählt — aktivieren Sie WebP und/oder AVIF in den Bild-Einstellungen.',
	'Nothing converted yet. Run a bulk optimization to fill this up.' => 'Noch nichts konvertiert. Führen Sie eine Massenoptimierung aus, um dies zu füllen.',
	'OctoberCMS builder is on' => 'OctoberCMS-Builder ist aktiv',
	'Off (default) strips camera, date and GPS data for smaller, more private files. On keeps it.' => 'Aus (Standard) entfernt Kamera-, Datums- und GPS-Daten für kleinere, privatere Dateien. Ein behält sie.',
	'On (recommended): the JPG/PNG becomes a WebP right in your media library, at its real smaller size. Off: keeps the original and serves a WebP copy only on the front-end.' => 'Ein (empfohlen): Das JPG/PNG wird direkt in Ihrer Mediathek zu einem WebP in seiner tatsächlich kleineren Größe. Aus: behält das Original und liefert nur im Frontend eine WebP-Kopie aus.',
	'On by default. Rewrites the page HTML on the front end. With Cloudflare Polish enabled you can leave this off.' => 'Standardmäßig aktiv. Schreibt das Seiten-HTML im Frontend um. Mit aktiviertem Cloudflare Polish können Sie dies deaktiviert lassen.',
	'Pages that were already set to noindex before you switched this on were left alone, so their own setting is untouched.' => 'Seiten, die bereits auf noindex gesetzt waren, bevor Sie dies aktiviert haben, wurden unberührt gelassen, sodass ihre eigene Einstellung unverändert bleibt.',
	'Paste this into any page, widget or Oxygen Shortcode element.' => 'Fügen Sie dies in eine beliebige Seite, ein Widget oder ein Oxygen-Shortcode-Element ein.',
	'Perfect quality with no compression loss — larger files. Great for graphics and screenshots, overkill for photos.' => 'Perfekte Qualität ohne Kompressionsverlust — größere Dateien. Ideal für Grafiken und Screenshots, übertrieben für Fotos.',
	'Phones often work best as a bottom or top bar even when desktop is a floating box.' => 'Auf Telefonen funktioniert oft eine untere oder obere Leiste am besten, selbst wenn der Desktop eine schwebende Box ist.',
	'Pick a file on the left to open it here.' => 'Wählen Sie links eine Datei aus, um sie hier zu öffnen.',
	'Pick the recommended path and Velox scans your plugins and tunes everything for you — or configure it yourself.' => 'Wählen Sie den empfohlenen Weg, und Velox scannt Ihre Plugins und stimmt alles für Sie ab — oder konfigurieren Sie es selbst.',
	'Plays when the banner first appears on the live site.' => 'Wird abgespielt, wenn das Banner zum ersten Mal auf der Live-Website erscheint.',
	'Plugins — slugs or links' => 'Plugins — Slugs oder Links',
	'Real Lighthouse scores from Google PageSpeed Insights, right on your dashboard.' => 'Echte Lighthouse-Werte von Google PageSpeed Insights, direkt in Ihrem Dashboard.',
	'Restores run' => 'Wiederherstellungen laufen',
	'Run PHP early — add_action, add_filter, custom logic. Lint-checked and crash-guarded.' => 'Führen Sie PHP früh aus — add_action, add_filter, eigene Logik. Syntaxgeprüft und absturzgesichert.',
	'Run backups automatically via WP-Cron. Older backups beyond your keep-count are pruned after each scheduled run.' => 'Führen Sie Sicherungen automatisch über WP-Cron aus. Ältere Sicherungen jenseits Ihrer Aufbewahrungsanzahl werden nach jedem geplanten Lauf entfernt.',
	'Runs the cleanup (not table optimization) once a week via WP-Cron.' => 'Führt die Bereinigung (nicht die Tabellenoptimierung) einmal wöchentlich über WP-Cron aus.',
	'Send old or moved URLs somewhere useful, and watch which missing pages your visitors actually hit so you can fix the ones that matter.' => 'Leiten Sie alte oder verschobene URLs an ein sinnvolles Ziel und beobachten Sie, welche fehlenden Seiten Ihre Besucher tatsächlich aufrufen, damit Sie die wichtigen beheben können.',
	'Served by Apache / LiteSpeed from your site root. Has no effect on a pure-Nginx server.' => 'Wird von Apache / LiteSpeed aus Ihrem Website-Stammverzeichnis ausgeliefert. Hat auf einem reinen Nginx-Server keine Wirkung.',
	'Sets consent to denied by default and updates Google tags when the visitor chooses. The correct way to stay compliant.' => 'Setzt die Einwilligung standardmäßig auf abgelehnt und aktualisiert Google-Tags, wenn der Besucher wählt. Der korrekte Weg, konform zu bleiben.',
	'Setup guide: clear Cloudflare cache from Velox' => 'Einrichtungsanleitung: Cloudflare-Cache aus Velox leeren',
	'Shows visitors a branded holding page while you work. You and any other admins keep seeing the live site, and wp-admin stays reachable. Sends a 503 so search engines know it\'s temporary.' => 'Zeigt Besuchern eine gebrandete Platzhalterseite, während Sie arbeiten. Sie und andere Administratoren sehen weiterhin die Live-Website, und wp-admin bleibt erreichbar. Sendet einen 503, damit Suchmaschinen wissen, dass es vorübergehend ist.',
	'Sits behind a tint of your background colour so text stays readable.' => 'Liegt hinter einer Tönung Ihrer Hintergrundfarbe, damit der Text lesbar bleibt.',
	'Skip the automatic tuning and head straight to Settings → Performance to set everything by hand.' => 'Überspringen Sie die automatische Abstimmung und gehen Sie direkt zu Einstellungen → Performance, um alles von Hand einzustellen.',
	'Small line at the very bottom. Empty = nothing shown (no site name forced in).' => 'Kleine Zeile ganz unten. Leer = nichts angezeigt (kein Website-Name erzwungen).',
	'Submissions through this form show up here as they arrive.' => 'Einsendungen über dieses Formular erscheinen hier, sobald sie eintreffen.',
	'Swaps every uploads image to WebP/AVIF when the browser supports it — WordPress images, Oxygen elements, CSS background-images and hard-coded links (originals stay as fallback).' => 'Ersetzt jedes Upload-Bild durch WebP/AVIF, wenn der Browser es unterstützt — WordPress-Bilder, Oxygen-Elemente, CSS-Hintergrundbilder und fest verdrahtete Links (Originale bleiben als Fallback).',
	'Switching builders? Run this again — Velox will wipe the old performance settings and reconfigure for the new one. Your image, font and database settings are kept.' => 'Builder wechseln? Führen Sie dies erneut aus — Velox löscht die alten Performance-Einstellungen und konfiguriert sie für den neuen neu. Ihre Bild-, Schriftarten- und Datenbank-Einstellungen bleiben erhalten.',
	'Take a database backup in Plesk before a big cleanup the first time. After that it\'s routine — revisions and transients pile up fast on builder sites.' => 'Erstellen Sie vor einer großen Bereinigung beim ersten Mal eine Datenbanksicherung in Plesk. Danach ist es Routine — Revisionen und Transients häufen sich auf Builder-Websites schnell an.',
	'That "content signals" block is coming from Cloudflare — not Velox.' => 'Dieser „Content Signals“-Block stammt von Cloudflare — nicht von Velox.',
	'The Cloudflare plugin already auto-purges on publish/edit; this button is for an on-demand whole-site purge.' => 'Das Cloudflare-Plugin leert den Cache bereits automatisch beim Veröffentlichen/Bearbeiten; diese Schaltfläche ist für eine bedarfsgesteuerte Leerung der gesamten Website.',
	'The file is replaced in place and its thumbnails are rebuilt, so the filename and every link to it stay exactly as they are. This cannot be undone.' => 'Die Datei wird an Ort und Stelle ersetzt und ihre Thumbnails werden neu erstellt, sodass der Dateiname und jeder Link darauf exakt erhalten bleiben. Dies kann nicht rückgängig gemacht werden.',
	'The modern baseline — typically 25–35% smaller than JPG/PNG with wide browser support.' => 'Der moderne Standard — typischerweise 25–35 % kleiner als JPG/PNG bei breiter Browser-Unterstützung.',
	'The override is switched off, so saving stores the choice without changing the page yet.' => 'Die Überschreibung ist ausgeschaltet, sodass beim Speichern die Auswahl gespeichert wird, ohne die Seite bereits zu ändern.',
	'The reply could not be sent — check your mail settings.' => 'Die Antwort konnte nicht gesendet werden — prüfen Sie Ihre E-Mail-Einstellungen.',
	'This is the real banner — same markup and CSS your visitors get. Switch the device tabs to check both layouts.' => 'Dies ist das echte Banner — dasselbe Markup und CSS, das Ihre Besucher erhalten. Wechseln Sie die Geräte-Tabs, um beide Layouts zu prüfen.',
	'This one hits the real login file directly, so it works even if the pretty URL above is blocked by your server or a CDN. If you ever can\'t reach the pretty URL, use this.' => 'Dieser greift direkt auf die echte Anmeldedatei zu, sodass er auch funktioniert, wenn die schöne URL oben von Ihrem Server oder einem CDN blockiert wird. Falls Sie die schöne URL einmal nicht erreichen, verwenden Sie diesen.',
	'Tried automatically if the primary send fails. Optional.' => 'Wird automatisch versucht, wenn der primäre Versand fehlschlägt. Optional.',
	'Turf war detected' => 'Revierkonflikt erkannt',
	'Turn each plugin on as soon as it\'s installed.' => 'Aktivieren Sie jedes Plugin, sobald es installiert ist.',
	'Turn this on to create forms and configure SMTP. Embed any form with' => 'Aktivieren Sie dies, um Formulare zu erstellen und SMTP zu konfigurieren. Betten Sie ein beliebiges Formular ein mit',
	'Typed names are saved in your browser — reload safely, they\'ll still be here until you apply them. Renaming updates every reference in posts and Oxygen automatically.' => 'Eingegebene Namen werden in Ihrem Browser gespeichert — Sie können gefahrlos neu laden, sie bleiben erhalten, bis Sie sie anwenden. Das Umbenennen aktualisiert automatisch jede Referenz in Beiträgen und Oxygen.',
	'Updates as you type. Admins still see the live site.' => 'Aktualisiert während der Eingabe. Administratoren sehen weiterhin die Live-Website.',
	'Use an address on your own domain so it isn\'t marked as spam.' => 'Verwenden Sie eine Adresse auf Ihrer eigenen Domain, damit sie nicht als Spam markiert wird.',
	'Used for any mail that doesn\'t match a route below.' => 'Wird für jede E-Mail verwendet, die keiner Route unten entspricht.',
	'Velox counts a visit the first time a real browser loads a page. Numbers will fill in as people visit your site.' => 'Velox zählt einen Besuch, wenn ein echter Browser eine Seite zum ersten Mal lädt. Die Zahlen füllen sich, während Menschen Ihre Website besuchen.',
	'Velox loads your front page, finds the Google Fonts it uses, downloads the woff2 files into your uploads folder and serves those instead. Re-scan after you change fonts.' => 'Velox lädt Ihre Startseite, findet die verwendeten Google Fonts, lädt die woff2-Dateien in Ihren Uploads-Ordner herunter und liefert diese stattdessen aus. Scannen Sie nach einer Schriftartenänderung erneut.',
	'Velox scans your builder and installed plugins, then shows tuned settings you can review and tweak before applying.' => 'Velox scannt Ihren Builder und die installierten Plugins und zeigt dann abgestimmte Einstellungen, die Sie vor dem Anwenden prüfen und anpassen können.',
	'Velox skipped your PHP snippets because one crashed the site (or you asked for Safe Mode). CSS, JS and HTML snippets are unaffected. Fix or switch off the offending snippet, then clear Safe Mode.' => 'Velox hat Ihre PHP-Snippets übersprungen, weil eines die Website zum Absturz gebracht hat (oder Sie den abgesicherten Modus angefordert haben). CSS-, JS- und HTML-Snippets sind nicht betroffen. Beheben oder deaktivieren Sie das betreffende Snippet und beenden Sie dann den abgesicherten Modus.',
	'Velox updates straight from GitHub releases, so it never appears in the public plugin directory. When a new version is released it shows up like any other plugin update.' => 'Velox aktualisiert direkt aus GitHub-Releases, sodass es nie im öffentlichen Plugin-Verzeichnis erscheint. Wenn eine neue Version veröffentlicht wird, erscheint sie wie jedes andere Plugin-Update.',
	'WP-Cron runs on traffic — quiet sites may back up a little late.' => 'WP-Cron läuft durch Traffic — bei ruhigen Websites kann die Sicherung etwas verspätet erfolgen.',
	'When this is off, the “Require CAPTCHA” switch is locked on every form. Turn it on and add your keys to allow forms to use it.' => 'Wenn dies aus ist, ist der Schalter „CAPTCHA erforderlich“ bei jedem Formular gesperrt. Aktivieren Sie es und fügen Sie Ihre Schlüssel hinzu, damit Formulare es verwenden können.',
	'While this is off, the page keeps whatever WordPress and your theme produce.' => 'Solange dies aus ist, behält die Seite das bei, was WordPress und Ihr Theme erzeugen.',
	'Your Velox page cache still clears fine without it.' => 'Ihr Velox-Seiten-Cache lässt sich auch ohne dies problemlos leeren.',
	'Your image optimization center — pick formats and quality, then convert your whole library. With replace mode on, images become WebP right in your media library; the resize width sets a max (height follows automatically, smaller images are left untouched).' => 'Ihr Zentrum für Bildoptimierung — wählen Sie Formate und Qualität und konvertieren Sie dann Ihre gesamte Mediathek. Mit aktiviertem Ersetzungsmodus werden Bilder direkt in Ihrer Mediathek zu WebP; die Skalierungsbreite legt ein Maximum fest (die Höhe folgt automatisch, kleinere Bilder bleiben unberührt).',
	'⚠ Editing files directly can break your site. Use with care.' => '⚠ Das direkte Bearbeiten von Dateien kann Ihre Website beschädigen. Mit Vorsicht verwenden.',
	'↻ Re-scan website' => '↻ Website erneut scannen',
	'⤓ Download all' => '⤓ Alle herunterladen',
	'← Prev' => '← Zurück',
	'+ Add connection' => '+ Verbindung hinzufügen',
	'+ Add rule' => '+ Regel hinzufügen',
	'+ Add rule group' => '+ Regelgruppe hinzufügen',
	'+ New form' => '+ Neues Formular',
	'(optional)' => '(optional)',
	'(optional — defaults to your domain)' => '(optional — standardmäßig Ihre Domain)',
	'(optional — e.g. legal note)' => '(optional — z. B. rechtlicher Hinweis)',
	'(top-level only)' => '(nur oberste Ebene)',
	'(homepage),' => '(Startseite),',
	'(lowercase, max 32 chars)' => '(Kleinbuchstaben, max. 32 Zeichen)',
	'(lowercase, max 32)' => '(Kleinbuchstaben, max. 32)',
	'(lowercase, max 20 chars — this is the post type key)' => '(Kleinbuchstaben, max. 20 Zeichen — dies ist der Beitragstyp-Schlüssel)',
	'(sets the right permissions automatically).' => '(setzt automatisch die richtigen Berechtigungen).',
	'(shown only once) and store it safely.' => '(wird nur einmal angezeigt) und bewahren Sie es sicher auf.',
	'(dashicons-… or image URL)' => '(dashicons-… oder Bild-URL)',
	'Next →' => 'Weiter →',
	'Careful:' => 'Vorsicht:',
	'Continue to summary →' => 'Weiter zur Zusammenfassung →',
	'Detect it for me →' => 'Für mich erkennen →',
	'Request it →' => 'Anfordern →',
	'Quick add:' => 'Schnell hinzufügen:',
	'Quick setup:' => 'Schnelleinrichtung:',
	'View converted images →' => 'Konvertierte Bilder ansehen →',
	'by Sumasearch' => 'von Sumasearch',
	'optional' => 'optional',
	'selected' => 'ausgewählt',
	'current' => 'aktuell',
	'archive' => 'Archiv',
	'blog' => 'Blog',
	'shop' => 'Shop',
	'front' => 'Startseite',
	'all' => 'alle',
	'and' => 'und',
	'or' => 'oder',
	'any' => 'beliebig',
	'file' => 'Datei',
	'widgets' => 'Widgets',
	'imported' => 'importiert',
	'restored straight away' => 'sofort wiederhergestellt',
	'safety' => 'Sicherheit',
	'copy it now' => 'jetzt kopieren',
	'drag to reorder' => 'zum Neuordnen ziehen',
	'example URLs — not your real site' => 'Beispiel-URLs — nicht Ihre echte Website',
	'in the last 30 days' => 'in den letzten 30 Tagen',
	'visitors / day' => 'Besucher / Tag',
	'— entries' => '— Einträge',
	'rows of junk to clean out' => 'Zeilen an Datenmüll zum Bereinigen',
	'No blueprints yet. Save a slug list above to create one.' => 'Noch keine Blueprints. Speichern Sie oben eine Slug-Liste, um einen zu erstellen.',
	'Authentication Mode →' => 'Authentifizierungsmodus →',
	'Bookmark your always-works recovery URL:' => 'Setzen Sie ein Lesezeichen für Ihre immer funktionierende Wiederherstellungs-URL:',
	'Detects every font your site loads. For each one:' => 'Erkennt jede Schriftart, die Ihre Website lädt. Für jede einzelne:',
	'Enter your Cloudflare account email + paste the token →' => 'Geben Sie die E-Mail Ihres Cloudflare-Kontos ein + fügen Sie das Token ein →',
	'Leave empty to keep the default wp-login. With a slug set, your login lives at:' => 'Leer lassen, um das Standard-wp-login beizubehalten. Mit gesetztem Slug befindet sich Ihre Anmeldung unter:',
	'One row per image:' => 'Eine Zeile pro Bild:',
	'Profile icon (top right) →' => 'Profilsymbol (oben rechts) →',
	'The full Google PageSpeed Insights report for' => 'Der vollständige Google-PageSpeed-Insights-Bericht für',
	'Velox tunes its performance settings to your builder. Currently configured for:' => 'Velox stimmt seine Performance-Einstellungen auf Ihren Builder ab. Aktuell konfiguriert für:',
	'turns on only the optimizations that can\'t break a site.' => 'aktiviert nur die Optimierungen, die eine Website nicht beschädigen können.',
	'adds async CSS, unused-CSS removal (auto-learn), JS delay and bloat removal — then test and exclude anything that misbehaves. Neither touches jQuery Migrate or content-visibility (those need per-site testing).' => 'fügt asynchrones CSS, Entfernung von ungenutztem CSS (Auto-Lernen), JS-Verzögerung und Ballast-Entfernung hinzu — testen Sie anschließend und schließen Sie alles aus, was sich fehlerhaft verhält. Keines davon berührt jQuery Migrate oder content-visibility (diese erfordern seitenweise Tests).',
	'The' => 'Die',
	'That\'s' => 'Das ist',
	'A physical' => 'Eine physische',
	'Switch on to use' => 'Aktivieren, um zu verwenden',
	'Used when' => 'Verwendet, wenn',
	'Saves your' => 'Speichert Ihre',
	'Upload a' => 'Laden Sie eine',
	'Tip: drop' => 'Tipp: Legen Sie',
	'Once enabled,' => 'Nach der Aktivierung',
	'tell us' => 'kontaktieren Sie uns',
	'which you need next.' => 'welches Sie als Nächstes benötigen.',
	'shown as the sender' => 'als Absender angezeigt',
	'Or upload plugin ZIPs' => 'Oder laden Sie Plugin-ZIPs hoch',
	'Seeing AI "content signals" text instead of yours?' => 'Sehen Sie KI-„Content-Signals“-Text statt Ihrem eigenen?',
	'A bad rule here can take the whole site down with a 500 error. Unlocking takes a snapshot first, so %s can always put it back exactly as it was when you unlocked.' => 'Eine fehlerhafte Regel kann hier die gesamte Website mit einem 500-Fehler lahmlegen. Beim Entsperren wird zuerst eine Sicherungskopie erstellt, sodass %s sie jederzeit exakt in den Zustand vor dem Entsperren zurückversetzen kann.',
	'A physical %s exists in your site root and is being served directly. The editor keeps it in sync on save. This is the most reliable setup behind Nginx or a CDN — use "Back to virtual" to remove it.' => 'Eine physische %s existiert in Ihrem Website-Stammverzeichnis und wird direkt ausgeliefert. Der Editor hält sie beim Speichern synchron. Dies ist die zuverlässigste Einrichtung hinter Nginx oder einem CDN — verwenden Sie „Zurück zu virtuell“, um sie zu entfernen.',
	'Add custom fields to posts, pages and any post type — ACF-style field groups with location rules and a %s API.' => 'Fügen Sie Beiträgen, Seiten und jedem Beitragstyp benutzerdefinierte Felder hinzu — Feldgruppen im ACF-Stil mit Positionsregeln und einer %s-API.',
	'Authentication Mode → %s.' => 'Authentifizierungsmodus → %s.',
	'Back up your database and files, download them, restore in a click, or import a backup from another site. Backups live in a protected folder under %s.' => 'Sichern Sie Ihre Datenbank und Dateien, laden Sie sie herunter, stellen Sie sie mit einem Klick wieder her oder importieren Sie eine Sicherung von einer anderen Website. Sicherungen liegen in einem geschützten Ordner unter %s.',
	'Builder not listed? %s' => 'Builder nicht aufgeführt? %s',
	'By default WordPress sends mail as %s. Set your own name and address here and every mail Velox sends uses it instead.' => 'Standardmäßig versendet WordPress E-Mails als %s. Legen Sie hier Ihren eigenen Namen und Ihre Adresse fest, und jede von Velox gesendete E-Mail verwendet diese stattdessen.',
	'Come back here — this note should turn green ("Cloudflare connected") and the Cloudflare button should report "Cloudflare purged."' => 'Kommen Sie hierher zurück — dieser Hinweis sollte grün werden („Cloudflare verbunden“), und die Cloudflare-Schaltfläche sollte „Cloudflare geleert“ melden.',
	'Continue to summary → %1$s → %2$s (shown only once) and store it safely.' => 'Weiter zur Zusammenfassung → %1$s → %2$s (wird nur einmal angezeigt) und bewahren Sie es sicher auf.',
	'Detects every font your site loads. For each one: %1$s starts it loading immediately (only worth it for the 1–2 fonts visible above the fold), and %2$s stops a Google-hosted font from loading at all. Local/builder fonts can be preloaded but not blocked.' => 'Erkennt jede Schriftart, die Ihre Website lädt. Für jede einzelne: %1$s startet das Laden sofort (nur für die 1–2 Schriftarten oberhalb des Falzes lohnenswert), und %2$s verhindert das Laden einer Google-gehosteten Schriftart vollständig. Lokale/Builder-Schriftarten können vorgeladen, aber nicht blockiert werden.',
	'Edit the %1$s, %2$s and %3$s on any image below, then hit %4$s. Use %5$s to change the actual filename without breaking links. For bulk work, use %6$s with the %7$s format.' => 'Bearbeiten Sie %1$s, %2$s und %3$s bei jedem Bild unten und klicken Sie dann auf %4$s. Verwenden Sie %5$s, um den tatsächlichen Dateinamen zu ändern, ohne Links zu beschädigen. Für Massenbearbeitung verwenden Sie %6$s mit dem Format %7$s.',
	'Enter your Cloudflare account email + paste the token → %s.' => 'Geben Sie die E-Mail Ihres Cloudflare-Kontos ein + fügen Sie das Token ein → %s.',
	'Find %1$s in the templates → %2$s (sets the right permissions automatically).' => 'Suchen Sie %1$s in den Vorlagen → %2$s (setzt automatisch die richtigen Berechtigungen).',
	'For agency/company accounts, prefer an %s token so it survives staff changes.' => 'Für Agentur-/Unternehmenskonten bevorzugen Sie ein %s-Token, damit es Personalwechsel übersteht.',
	'Full control — target any element inside the banner. Scope your rules with %1$s (the banner) or %2$s (a specific button). Applied on top of everything above.' => 'Volle Kontrolle — sprechen Sie jedes Element innerhalb des Banners an. Begrenzen Sie Ihre Regeln mit %1$s (dem Banner) oder %2$s (einer bestimmten Schaltfläche). Wird zusätzlich zu allem oben Genannten angewendet.',
	'Give the WordPress/Oxygen names something human. Every change is applied to the HTML %s the CSS together, and the preview updates as you type. When you\'re done, download a renamed version.' => 'Geben Sie den WordPress-/Oxygen-Namen etwas Menschliches. Jede Änderung wird auf das HTML %s das CSS gemeinsam angewendet, und die Vorschau aktualisiert sich während der Eingabe. Wenn Sie fertig sind, laden Sie eine umbenannte Version herunter.',
	'Live at %s' => 'Live unter %s',
	'Log in at %s.' => 'Melden Sie sich an unter %s.',
	'Moves the login page off the default %s to a path only you know — most brute-force bots hammer wp-login, so this quietly cuts that traffic.' => 'Verschiebt die Anmeldeseite vom Standard %s auf einen Pfad, den nur Sie kennen — die meisten Brute-Force-Bots hämmern auf wp-login, sodass dies diesen Traffic unauffällig reduziert.',
	'No %s exists in your site root yet — saving will create one.' => 'In Ihrem Website-Stammverzeichnis existiert noch keine %s — beim Speichern wird eine erstellt.',
	'No assets discovered yet. Click %s above, or visit a few pages of your site, then reload this screen.' => 'Noch keine Assets erkannt. Klicken Sie oben auf %s oder besuchen Sie einige Seiten Ihrer Website und laden Sie diesen Bildschirm dann neu.',
	'No builds yet. Name your theme above and hit %s.' => 'Noch keine Builds. Benennen Sie oben Ihr Theme und klicken Sie auf %s.',
	'No forms yet. Hit %1$s to create one — you\'ll get a %2$s shortcode to embed anywhere, including an Oxygen Shortcode element.' => 'Noch keine Formulare. Klicken Sie auf %1$s, um eines zu erstellen — Sie erhalten einen %2$s-Shortcode zum Einbetten an beliebiger Stelle, auch in einem Oxygen-Shortcode-Element.',
	'Notifications are sent when the form is submitted. Use the %1$s menu to drop in merge tags like %2$s, or %3$s for the whole submission.' => 'Benachrichtigungen werden gesendet, wenn das Formular abgesendet wird. Verwenden Sie das Menü %1$s, um Merge-Tags wie %2$s einzufügen, oder %3$s für die gesamte Einsendung.',
	'Once enabled, %1$s and %2$s redirect away for logged-out visitors. If you ever lock yourself out, clear the %3$s value (or deactivate Velox) via your hosting file manager to restore the default login.' => 'Nach der Aktivierung leiten %1$s und %2$s abgemeldete Besucher weg. Falls Sie sich jemals aussperren, löschen Sie den Wert %3$s (oder deaktivieren Sie Velox) über den Dateimanager Ihres Hosters, um die Standardanmeldung wiederherzustellen.',
	'Once on, build field groups here and they\'ll appear on the matching post edit screens. Read values on the front end with %1$s or the %2$s merge tag.' => 'Sobald aktiviert, erstellen Sie hier Feldgruppen, und sie erscheinen auf den passenden Beitragsbearbeitungs-Bildschirmen. Lesen Sie Werte im Frontend mit %1$s oder dem Merge-Tag %2$s.',
	'One per line. Accepts a plain slug (%1$s), a wordpress.org link, or a direct %2$s download URL.' => 'Eine pro Zeile. Akzeptiert einen einfachen Slug (%1$s), einen wordpress.org-Link oder eine direkte %2$s-Download-URL.',
	'One row per image: %s. Filenames are matched to your library; a header row is ignored.' => 'Eine Zeile pro Bild: %s. Dateinamen werden mit Ihrer Mediathek abgeglichen; eine Kopfzeile wird ignoriert.',
	'Options pages are admin screens for global settings (read with %s). Target one from a field group\'s location rule.' => 'Optionsseiten sind Admin-Bildschirme für globale Einstellungen (auslesbar mit %s). Sprechen Sie eine über die Positionsregel einer Feldgruppe an.',
	'PHP-zip is not available on this server, so the plugin zip cannot be built. Ask your host to enable the php-zip extension.' => 'PHP-zip ist auf diesem Server nicht verfügbar, sodass das Plugin-ZIP nicht erstellt werden kann. Bitten Sie Ihren Hoster, die php-zip-Erweiterung zu aktivieren.',
	'PHP-zip isn\'t available on this server, so %1$s backups can\'t be created or restored — database backups still work. Ask your host to enable the %2$s extension.' => 'PHP-zip ist auf diesem Server nicht verfügbar, sodass %1$s-Sicherungen nicht erstellt oder wiederhergestellt werden können — Datenbanksicherungen funktionieren weiterhin. Bitten Sie Ihren Hoster, die %2$s-Erweiterung zu aktivieren.',
	'Pick a Bootstrap icon, or type a %s class or image URL.' => 'Wählen Sie ein Bootstrap-Symbol oder geben Sie eine %s-Klasse oder Bild-URL ein.',
	'Pick one or more %s plugin files from your computer and install them directly.' => 'Wählen Sie eine oder mehrere %s-Plugin-Dateien von Ihrem Computer und installieren Sie sie direkt.',
	'Pick yours below — every builder needs different speed settings. Not sure? %s' => 'Wählen Sie Ihren unten — jeder Builder benötigt andere Geschwindigkeitseinstellungen. Nicht sicher? %s',
	'Plugins → Add New → search %1$s → install &amp; activate the one by %2$s (listed as "Cloudflare – CDN &amp; Edge Caching"). Don\'t confuse it with "WP Cloudflare Super Page Cache."' => 'Plugins → Installieren → suchen Sie %1$s → installieren und aktivieren Sie das von %2$s (aufgeführt als „Cloudflare – CDN &amp; Edge Caching“). Verwechseln Sie es nicht mit „WP Cloudflare Super Page Cache“.',
	'Profile icon (top right) → %s.' => 'Profilsymbol (oben rechts) → %s.',
	'Pull a real Lighthouse score from Google PageSpeed Insights on a schedule and show it on your dashboard. A free %1$s is recommended (checks run without one, but Google rate-limits keyless requests). Your server needs outbound access to %2$s and WordPress cron running.' => 'Rufen Sie einen echten Lighthouse-Wert von Google PageSpeed Insights planmäßig ab und zeigen Sie ihn in Ihrem Dashboard an. Ein kostenloser %1$s wird empfohlen (Prüfungen laufen auch ohne, aber Google drosselt schlüssellose Anfragen). Ihr Server benötigt ausgehenden Zugriff auf %2$s und einen laufenden WordPress-Cron.',
	'Purge caches across your whole stack in one click. Velox clears its own page cache, WP Fastest Cache and Oxygen directly. Cloudflare is cleared through the official Cloudflare plugin (see the note below).' => 'Leeren Sie Caches über Ihren gesamten Stack mit einem Klick. Velox leert seinen eigenen Seiten-Cache, WP Fastest Cache und Oxygen direkt. Cloudflare wird über das offizielle Cloudflare-Plugin geleert (siehe Hinweis unten).',
	'Quick setup: %1$s install the %2$s plugin, %3$s create a Cloudflare API token, %4$s connect it. Full steps below.' => 'Schnelleinrichtung: %1$s installieren Sie das %2$s-Plugin, %3$s erstellen Sie ein Cloudflare-API-Token, %4$s verbinden Sie es. Vollständige Schritte unten.',
	'Read from your live front page in this browser, so it shows what visitors and crawlers really get rather than what the setting claims. WordPress itself is set to %s.' => 'Wird in diesem Browser von Ihrer Live-Startseite gelesen, sodass angezeigt wird, was Besucher und Crawler wirklich erhalten, statt was die Einstellung behauptet. WordPress selbst ist auf %s eingestellt.',
	'Saves your %s database (a small DB-only backup) so you can undo this restore. It\'s the small one labelled “safety”.' => 'Speichert Ihre %s Datenbank (eine kleine reine DB-Sicherung), damit Sie diese Wiederherstellung rückgängig machen können. Es ist die kleine mit der Bezeichnung „Sicherheit“.',
	'Scan the whole site and export it as an importable OctoberCMS theme: every published page becomes a %s page, the shared header/footer are lifted into partials, the CSS is converted into the theme\'s SCSS structure, and the media you actually use (and have in the library) is bundled in. Builds are versioned — re-scan to pick up new pages, and keep older versions to revert to.' => 'Scannen Sie die gesamte Website und exportieren Sie sie als importierbares OctoberCMS-Theme: Jede veröffentlichte Seite wird zu einer %s-Seite, der gemeinsame Header/Footer wird in Partials ausgelagert, das CSS wird in die SCSS-Struktur des Themes umgewandelt, und die tatsächlich verwendeten Medien (die in der Mediathek vorhanden sind) werden eingebunden. Builds sind versioniert — scannen Sie erneut, um neue Seiten zu erfassen, und behalten Sie ältere Versionen zum Zurückkehren.',
	'Send mail from a specific address or name through a chosen connection — e.g. route %s through a transactional provider and newsletters through another.' => 'Versenden Sie E-Mails von einer bestimmten Adresse oder einem Namen über eine gewählte Verbindung — leiten Sie z. B. %s über einen Transaktionsanbieter und Newsletter über einen anderen.',
	'Served by WordPress at %s. Edit freely — the Sitemap line should point at your sitemap.xml.' => 'Wird von WordPress unter %s ausgeliefert. Frei bearbeitbar — die Sitemap-Zeile sollte auf Ihre sitemap.xml verweisen.',
	'Sets the %1$s attribute on the %2$s tag. Handy when a theme or builder hard-codes it and the WordPress site language never actually reaches the page — screen readers and search engines both read this attribute to decide what language the page is in.' => 'Setzt das Attribut %1$s am Tag %2$s. Praktisch, wenn ein Theme oder Builder es fest verdrahtet und die WordPress-Sprache die Seite nie tatsächlich erreicht — Screenreader und Suchmaschinen lesen beide dieses Attribut, um die Sprache der Seite zu bestimmen.',
	'Settings → Cloudflare (or the plugin\'s Settings link).' => 'Einstellungen → Cloudflare (oder der Einstellungs-Link des Plugins).',
	'Show this group where %1$s rules in a box match, or %2$s box matches.' => 'Diese Gruppe anzeigen, wenn %1$s Regeln in einem Kasten übereinstimmen, oder %2$s Kasten übereinstimmt.',
	'Source is a path on this site. Target can be a path (%1$s) or a full URL. Choose %2$s to tell search engines a page is permanently removed.' => 'Die Quelle ist ein Pfad auf dieser Website. Das Ziel kann ein Pfad (%1$s) oder eine vollständige URL sein. Wählen Sie %2$s, um Suchmaschinen mitzuteilen, dass eine Seite dauerhaft entfernt wurde.',
	'Stop plugins from loading CSS/JS where it isn\'t needed — the classic example is keeping Contact Form 7 off every page except your contact page. Pages are matched by ID, slug, %1$s (homepage), %2$s, %3$s, %4$s, or a whole post type with %5$s, %6$s, etc.' => 'Hindern Sie Plugins daran, CSS/JS dort zu laden, wo es nicht benötigt wird — das klassische Beispiel ist, Contact Form 7 auf jeder Seite außer Ihrer Kontaktseite fernzuhalten. Seiten werden nach ID, Slug, %1$s (Startseite), %2$s, %3$s, %4$s oder einem ganzen Beitragstyp mit %5$s, %6$s usw. abgeglichen.',
	'The %1$s / %2$s fields under Performance → CSS are a separate feature (the used-CSS engine) and aren\'t used for cache clearing.' => 'Die Felder %1$s / %2$s unter Performance → CSS sind eine separate Funktion (die Used-CSS-Engine) und werden nicht zum Leeren des Caches verwendet.',
	'The %1$s button clears your edge cache through the %2$s — Velox asks that plugin to purge, so it must be installed and connected to your account. Until then the button reports %3$s' => 'Die Schaltfläche %1$s leert Ihren Edge-Cache über das %2$s — Velox bittet dieses Plugin zu leeren, daher muss es installiert und mit Ihrem Konto verbunden sein. Bis dahin meldet die Schaltfläche %3$s',
	'The %s file isn\'t writable by WordPress, so editing is disabled. Adjust file permissions on the server to enable it.' => 'Die Datei %s ist für WordPress nicht beschreibbar, daher ist die Bearbeitung deaktiviert. Passen Sie die Dateiberechtigungen auf dem Server an, um sie zu aktivieren.',
	'The full Google PageSpeed Insights report for %s &mdash; every category, every check.' => 'Der vollständige Google-PageSpeed-Insights-Bericht für %s &mdash; jede Kategorie, jede Prüfung.',
	'The list grows as more of your site is visited. Set a rule, then %s. Disabling a handle also removes anything that depends on it, so re-test the page afterwards.' => 'Die Liste wächst, je mehr Ihrer Website besucht wird. Legen Sie eine Regel fest, dann %s. Das Deaktivieren eines Handles entfernt auch alles, was davon abhängt, testen Sie die Seite also anschließend erneut.',
	'The official Cloudflare plugin is active, so the %s button above purges your edge cache.' => 'Das offizielle Cloudflare-Plugin ist aktiv, sodass die Schaltfläche %s oben Ihren Edge-Cache leert.',
	'The submit button text, colours and full styling live on the %1$s — click the button there, or open the %2$s.' => 'Der Text, die Farben und die vollständige Gestaltung der Absende-Schaltfläche befinden sich auf %1$s — klicken Sie dort auf die Schaltfläche oder öffnen Sie %2$s.',
	'This crawls every published page over HTTP, so a large site can take a minute. If you\'re behind Cloudflare, run %s first — the builder falls back to your origin server automatically, but a strict WAF can still block it.' => 'Dies durchsucht jede veröffentlichte Seite über HTTP, sodass eine große Website eine Minute dauern kann. Wenn Sie hinter Cloudflare sind, führen Sie zuerst %s aus — der Builder greift automatisch auf Ihren Ursprungsserver zurück, aber eine strikte WAF kann ihn dennoch blockieren.',
	'Tip: drop %s anywhere (e.g. your footer) and it reopens this banner.' => 'Tipp: Platzieren Sie %s an beliebiger Stelle (z. B. in Ihrer Fußzeile), und es öffnet dieses Banner erneut.',
	'Turn it on, then hit %s (or just browse your site) so Velox can learn which handles load. You\'ll then be able to switch any of them off here.' => 'Aktivieren Sie es und klicken Sie dann auf %s (oder durchstöbern Sie einfach Ihre Website), damit Velox lernen kann, welche Handles geladen werden. Anschließend können Sie hier jedes davon abschalten.',
	'Turn this on to create forms and configure SMTP. Embed any form with %s — including inside an Oxygen Shortcode element.' => 'Aktivieren Sie dies, um Formulare zu erstellen und SMTP zu konfigurieren. Betten Sie ein beliebiges Formular mit %s ein — auch innerhalb eines Oxygen-Shortcode-Elements.',
	'Upload a %1$s dump or a %2$s archive made on another site and it\'s %3$s. A safety backup of the current site is taken first, so you can roll the restore back from the list below.' => 'Laden Sie einen %1$s-Dump oder ein %2$s-Archiv hoch, das auf einer anderen Website erstellt wurde, und es wird %3$s. Zuerst wird eine Sicherheitskopie der aktuellen Website erstellt, sodass Sie die Wiederherstellung über die Liste unten rückgängig machen können.',
	'Use the short region form, like %1$s or %2$s. Underscores are converted to hyphens for you.' => 'Verwenden Sie die kurze Regionsform, wie %1$s oder %2$s. Unterstriche werden für Sie in Bindestriche umgewandelt.',
	'Used when %1$s is set to %2$s. Upload a %3$s or %4$s from your media library, or paste a link (e.g. from LottieFiles).' => 'Wird verwendet, wenn %1$s auf %2$s gesetzt ist. Laden Sie eine %3$s oder %4$s aus Ihrer Mediathek hoch oder fügen Sie einen Link ein (z. B. von LottieFiles).',
	'Velox doesn\'t talk to Cloudflare directly — when you clear the Cloudflare cache, Velox asks the %1$s to purge everything. So it only works once that plugin is installed and connected; otherwise you get %2$s Your Velox page cache still clears fine without it.' => 'Velox kommuniziert nicht direkt mit Cloudflare — wenn Sie den Cloudflare-Cache leeren, bittet Velox das %1$s, alles zu leeren. Es funktioniert also erst, sobald dieses Plugin installiert und verbunden ist; andernfalls erhalten Sie %2$s Ihr Velox-Seiten-Cache lässt sich auch ohne dies problemlos leeren.',
	'editing core, %1$s, or a theme\'s %2$s can take the whole site down. If you\'re unsure, make a backup first (Utilities &rarr; Backup &amp; restore).' => 'Das Bearbeiten von Kern-Dateien, %1$s oder der %2$s eines Themes kann die gesamte Website lahmlegen. Wenn Sie unsicher sind, erstellen Sie zuerst eine Sicherung (Werkzeuge &rarr; Sicherung &amp; Wiederherstellung).',
