	'— how sitemap.xml looks when opened in a browser. Search engines still read the plain XML.' => '— wie sitemap.xml aussieht, wenn sie in einem Browser geöffnet wird. Suchmaschinen lesen weiterhin das reine XML.',
	'— switch off to disable forms and SMTP.' => '— ausschalten, um Formulare und SMTP zu deaktivieren.',
