	'— switch on to create field groups.' => '— einschalten, um Feldgruppen zu erstellen.',
	'“Cloudflare”' => '„Cloudflare“',
	'…) so links shared to Facebook, LinkedIn, WhatsApp and X show a rich preview. Turn off if another tool already handles them.' => '…), damit auf Facebook, LinkedIn, WhatsApp und X geteilte Links eine Rich-Vorschau zeigen. Ausschalten, wenn ein anderes Werkzeug dies bereits übernimmt.',
	'Save your settings first. A live check can take ~30&nbsp;seconds.' => 'Speichern Sie zuerst Ihre Einstellungen. Eine Live-Prüfung kann ~30&nbsp;Sekunden dauern.',
