	'Checked %s ago' => 'Vor %s geprüft',
	'Passed audits (%d)' => 'Bestandene Prüfungen (%d)',
	'Open on PageSpeed Insights &#8599;' => 'In PageSpeed Insights öffnen &#8599;',
	'Functions &amp; hooks' => 'Funktionen &amp; Hooks',
	'Print JavaScript before &lt;/body&gt; for the chosen location.' => 'JavaScript vor &lt;/body&gt; für den gewählten Ort ausgeben.',
	'PHP — Functions &amp; hooks' => 'PHP — Funktionen &amp; Hooks',
	'Risky' => 'Riskant',
	'Scan &amp; build (Cloudflare/Local)' => 'Scannen &amp; erstellen (Cloudflare/Lokal)',
	'Scan &amp; download fonts' => 'Schriftarten scannen &amp; herunterladen',
	'Quality &amp; processing' => 'Qualität &amp; Verarbeitung',
	'Find &amp; replace names' => 'Namen suchen &amp; ersetzen',
	'Media Editor — Alt text &amp; titles' => 'Medien-Editor — Alt-Text &amp; Titel',
	'Rename &amp; fix references' => 'Umbenennen &amp; Verweise korrigieren',
	'Keep the original proportions' => 'Die ursprünglichen Proportionen beibehalten',
	'Collapse menu' => 'Menü einklappen',
	'Detect &amp; recommend' => 'Erkennen &amp; empfehlen',
	'Unlock to edit this file' => 'Zum Bearbeiten dieser Datei entsperren',
	'%1$s tab → %2$s.' => '%1$s-Tab → %2$s.',
	'%1$s turns on only the optimizations that can\'t break a site. %2$s adds async CSS, unused-CSS removal (auto-learn), JS delay and bloat removal — then test and exclude anything that misbehaves. Neither touches jQuery Migrate or content-visibility (those need per-site testing).' => '%1$s aktiviert nur die Optimierungen, die eine Website nicht beschädigen können. %2$s fügt asynchrones CSS, das Entfernen ungenutzten CSS (automatisches Lernen), JS-Verzögerung und das Entfernen von überflüssigem Code hinzu — testen Sie anschließend und schließen Sie alles aus, was sich fehlerhaft verhält. Keines von beiden berührt jQuery Migrate oder content-visibility (diese erfordern Tests pro Website).',
	'Both devices are checked &mdash; this is just the one shown first on the dashboard.' => 'Beide Geräte werden geprüft &mdash; dies ist lediglich das zuerst im Dashboard angezeigte.',
	'Browse and edit your site\'s files, like SFTP or the Plesk file manager. Changes write straight to the server &mdash; there is no undo.' => 'Durchsuchen und bearbeiten Sie die Dateien Ihrer Website, wie mit SFTP oder dem Plesk-Dateimanager. Änderungen werden direkt auf den Server geschrieben &mdash; es gibt kein Rückgängigmachen.',
	'By default, deleting the plugin wipes Velox&rsquo;s settings, forms, redirects and logs. Turn this on to leave everything in place so a reinstall picks up where you left off. Your media is never touched either way.' => 'Standardmäßig werden beim Löschen des Plugins die Einstellungen, Formulare, Weiterleitungen und Protokolle von Velox gelöscht. Aktivieren Sie dies, um alles zu erhalten, sodass eine Neuinstallation dort fortfährt, wo Sie aufgehört haben. Ihre Medien werden in keinem Fall berührt.',
	'Everything&rsquo;s tuned. Nice work &mdash; your key optimizations are all on.' => 'Alles ist optimiert. Gut gemacht &mdash; Ihre wichtigsten Optimierungen sind alle aktiviert.',
	'Footer HTML, also embeddable with [velox_snippet id="…"].' => 'Footer-HTML, auch einbettbar mit [velox_snippet id="…"].',
	'No extension needed. Spaces &amp; caps become kebab-case. All thumbnail sizes and WebP twins are renamed too.' => 'Keine Erweiterung erforderlich. Leerzeichen &amp; Großbuchstaben werden zu Kebab-Case. Alle Miniaturgrößen und WebP-Zwillinge werden ebenfalls umbenannt.',
	'No report yet. Running a check tests both Mobile and Desktop across all categories &mdash; it takes about a minute.' => 'Noch kein Bericht. Bei einer Prüfung werden Mobil und Desktop über alle Kategorien hinweg getestet &mdash; das dauert etwa eine Minute.',
	'That\'s %1$s serving its own robots.txt at the edge, which overrides this. Fix it in your Cloudflare dashboard: %2$s. Writing a physical file here also helps, since Cloudflare only injects when your origin has no robots.txt.' => 'Das ist %1$s, das seine eigene robots.txt am Edge ausliefert und dies überschreibt. Beheben Sie es in Ihrem Cloudflare-Dashboard: %2$s. Das Schreiben einer physischen Datei hier hilft ebenfalls, da Cloudflare nur dann einfügt, wenn Ihr Ursprung keine robots.txt hat.',
	'These active plugins overlap features Velox already handles. Two plugins doing the same job tend to fight over the same output &mdash; keep one.' => 'Diese aktiven Plugins überschneiden sich mit Funktionen, die Velox bereits übernimmt. Zwei Plugins, die dieselbe Aufgabe erledigen, geraten oft über dieselbe Ausgabe in Konflikt &mdash; behalten Sie nur eines.',
	'Tick the images you want, then download. Alt text &amp; titles come along in a text file.' => 'Markieren Sie die gewünschten Bilder und laden Sie sie dann herunter. Alt-Text &amp; Titel werden in einer Textdatei mitgeliefert.',
	'Velox can count page views with a tiny first-party script &mdash; no cookies, no raw IP stored (visitors are de-duped with a salted daily hash), bots and logged-in admins excluded. Powers the Visitors widget on the dashboard. Turn it off and nothing is collected.' => 'Velox kann Seitenaufrufe mit einem winzigen First-Party-Skript zählen &mdash; keine Cookies, keine Speicherung roher IP-Adressen (Besucher werden mit einem gesalzenen Tages-Hash entdupliziert), Bots und angemeldete Administratoren ausgeschlossen. Versorgt das Besucher-Widget im Dashboard. Schalten Sie es aus und es wird nichts erfasst.',
	'Velox is serving the clean robots.txt shown in the editor above. Cloudflare adds the signals block at the edge, so no WordPress plugin can remove it. To turn it off: open your Cloudflare dashboard → select this domain → %1$s (older accounts: %2$s) → switch off %3$s / managed robots.txt, then come back and click %4$s again.' => 'Velox liefert die saubere robots.txt aus, die oben im Editor angezeigt wird. Cloudflare fügt den Signalblock am Edge hinzu, sodass kein WordPress-Plugin ihn entfernen kann. Zum Deaktivieren: Öffnen Sie Ihr Cloudflare-Dashboard → wählen Sie diese Domain → %1$s (ältere Konten: %2$s) → deaktivieren Sie %3$s / verwaltete robots.txt, kommen Sie dann zurück und klicken Sie erneut auf %4$s.',
	'your zone → AI Crawl Control / Bots → uncheck "Display Content Signals Policy" / managed robots.txt' => 'Ihre Zone → AI Crawl Control / Bots → „Display Content Signals Policy“ / verwaltete robots.txt deaktivieren',
