	'Preload — only the weights above the fold' => 'Vorladen — nur die Schnitte im sichtbaren Bereich',
	'Preloading everything is the same as preloading nothing. Pick the one or two weights your first screen actually uses.' => 'Alles vorzuladen ist dasselbe wie nichts vorzuladen. Wählen Sie die ein oder zwei Schnitte, die Ihr erster Bildschirm wirklich nutzt.',
	'Font files — one per weight' => 'Schriftdateien — eine pro Schnitt',
	'Upload .woff2 files to the media library and pick them here. Velox writes the @font-face rules for you.' => 'Laden Sie .woff2-Dateien in die Mediathek und wählen Sie sie hier. Velox schreibt die @font-face-Regeln für Sie.',
	'Every extra weight is another file the visitor downloads, so tick only what you use.' => 'Jeder zusätzliche Schnitt ist eine weitere Datei für den Besucher — haken Sie nur an, was Sie verwenden.',
	'fallback — brief block, then fallback' => 'fallback — kurz blockieren, dann Ersatzschrift',
	'A template is the frame around your pages — navbar, footer, anything shared. Each one says what it is for, and the page content drops into its Inner Content element.' => 'Eine Vorlage ist der Rahmen um Ihre Seiten — Navigation, Footer, alles Gemeinsame. Jede sagt, wofür sie da ist, und der Seiteninhalt landet in ihrem Element „Innerer Inhalt“.',
	'Your templates' => 'Ihre Vorlagen',
	'When more than one could apply, the most specific wins: Front page beats Pages, which beats Catch-all.' => 'Wenn mehrere passen, gewinnt die spezifischste: Startseite schlägt Seiten, Seiten schlägt Auffangvorlage.',
	'Create one to share a navbar and footer across your pages.' => 'Erstellen Sie eine, um Navigation und Footer über alle Seiten zu teilen.',
