	'Invalid template purpose.' => 'Ungültiger Vorlagenzweck.',
	'The template starts with an Inner Content element already in place — that is the slot each page renders into. Add your navbar above it and your footer below.' => 'Die Vorlage enthält bereits ein Element „Innerer Inhalt“ — das ist der Platz, an dem jede Seite gerendert wird. Fügen Sie Ihre Navigation darüber und den Footer darunter ein.',
