	'Upload a file' => 'Eine Datei hochladen',
	'Use SES SMTP credentials, not your AWS keys.' => 'Verwenden Sie SES-SMTP-Anmeldedaten, nicht Ihre AWS-Schlüssel.',
	'Use file' => 'Datei verwenden',
	'User' => 'Benutzer',
	'Username + Password = the SES SMTP credentials you just created.' => 'Benutzername + Passwort = die SES-SMTP-Anmeldedaten, die Sie gerade erstellt haben.',
	'Username = the literal word apikey. Password = your API key.' => 'Benutzername = das wörtliche Wort apikey. Passwort = Ihr API-Schlüssel.',
	'Username = your Brevo account email, password = your SMTP key (SMTP & API settings).' => 'Benutzername = Ihre Brevo-Konto-E-Mail, Passwort = Ihr SMTP-Schlüssel (SMTP- & API-Einstellungen).',
	'Username = your Brevo account email. Password = the SMTP key.' => 'Benutzername = Ihre Brevo-Konto-E-Mail. Passwort = der SMTP-Schlüssel.',
	'Username = your Mailgun SMTP login, password = its SMTP password (from Domain settings).' => 'Benutzername = Ihr Mailgun-SMTP-Login, Passwort = dessen SMTP-Passwort (aus den Domain-Einstellungen).',
	'Username = your Zoho email, password = an app-specific password.' => 'Benutzername = Ihre Zoho-E-Mail, Passwort = ein anwendungsspezifisches Passwort.',
	'Username = your Zoho email. Password = the app-specific password.' => 'Benutzername = Ihre Zoho-E-Mail. Passwort = das anwendungsspezifische Passwort.',
	'Username = your email address, password = your account or app password.' => 'Benutzername = Ihre E-Mail-Adresse, Passwort = Ihr Konto- oder App-Passwort.',
	'Username = your full GMX address. Password = your normal GMX password.' => 'Benutzername = Ihre vollständige GMX-Adresse. Passwort = Ihr normales GMX-Passwort.',
	'Username = your full Gmail address.' => 'Benutzername = Ihre vollständige Gmail-Adresse.',
	'Username = your full web.de address. Password = your normal password.' => 'Benutzername = Ihre vollständige web.de-Adresse. Passwort = Ihr normales Passwort.',
	'Username AND Password = your Server API Token (the same value in both).' => 'Benutzername UND Passwort = Ihr Server-API-Token (derselbe Wert in beiden).',
	'Username and password are both your Postmark Server API token.' => 'Benutzername und Passwort sind beide Ihr Postmark-Server-API-Token.',
	'Uses an app-specific password.' => 'Verwendet ein anwendungsspezifisches Passwort.',
