	'Using page defaults' => 'Seitenstandards werden verwendet',
	'Using the page title' => 'Der Seitentitel wird verwendet',
	'Advanced' => 'Erweitert',
	'Error Logger' => 'Fehler-Logger',
	'Every PHP error, fatal and failed API request as it happens — grouped by type, each with what it means and how to fix it. Turn it on and errors show up here from that point forward.' => 'Jeder PHP-Fehler, jeder schwerwiegende Fehler und jede fehlgeschlagene API-Anfrage in Echtzeit — nach Typ gruppiert, jeweils mit einer Erklärung und einer Anleitung zur Behebung. Schalten Sie ihn ein, und Fehler erscheinen ab diesem Zeitpunkt hier.',
	'Log errors' => 'Fehler protokollieren',
	'Clear all' => 'Alle löschen',
	'Logging is off. Flip it on to start catching errors from this point forward.' => 'Die Protokollierung ist aus. Schalten Sie sie ein, um ab jetzt Fehler zu erfassen.',
	'No errors logged.' => 'Keine Fehler protokolliert.',
	'Nothing has gone wrong since you switched this on. New errors will appear here, newest first.' => 'Seit dem Einschalten ist nichts schiefgelaufen. Neue Fehler erscheinen hier, die neuesten zuerst.',
	'%d distinct error logged. Click one to see what it means and how to fix it.' => '%d eindeutiger Fehler protokolliert. Klicken Sie auf einen, um zu sehen, was er bedeutet und wie man ihn behebt.',
	'%d distinct errors logged. Click one to see what it means and how to fix it.' => '%d eindeutige Fehler protokolliert. Klicken Sie auf einen, um zu sehen, was er bedeutet und wie man ihn behebt.',
	'Fatal errors' => 'Schwerwiegende Fehler',
	'Errors that stop a request completely — the usual cause of a white screen or broken page.' => 'Fehler, die eine Anfrage vollständig stoppen — die übliche Ursache für einen weißen Bildschirm oder eine defekte Seite.',
	'PHP warnings & notices' => 'PHP-Warnungen & -Hinweise',
	'Non-fatal PHP messages. The page still loads, but these can point at bugs in a plugin or theme.' => 'Nicht schwerwiegende PHP-Meldungen. Die Seite lädt weiterhin, aber diese können auf Fehler in einem Plugin oder Theme hinweisen.',
	'API & HTTP errors' => 'API- & HTTP-Fehler',
	'Outgoing requests to other servers that failed or came back with an error status.' => 'Ausgehende Anfragen an andere Server, die fehlgeschlagen sind oder mit einem Fehlerstatus zurückkamen.',
	'Where' => 'Wo',
	'Seen' => 'Gesehen',
	'first %1$s, last %2$s' => 'zuerst %1$s, zuletzt %2$s',
	'What it is' => 'Was es ist',
	'How to fix it' => 'So beheben Sie es',
	'Dismiss this error' => 'Diesen Fehler verwerfen',
	'just now' => 'gerade eben',
	'%s ago' => 'vor %s',
	'Outgoing request failed' => 'Ausgehende Anfrage fehlgeschlagen',
	'WordPress tried to reach another server and the connection itself failed — before any HTTP status came back.' => 'WordPress hat versucht, einen anderen Server zu erreichen, und die Verbindung selbst ist fehlgeschlagen — bevor ein HTTP-Status zurückkam.',
	'Usually a DNS, firewall or timeout issue. Check the host is reachable from your server, that outbound connections aren’t blocked, and that any API key or URL is correct. If it’s a loopback to your own site, your host may be blocking server-to-self requests.' => 'Normalerweise ein DNS-, Firewall- oder Timeout-Problem. Prüfen Sie, ob der Host von Ihrem Server erreichbar ist, ob ausgehende Verbindungen nicht blockiert werden und ob API-Schlüssel oder URL korrekt sind. Bei einem Loopback zur eigenen Website blockiert Ihr Host möglicherweise Server-zu-sich-selbst-Anfragen.',
	'Request rejected (auth)' => 'Anfrage abgelehnt (Authentifizierung)',
	'The remote server refused the request with a %d — an authentication or permission problem.' => 'Der entfernte Server hat die Anfrage mit einem %d abgelehnt — ein Authentifizierungs- oder Berechtigungsproblem.',
	'Check the API key, token or credentials for that service, and that they haven’t expired or lost the required scope.' => 'Prüfen Sie den API-Schlüssel, das Token oder die Anmeldedaten für diesen Dienst und ob sie nicht abgelaufen sind oder den erforderlichen Geltungsbereich verloren haben.',
	'Remote endpoint not found (404)' => 'Entfernter Endpunkt nicht gefunden (404)',
	'The URL WordPress requested doesn’t exist on the remote server.' => 'Die von WordPress angeforderte URL existiert auf dem entfernten Server nicht.',
	'Verify the endpoint URL is correct and current — an API may have moved or changed its version path.' => 'Prüfen Sie, ob die Endpunkt-URL korrekt und aktuell ist — eine API könnte umgezogen sein oder ihren Versionspfad geändert haben.',
	'Rate limited (429)' => 'Ratenbegrenzung (429)',
	'The remote service is throttling your requests because too many arrived too fast.' => 'Der entfernte Dienst drosselt Ihre Anfragen, weil zu viele zu schnell eingegangen sind.',
	'Slow the request rate, add caching so you call the API less often, or upgrade the plan/quota with that provider.' => 'Verringern Sie die Anfragerate, fügen Sie Caching hinzu, um die API seltener aufzurufen, oder erweitern Sie Tarif/Kontingent bei diesem Anbieter.',
	'Remote server error (%d)' => 'Fehler des entfernten Servers (%d)',
	'The other server had an internal problem — this is on their end, not yours.' => 'Der andere Server hatte ein internes Problem — das liegt an dessen Seite, nicht an Ihrer.',
	'Usually temporary. Retry later; if it persists, check that provider’s status page or contact them.' => 'Meist vorübergehend. Versuchen Sie es später erneut; wenn es weiterhin auftritt, prüfen Sie die Statusseite des Anbieters oder kontaktieren Sie ihn.',
	'HTTP error (%d)' => 'HTTP-Fehler (%d)',
	'An outgoing request returned an error status.' => 'Eine ausgehende Anfrage hat einen Fehlerstatus zurückgegeben.',
	'Check the request URL and parameters for that service.' => 'Prüfen Sie die Anfrage-URL und die Parameter für diesen Dienst.',
	'Out of memory' => 'Nicht genügend Arbeitsspeicher',
	'A script tried to use more memory than PHP allows, so it was killed mid-run.' => 'Ein Skript hat versucht, mehr Speicher zu verwenden, als PHP erlaubt, und wurde daher mitten im Lauf beendet.',
	'Raise the PHP memory limit (WP_MEMORY_LIMIT in wp-config.php, or php.ini), and look at whichever plugin/theme is named in the file path — it may be loading too much at once.' => 'Erhöhen Sie das PHP-Speicherlimit (WP_MEMORY_LIMIT in wp-config.php oder php.ini) und sehen Sie sich das im Dateipfad genannte Plugin/Theme an — es lädt möglicherweise zu viel auf einmal.',
	'Script timed out' => 'Zeitüberschreitung des Skripts',
	'A script ran longer than the allowed time limit and PHP stopped it.' => 'Ein Skript lief länger als das erlaubte Zeitlimit und PHP hat es gestoppt.',
	'Increase max_execution_time, or fix the slow operation (a heavy query, an external API with no timeout, or an import running on the main request).' => 'Erhöhen Sie max_execution_time oder beheben Sie den langsamen Vorgang (eine aufwändige Abfrage, eine externe API ohne Timeout oder einen Import, der auf der Hauptanfrage läuft).',
	'Missing function or method' => 'Fehlende Funktion oder Methode',
	'Code called something that doesn’t exist — usually a plugin was updated, deactivated, or a required library isn’t loaded.' => 'Code hat etwas aufgerufen, das nicht existiert — normalerweise wurde ein Plugin aktualisiert, deaktiviert oder eine benötigte Bibliothek ist nicht geladen.',
	'Check the plugin/theme named in the file path is active and up to date. If it appeared right after an update, roll that update back and report it to the author.' => 'Prüfen Sie, ob das im Dateipfad genannte Plugin/Theme aktiv und aktuell ist. Wenn es direkt nach einem Update auftrat, machen Sie dieses Update rückgängig und melden Sie es dem Autor.',
	'Undefined value' => 'Undefinierter Wert',
	'Code read a variable, array key or property that was never set. Often harmless, but it can hint at a logic bug.' => 'Code hat eine Variable, einen Array-Schlüssel oder eine Eigenschaft gelesen, die nie gesetzt wurde. Oft harmlos, kann aber auf einen Logikfehler hinweisen.',
	'Usually safe to ignore if the page still works. If it’s from a plugin/theme, update it; the author should guard the value with isset() before using it.' => 'Meist unbedenklich zu ignorieren, wenn die Seite noch funktioniert. Wenn es von einem Plugin/Theme stammt, aktualisieren Sie es; der Autor sollte den Wert vor der Verwendung mit isset() absichern.',
	'Value was not what code expected' => 'Wert war nicht, was der Code erwartet hat',
	'Code treated something as an array or object when it was actually null or a boolean — often a failed lookup that returned nothing.' => 'Code hat etwas als Array oder Objekt behandelt, obwohl es tatsächlich null oder ein Boolescher Wert war — oft eine fehlgeschlagene Suche, die nichts zurückgab.',
	'Update the plugin/theme named in the path. It usually means an earlier step returned nothing and the result wasn’t checked before use.' => 'Aktualisieren Sie das im Pfad genannte Plugin/Theme. Es bedeutet meist, dass ein früherer Schritt nichts zurückgab und das Ergebnis vor der Verwendung nicht geprüft wurde.',
	'Headers already sent' => 'Header bereits gesendet',
	'Something printed output (often a stray space or a notice) before WordPress tried to send HTTP headers — this breaks redirects and cookies.' => 'Etwas hat Ausgabe erzeugt (oft ein überflüssiges Leerzeichen oder ein Hinweis), bevor WordPress versuchte, HTTP-Header zu senden — das bricht Weiterleitungen und Cookies.',
	'Find the file/line named as the output source: usually whitespace after a closing ?> tag, or an error being printed. Remove trailing blank lines from that file.' => 'Finden Sie die als Ausgabequelle genannte Datei/Zeile: meist Leerzeichen nach einem schließenden ?>-Tag oder ein ausgegebener Fehler. Entfernen Sie nachfolgende Leerzeilen aus dieser Datei.',
	'PHP syntax error' => 'PHP-Syntaxfehler',
	'A file has invalid PHP and can’t be parsed — this usually takes the whole site down (white screen).' => 'Eine Datei enthält ungültiges PHP und kann nicht verarbeitet werden — das legt meist die ganze Website lahm (weißer Bildschirm).',
	'Open the file at the exact line shown and fix the syntax (often a missing semicolon, bracket or quote). If it came from an edit or a snippet, undo that change.' => 'Öffnen Sie die Datei an der angezeigten Zeile und korrigieren Sie die Syntax (oft ein fehlendes Semikolon, eine Klammer oder ein Anführungszeichen). Wenn es von einer Bearbeitung oder einem Snippet kam, machen Sie diese Änderung rückgängig.',
	'Deprecated code' => 'Veralteter Code',
	'A plugin or theme is using something PHP or WordPress plans to remove. It still works today but will break on a future update.' => 'Ein Plugin oder Theme verwendet etwas, das PHP oder WordPress entfernen möchte. Es funktioniert heute noch, wird aber bei einem zukünftigen Update brechen.',
	'Not urgent. Update the plugin/theme named in the path to a version that no longer uses the old code. If you’re on a new PHP version, the author may not have caught up yet.' => 'Nicht dringend. Aktualisieren Sie das im Pfad genannte Plugin/Theme auf eine Version, die den alten Code nicht mehr verwendet. Wenn Sie eine neue PHP-Version nutzen, ist der Autor möglicherweise noch nicht nachgezogen.',
	'Fatal error' => 'Schwerwiegender Fehler',
	'A fatal error stops the current request completely — often the cause of a white screen or a broken page.' => 'Ein schwerwiegender Fehler stoppt die aktuelle Anfrage vollständig — oft die Ursache für einen weißen Bildschirm oder eine defekte Seite.',
	'Look at the file and line named. If it points at a plugin or theme, deactivate that one to confirm, then update or replace it. Enabling WP_DEBUG_LOG gives a fuller stack trace.' => 'Sehen Sie sich die genannte Datei und Zeile an. Wenn sie auf ein Plugin oder Theme verweist, deaktivieren Sie dieses zur Bestätigung und aktualisieren oder ersetzen Sie es dann. Das Aktivieren von WP_DEBUG_LOG liefert einen ausführlicheren Stack-Trace.',
	'PHP notice' => 'PHP-Hinweis',
	'A low-severity message from PHP. The page usually still works, but it can point at a small bug in a plugin or theme.' => 'Eine Meldung von PHP mit geringem Schweregrad. Die Seite funktioniert meist noch, kann aber auf einen kleinen Fehler in einem Plugin oder Theme hinweisen.',
	'Safe to ignore if everything works. If it’s frequent and from one plugin/theme, updating it usually clears it.' => 'Kann ignoriert werden, wenn alles funktioniert. Wenn es häufig auftritt und von einem Plugin/Theme stammt, behebt ein Update es meist.',
	'Error log cleared.' => 'Fehlerprotokoll gelöscht.',
	'Entry removed.' => 'Eintrag entfernt.',
	'Clear the entire error log?' => 'Das gesamte Fehlerprotokoll löschen?',
	'Could not clear.' => 'Konnte nicht gelöscht werden.',
	'Could not remove.' => 'Konnte nicht entfernt werden.',
	'Every email your site sends is logged here — contact forms, password resets, new-user notices, WooCommerce receipts and anything other plugins send — so you can see what went out and what failed.' => 'Jede E-Mail, die Ihre Website versendet, wird hier protokolliert — Kontaktformulare, Passwort-Zurücksetzungen, Benachrichtigungen über neue Benutzer, WooCommerce-Belege und alles, was andere Plugins senden — damit Sie sehen, was rausging und was fehlschlug.',
	'Alert me when a send fails' => 'Benachrichtigen, wenn ein Versand fehlschlägt',
	'— emails the site admin (at most once per hour).' => '— sendet eine E-Mail an den Website-Administrator (höchstens einmal pro Stunde).',
	'WordPress default' => 'WordPress-Standard',
	'[%s] An email failed to send' => '[%s] Eine E-Mail konnte nicht gesendet werden',
	'Velox detected that an outgoing email failed to send.' => 'Velox hat festgestellt, dass eine ausgehende E-Mail nicht gesendet werden konnte.',
	'Error' => 'Fehler',
	'See the full email log under Velox → Mail & forms.' => 'Das vollständige E-Mail-Protokoll finden Sie unter Velox → E-Mail & Formulare.',
	'AI crawlers' => 'KI-Crawler',
	'Decide which AI bots may crawl your site. Choices here are added to your robots.txt automatically — no need to hand-edit the block above. Well-behaved crawlers honour these rules; they are a request, not a hard block.' => 'Legen Sie fest, welche KI-Bots Ihre Website crawlen dürfen. Die Auswahl hier wird automatisch zu Ihrer robots.txt hinzugefügt — kein manuelles Bearbeiten des Blocks oben nötig. Gut funktionierende Crawler halten sich an diese Regeln; sie sind eine Bitte, keine harte Sperre.',
	'Block this group' => 'Diese Gruppe blockieren',
	'Allowed' => 'Erlaubt',
	'Tip: most sites allow AI search crawlers (visibility in AI answers) but may block training crawlers. Blocking on-demand fetchers can stop your pages being summarised when someone shares your link.' => 'Tipp: Die meisten Websites erlauben KI-Suchcrawler (Sichtbarkeit in KI-Antworten), blockieren aber möglicherweise Trainings-Crawler. Das Blockieren von On-Demand-Abrufern kann verhindern, dass Ihre Seiten zusammengefasst werden, wenn jemand Ihren Link teilt.',
	'Serves a %s — a plain-text map of your key pages that AI tools can read to understand your site. Auto-generated from your pages; edit it if you want. Note: Google has said it ignores llms.txt, so this is for the AI systems that do read it, not a Google-ranking boost.' => 'Stellt eine %s bereit — eine Klartext-Übersicht Ihrer wichtigsten Seiten, die KI-Tools lesen können, um Ihre Website zu verstehen. Automatisch aus Ihren Seiten generiert; bei Bedarf bearbeitbar. Hinweis: Google hat erklärt, dass es llms.txt ignoriert — dies ist also für die KI-Systeme, die sie lesen, kein Google-Ranking-Vorteil.',
	'Leave blank to auto-generate from your pages…' => 'Leer lassen, um automatisch aus Ihren Seiten zu generieren…',
	'Save llms.txt' => 'llms.txt speichern',
	'Regenerate from pages' => 'Aus Seiten neu generieren',
	'View live llms.txt' => 'Live-llms.txt ansehen',
	'AI training crawlers' => 'KI-Trainings-Crawler',
	'Collect content to train AI models. Block these if you don’t want your content used as training data.' => 'Sammeln Inhalte, um KI-Modelle zu trainieren. Blockieren Sie diese, wenn Sie nicht möchten, dass Ihre Inhalte als Trainingsdaten verwendet werden.',
	'AI search crawlers' => 'KI-Suchcrawler',
	'Index your site so it can appear in AI answers (ChatGPT Search, Perplexity, etc.). Most sites want these allowed for visibility.' => 'Indexieren Ihre Website, damit sie in KI-Antworten erscheinen kann (ChatGPT Search, Perplexity usw.). Die meisten Websites möchten diese für die Sichtbarkeit erlauben.',
	'On-demand fetchers' => 'On-Demand-Abrufer',
	'Fetch a page only when a user pastes or asks about its link. Blocking these can stop your pages being summarised on request.' => 'Rufen eine Seite nur ab, wenn ein Nutzer ihren Link einfügt oder danach fragt. Das Blockieren kann verhindern, dass Ihre Seiten auf Anfrage zusammengefasst werden.',
	'AI group blocked.' => 'KI-Gruppe blockiert.',
	'AI group allowed.' => 'KI-Gruppe erlaubt.',
	'llms.txt enabled.' => 'llms.txt aktiviert.',
	'llms.txt disabled.' => 'llms.txt deaktiviert.',
	'llms.txt saved.' => 'llms.txt gespeichert.',
	'Regenerated from your pages.' => 'Aus Ihren Seiten neu generiert.',
	'You can also upload an %1$s backup (%2$s). Velox unpacks it and rewrites the old site’s address to this one automatically, so it works on this domain.' => 'Sie können auch ein %1$s-Backup (%2$s) hochladen. Velox entpackt es und schreibt die Adresse der alten Website automatisch auf diese um, damit es auf dieser Domain funktioniert.',
	'All-in-One WP Migration' => 'All-in-One WP Migration',
