	'The .wpress file could not be read.' => 'Die .wpress-Datei konnte nicht gelesen werden.',
	'PHP-zip is unavailable on this server, so .wpress files cannot be imported.' => 'PHP-Zip ist auf diesem Server nicht verfügbar, daher können .wpress-Dateien nicht importiert werden.',
	'Could not create a temporary folder for the import.' => 'Für den Import konnte kein temporärer Ordner erstellt werden.',
	'This .wpress backup has no database.sql inside it, so it can’t be imported.' => 'Dieses .wpress-Backup enthält keine database.sql und kann daher nicht importiert werden.',
