	'Webmaster verification' => 'Webmaster-Verifizierung',
	'Verify site ownership with search engines and other tools. Paste either the verification ID/token or the full <meta> tag they give you — Velox extracts the token and outputs a clean tag in your site’s <head>.' => 'Bestätigen Sie den Website-Besitz bei Suchmaschinen und anderen Tools. Fügen Sie entweder die Verifizierungs-ID/den Token oder das vollständige <meta>-Tag ein — Velox extrahiert den Token und gibt ein sauberes Tag im <head> Ihrer Website aus.',
