	'Your cart is empty.' => 'Ihr Warenkorb ist leer.',
	'Thank you — your order is in.' => 'Vielen Dank — Ihre Bestellung ist eingegangen.',
	'Reference %s. We will email you payment details before anything ships.' => 'Referenz %s. Wir senden Ihnen die Zahlungsdaten per E-Mail, bevor etwas versendet wird.',
	'Delivery address' => 'Lieferadresse',
	'Anything we should know?' => 'Gibt es etwas, das wir wissen sollten?',
	'No card details are taken here. We confirm the order first and send payment details by email.' => 'Hier werden keine Kartendaten erfasst. Wir bestätigen die Bestellung und senden die Zahlungsdaten per E-Mail.',
	'Place order' => 'Bestellung abschicken',
	'Forgotten your password?' => 'Passwort vergessen?',
	'Create an account' => 'Konto erstellen',
	'Signed in as %s.' => 'Angemeldet als %s.',
	'Sign out' => 'Abmelden',
	'No orders yet.' => 'Noch keine Bestellungen.',
	'Awaiting payment' => 'Zahlung ausstehend',
	'Paid' => 'Bezahlt',
	'Shipped' => 'Versendet',
	'Cancelled' => 'Storniert',
	'Price' => 'Preis',
	'Availability' => 'Verfügbarkeit',
	'Dimensions' => 'Masse',
	'State' => 'Status',
	'Customer' => 'Kunde',
	'Work details' => 'Angaben zum Werk',
	'Year' => 'Jahr',
	'Enable shop' => 'Shop aktivieren',
	'Adds a Products area to the admin menu, with Orders beneath it.' => 'Fügt einen Bereich „Werke“ im Menü hinzu, mit „Bestellungen“ darunter.',
	'What this deliberately does not do' => 'Was bewusst nicht passiert',
	'No card details are taken or stored anywhere in Velox. Placing an order records it and emails both sides; you agree payment out of band. A real payment provider belongs behind a redirect and can be added later without changing anything here.' => 'In Velox werden keine Kartendaten erfasst oder gespeichert. Eine Bestellung wird aufgezeichnet und beiden Seiten per E-Mail bestätigt; die Zahlung vereinbaren Sie separat. Ein echter Zahlungsanbieter gehört hinter eine Weiterleitung und lässt sich später ergänzen.',
	'Customer accounts are ordinary WordPress users. Sign-in, registration and password resets all use WordPress itself, so no second set of credentials exists to be leaked.' => 'Kundenkonten sind gewöhnliche WordPress-Benutzer. Anmeldung, Registrierung und Passwort-Zurücksetzen laufen über WordPress selbst — es gibt keine zweiten Zugangsdaten, die verloren gehen könnten.',
	'Currency symbol' => 'Währungssymbol',
	'Symbol position' => 'Position des Symbols',
	'After the amount — 149 €' => 'Hinter dem Betrag — 149 €',
	'Before the amount — € 149' => 'Vor dem Betrag — € 149',
	'Putting it on a page' => 'Einbinden auf einer Seite',
	'Four shortcodes. Drop them into a Velox Builder text element or any page.' => 'Vier Shortcodes. Einfach in ein Velox-Builder-Textelement oder eine beliebige Seite einfügen.',
	'The catalogue grid' => 'Das Werkraster',
	'Current cart contents' => 'Aktueller Warenkorb',
	'Checkout form and the thank-you state' => 'Kasse und Bestätigungsansicht',
	'Sign in, and order history once signed in' => 'Anmeldung und Bestellübersicht nach dem Anmelden',
	'Published works' => 'Veröffentlichte Werke',
	'Add a work' => 'Werk hinzufügen',
	'View orders' => 'Bestellungen ansehen',
	'Sell individual works: a catalogue with prices and availability, a cart, orders and a customer account area.' => 'Einzelne Werke verkaufen: ein Katalog mit Preisen und Verfügbarkeit, ein Warenkorb, Bestellungen und ein Kundenbereich.',
	'Shop' => 'Shop',
	'Login protection' => 'Anmeldeschutz',
	'Block an address after repeated failed sign-ins, until you let it back in.' => 'Eine Adresse nach wiederholt fehlgeschlagenen Anmeldungen sperren, bis Sie sie wieder freigeben.',
	'Enable' => 'Aktivieren',
	'Block after this many failures' => 'Sperren nach so vielen Fehlversuchen',
	'Counted per address. A successful sign-in resets the count.' => 'Wird je Adresse gezählt. Eine erfolgreiche Anmeldung setzt den Zähler zurück.',
	'Email me when an address is blocked' => 'Bei einer Sperre eine E-Mail senden',
	'The email carries a one-click unlock link, so you can never be shut out of your own site by this.' => 'Die E-Mail enthält einen Freigabe-Link, damit Sie sich hiermit nie selbst aussperren können.',
	'This site sits behind a proxy or CDN' => 'Diese Website läuft hinter einem Proxy oder CDN',
	'Only switch this on if it is true. It makes Velox trust the forwarded-address header — and on a site that is not behind a proxy, anyone could forge that header and dodge every block.' => 'Nur aktivieren, wenn es zutrifft. Velox vertraut dann dem weitergeleiteten Adress-Header — ohne Proxy könnte jeder diesen Header fälschen und jede Sperre umgehen.',
	'Blocked by address, not by account' => 'Gesperrt wird die Adresse, nicht das Konto',
	'Blocking an account after failed attempts would let anyone lock you out of your own site just by typing your username wrong a few times. Velox blocks where the attempts come from instead.' => 'Ein Konto zu sperren würde bedeuten, dass jeder Sie aus Ihrer eigenen Website aussperren kann, indem er Ihren Benutzernamen einige Male falsch eingibt. Velox sperrt stattdessen die Herkunft der Versuche.',
	'Blocked addresses' => 'Gesperrte Adressen',
	'Unlock all' => 'Alle freigeben',
	'Nothing is blocked.' => 'Nichts ist gesperrt.',
	'Attempts' => 'Versuche',
	'Username tried' => 'Versuchter Benutzername',
	'Unlock' => 'Freigeben',
	'<strong>Signing in is blocked from this address.</strong> There were %s failed attempts. An administrator has to unlock it before you can try again.' => '<strong>Die Anmeldung von dieser Adresse ist gesperrt.</strong> Es gab %s Fehlversuche. Ein Administrator muss die Adresse freigeben, bevor Sie es erneut versuchen können.',
	'Sign-ins to %1$s are now blocked from %2$s after %3$d failed attempts (last username tried: %4$s).

If that was you, unlock it here:
%5$s

The link works once and expires in 24 hours. You can also unlock it under Velox → Utilities → Login protection.
' => 'Anmeldungen bei %1$s sind von %2$s nach %3$d Fehlversuchen gesperrt (zuletzt versuchter Benutzername: %4$s).

Falls Sie das waren, hier freigeben:
%5$s

Der Link funktioniert einmal und läuft nach 24 Stunden ab. Sie können die Adresse auch unter Velox → Utilities → Anmeldeschutz freigeben.
',
	'Sign-in blocked from %s' => 'Anmeldung von %s gesperrt',
	'Address unlocked.' => 'Adresse freigegeben.',
	'Unlock every blocked address?' => 'Alle gesperrten Adressen freigeben?',
	'All addresses unlocked.' => 'Alle Adressen freigegeben.',

	/* Site scan */
	'WordPress.org publishes no checksums for %s, so the English list was used. Translation files are not covered by it.' => 'WordPress.org veröffentlicht keine Prüfsummen für %s, daher wurde die englische Liste verwendet. Übersetzungsdateien sind darin nicht enthalten.',
	'The checksums for your WordPress version could not be fetched, so core files were not verified. This is usually a blocked outbound connection rather than a problem with the site.' => 'Die Prüfsummen für Ihre WordPress-Version konnten nicht abgerufen werden, daher wurden die Kerndateien nicht überprüft. Meist liegt das an einer blockierten ausgehenden Verbindung und nicht an einem Problem der Website.',
	'A core file that should be here is gone.' => 'Eine Kerndatei, die hier sein sollte, fehlt.',
	'Could not be read, so it was not checked.' => 'Konnte nicht gelesen werden und wurde daher nicht geprüft.',
	'Does not match the file WordPress published for this version.' => 'Stimmt nicht mit der Datei überein, die WordPress für diese Version veröffentlicht hat.',
	'Not part of WordPress. This folder should hold nothing else.' => 'Gehört nicht zu WordPress. In diesem Ordner sollte nichts anderes liegen.',
	'The uploads folder could not be located, so it was not checked.' => 'Der Uploads-Ordner konnte nicht gefunden werden und wurde daher nicht geprüft.',
	'Uploads holds more than %s files, so the check stopped there. Everything past that point was not looked at.' => 'Uploads enthält mehr als %s Dateien, daher wurde die Prüfung dort beendet. Alles darüber hinaus wurde nicht angesehen.',
	'Runnable code in the media folder. Nothing legitimate puts it there.' => 'Ausführbarer Code im Medienordner. Nichts Legitimes legt ihn dort ab.',
	'A double extension hiding a code file. Some server setups will run it.' => 'Eine doppelte Dateiendung, die eine Code-Datei verbirgt. Manche Server-Konfigurationen führen sie aus.',
	'Changes how this folder is served. Some plugins add one legitimately — read it before removing it.' => 'Ändert, wie dieser Ordner ausgeliefert wird. Manche Plugins legen sie berechtigt an — lesen Sie sie, bevor Sie sie entfernen.',
	'Makes this folder run code. That is how an uploaded image becomes a back door.' => 'Lässt diesen Ordner Code ausführen. Genau so wird aus einem hochgeladenen Bild eine Hintertür.',
	'Changed' => 'Geändert',
	'Missing' => 'Fehlt',
	'Does not belong' => 'Gehört nicht hierher',
	'Code in uploads' => 'Code in Uploads',
	'Double extension' => 'Doppelte Endung',
	'Server rules' => 'Server-Regeln',
	'Unreadable' => 'Nicht lesbar',
	'Site scan' => 'Website-Prüfung',
	'Compares your WordPress core files against the ones WordPress.org published for your exact version, and checks the uploads folder for runnable code. Read what it does not check before you rely on it.' => 'Vergleicht Ihre WordPress-Kerndateien mit denen, die WordPress.org für genau Ihre Version veröffentlicht hat, und prüft den Uploads-Ordner auf ausführbaren Code. Lesen Sie, was nicht geprüft wird, bevor Sie sich darauf verlassen.',
	'Check your WordPress core files against the ones WordPress.org published for your version, and find runnable code hiding in the uploads folder. It does not pattern-match for malware, and says so plainly.' => 'Prüfen Sie Ihre WordPress-Kerndateien gegen die von WordPress.org für Ihre Version veröffentlichten und finden Sie ausführbaren Code, der sich im Uploads-Ordner versteckt. Es wird nicht nach Schadcode-Mustern gesucht — und das wird klar gesagt.',
	'Run scan' => 'Prüfung starten',
	'Last scanned %s ago.' => 'Zuletzt vor %s geprüft.',
	'Not scanned yet.' => 'Noch nicht geprüft.',
	'What this does not check' => 'Was hier nicht geprüft wird',
	'It does not read your files looking for malicious code. Searching for "known bad" patterns fails in both directions: ordinary minified or packed code sets it off constantly, so the report fills with alarms nobody can act on, and any infection not already on the list walks straight past — which is worse than no scan at all, because it feels like an all-clear.' => 'Ihre Dateien werden nicht nach Schadcode durchsucht. Die Suche nach „bekannt schlechten“ Mustern scheitert in beide Richtungen: Ganz normaler minifizierter oder gepackter Code löst sie ständig aus, sodass sich der Bericht mit Warnungen füllt, mit denen niemand etwas anfangen kann — und jede Infektion, die noch nicht auf der Liste steht, kommt ungehindert durch. Das ist schlimmer als gar keine Prüfung, weil es sich wie eine Entwarnung anfühlt.',
	'It also does not check your plugins, your theme or wp-content, because there is no published list of what those files are supposed to contain. A clean result here means your core files match and uploads holds no code. It is not proof that the site is uninfected.' => 'Ebenso wenig werden Ihre Plugins, Ihr Theme oder wp-content geprüft, denn für diese Dateien gibt es keine veröffentlichte Liste ihres Sollzustands. Ein sauberes Ergebnis bedeutet hier: Ihre Kerndateien stimmen überein und in Uploads liegt kein Code. Es ist kein Beweis dafür, dass die Website nicht infiziert ist.',
	'serious' => 'kritisch',
	'to look at' => 'anzusehen',
	'Nothing found' => 'Nichts gefunden',
	'%1$s core files matched, and %2$s files in uploads carried no runnable code.' => '%1$s Kerndateien stimmten überein, und %2$s Dateien in Uploads enthielten keinen ausführbaren Code.',
	'Why it is listed' => 'Warum aufgeführt',
	'A further %s were found and are not listed here. Deal with the ones above first, then scan again.' => 'Weitere %s wurden gefunden und sind hier nicht aufgeführt. Kümmern Sie sich zuerst um die obigen und prüfen Sie dann erneut.',
	'so far' => 'bisher',

	/* Sidebar groups and dashboard tiles */
	'Security' => 'Sicherheit',
	'Live scores' => 'Live-Werte',
	'Rating slider' => 'Bewertungs-Slider',
	'Frontend Tools' => 'Frontend-Werkzeuge',
	'Admin quick-panel' => 'Schnellzugriff für Admins',
	'PHP error log' => 'PHP-Fehlerprotokoll',
	'Block brute force' => 'Brute-Force blockieren',
	'Core & uploads' => 'Kern & Uploads',
	'Products & orders' => 'Produkte & Bestellungen',
	'Large images' => 'Große Bilder',
	'Every image above the limit you set — 1001 counts when the limit is 1000. Re-convert them smaller with the settings below; your saved Images settings stay as they are.' => 'Alle Bilder über dem von Ihnen gewählten Grenzwert – 1001 zählt, wenn der Grenzwert 1000 ist. Konvertieren Sie sie mit den Einstellungen unten kleiner; Ihre gespeicherten Bild-Einstellungen bleiben unverändert.',
	'No image engine (Imagick or GD with WebP) was found on this server, so images can be listed but not re-converted.' => 'Auf diesem Server wurde keine Bild-Engine (Imagick oder GD mit WebP) gefunden. Bilder können daher aufgelistet, aber nicht neu konvertiert werden.',
	'Show images' => 'Bilder anzeigen',
	'wider than' => 'breiter als',
	'taller than' => 'höher als',
	'bigger than' => 'größer als',
	'Limit' => 'Grenzwert',
	'Re-convert with' => 'Neu konvertieren mit',
	'Height follows. 0 keeps the size.' => 'Die Höhe passt sich an. 0 behält die Größe.',
	'75–85 looks identical for photos.' => '75–85 sieht bei Fotos identisch aus.',
	'Format' => 'Format',
	'This server cannot create AVIF files.' => 'Dieser Server kann keine AVIF-Dateien erstellen.',
	'WebP + AVIF' => 'WebP + AVIF',
	'Replace in media library' => 'In der Mediathek ersetzen',
	'Lossless' => 'Verlustfrei',
	'Keep EXIF' => 'EXIF behalten',
	'Re-convert selected' => 'Auswahl neu konvertieren',
	'Looking through your library…' => 'Mediathek wird durchsucht …',
	'Find large images →' => 'Große Bilder finden →',
	'Server rules for redirects, caching headers and access. One typo can take the whole site offline, so the editor stays locked until you open it — and locks itself again after 10 minutes.' => 'Serverregeln für Weiterleitungen, Caching-Header und Zugriffe. Ein einziger Tippfehler kann die ganze Website lahmlegen – deshalb bleibt der Editor gesperrt, bis Sie ihn öffnen, und sperrt sich nach 10 Minuten von selbst wieder.',
	'Locked' => 'Gesperrt',
	'Unlock for 10 minutes' => 'Für 10 Minuten entsperren',
	'Lock now' => 'Jetzt sperren',
	'This server does not look like Apache or LiteSpeed. If it runs on nginx alone, rules in .htaccess have no effect.' => 'Dieser Server scheint weder Apache noch LiteSpeed zu sein. Läuft er nur mit nginx, haben Regeln in der .htaccess keine Wirkung.',
	'Every save keeps the previous version and checks that your site still loads — if it doesn\'t, the old version is put back automatically.' => 'Jedes Speichern bewahrt die vorherige Version auf und prüft, ob Ihre Website noch lädt – falls nicht, wird automatisch die alte Version wiederhergestellt.',
	'Restore previous version' => 'Vorherige Version wiederherstellen',
	'Turn on Risky mode in Performance to edit .htaccess.' => 'Aktivieren Sie unter Performance den Risiko-Modus, um die .htaccess zu bearbeiten.',
	'File editing is switched off on this site (DISALLOW_FILE_EDIT in wp-config.php).' => 'Das Bearbeiten von Dateien ist auf dieser Website deaktiviert (DISALLOW_FILE_EDIT in der wp-config.php).',
	'WordPress is not allowed to write the .htaccess file on this server (file permissions).' => 'WordPress darf die .htaccess auf diesem Server nicht schreiben (Dateiberechtigungen).',
	'That is far too large for an .htaccess file — nothing was saved.' => 'Das ist viel zu groß für eine .htaccess – es wurde nichts gespeichert.',
	'No changes to save.' => 'Keine Änderungen zum Speichern.',
	'Could not write the .htaccess file. Nothing was changed.' => 'Die .htaccess konnte nicht geschrieben werden. Es wurde nichts geändert.',
	'Your change made the site return an error (HTTP %d), so Velox put the previous version back. Nothing is broken.' => 'Durch Ihre Änderung hat die Website einen Fehler geliefert (HTTP %d), daher hat Velox die vorherige Version wiederhergestellt. Es ist nichts kaputt.',
	'Saved. Velox could not load your home page to double-check it, so open the site in a new tab to make sure it still works.' => 'Gespeichert. Velox konnte Ihre Startseite zur Kontrolle nicht laden – öffnen Sie die Website in einem neuen Tab, um sicherzugehen, dass sie noch funktioniert.',
	'Saved — your site still loads fine.' => 'Gespeichert – Ihre Website lädt weiterhin einwandfrei.',
	'There is no earlier version to restore.' => 'Es gibt keine frühere Version zum Wiederherstellen.',
	'Previous version restored.' => 'Vorherige Version wiederhergestellt.',
	'The editor locked itself again. Unlock it to keep editing — your text is still in the box.' => 'Der Editor hat sich wieder gesperrt. Entsperren Sie ihn, um weiterzuarbeiten – Ihr Text ist noch im Feld.',
	'Only JPG, PNG and WebP images can be re-converted.' => 'Nur JPG-, PNG- und WebP-Bilder können neu konvertiert werden.',
	'Could not make a working copy of the image.' => 'Es konnte keine Arbeitskopie des Bildes erstellt werden.',
	'Unlocked · %s left' => 'Entsperrt · noch %s',
	'Put the previous version of .htaccess back?' => 'Die vorherige Version der .htaccess wiederherstellen?',
	'%s images · %s' => '%s Bilder · %s',
	'No images' => 'Keine Bilder',
	'Re-convert selected (%s)' => 'Auswahl neu konvertieren (%s)',
	'Select %s' => '%s auswählen',
	'no original kept' => 'kein Original vorhanden',
	'Re-convert' => 'Neu konvertieren',
	'Nothing above %s %s' => 'Nichts über %s %s',
	'Every image in your library is within this limit. Try a lower number to see more.' => 'Alle Bilder in Ihrer Mediathek liegen innerhalb dieses Grenzwerts. Versuchen Sie eine niedrigere Zahl, um mehr zu sehen.',
	'Retry' => 'Erneut versuchen',
	'Stopped after %s of %s.' => 'Nach %s von %s angehalten.',
	'Re-converted %s images.' => '%s Bilder neu konvertiert.',
	'Re-converted %s of %s — %s failed. Hover Retry to see why.' => '%s von %s neu konvertiert – %s fehlgeschlagen. Fahren Sie über „Erneut versuchen“, um den Grund zu sehen.',
	'On a multisite network only a network administrator can edit .htaccess.' => 'In einem Multisite-Netzwerk kann nur ein Netzwerk-Administrator die .htaccess bearbeiten.',
	'Original files' => 'Originaldateien',
	'When an image becomes WebP, Velox keeps its original JPG/PNG so nothing is ever lost. Choose where the originals live.' => 'Wenn ein Bild zu WebP wird, behält Velox das originale JPG/PNG, damit nichts verloren geht. Wählen Sie, wo die Originale liegen.',
	'Next to the WebP' => 'Neben der WebP',
	'Private backup' => 'Privates Backup',
	'The original stays in the same folder as its WebP. Simple — but it still fills up your uploads folder, and anyone with the old link can open it.' => 'Das Original bleibt im selben Ordner wie seine WebP. Einfach – aber es füllt weiterhin Ihren Uploads-Ordner, und jeder mit dem alten Link kann es öffnen.',
	'Originals move into a hidden backup folder that visitors can\'t open. Your site only uses the converted images, and old .jpg/.png links are sent to the WebP automatically.' => 'Originale werden in einen versteckten Backup-Ordner verschoben, den Besucher nicht öffnen können. Ihre Website nutzt nur die konvertierten Bilder, und alte .jpg/.png-Links werden automatisch zur WebP weitergeleitet.',
	'Right now originals are deleted after conversion (an older setting). Pick one of the options above to keep them from now on.' => 'Derzeit werden Originale nach der Konvertierung gelöscht (eine ältere Einstellung). Wählen Sie oben eine Option, um sie ab jetzt zu behalten.',
	'This applies when “Replace originals with WebP” is on. With it off, the originals are the files your site shows, so they stay where they are.' => 'Das gilt, wenn „Originale durch WebP ersetzen“ aktiv ist. Ist es aus, sind die Originale die Dateien, die Ihre Website anzeigt – sie bleiben daher, wo sie sind.',
	'Download all (ZIP)' => 'Alle herunterladen (ZIP)',
	'You are not allowed to do that.' => 'Dazu sind Sie nicht berechtigt.',
	'There are no original images to download yet.' => 'Es gibt noch keine Originalbilder zum Herunterladen.',
	'Could not build the ZIP file on this server.' => 'Die ZIP-Datei konnte auf diesem Server nicht erstellt werden.',
	'No originals yet — they appear here as images are converted.' => 'Noch keine Originale – sie erscheinen hier, sobald Bilder konvertiert werden.',
	'%s in the backup' => '%s im Backup',
	'%s next to their WebP' => '%s neben ihrer WebP',
	'%s originals · %s' => '%s Originale · %s',
	'Move %s to the backup' => '%s ins Backup verschieben',
	'Building the ZIP — the download starts in a moment.' => 'ZIP wird erstellt – der Download startet gleich.',
	'Moving… %s left' => 'Wird verschoben … noch %s',
	'Moved %s originals — %s could not be moved and stayed where they were.' => '%s Originale verschoben – %s konnten nicht verschoben werden und sind geblieben, wo sie waren.',
	'Moved %s originals to the backup.' => '%s Originale ins Backup verschoben.',
	'Originals: a JPG or PNG is always kept. A WebP wider than 1000 px with no original is backed up before it is re-converted; smaller WebPs are not.' => 'Originale: Ein JPG oder PNG wird immer behalten. Eine WebP, die breiter als 1000 px ist und kein Original hat, wird vor dem Neukonvertieren gesichert; kleinere WebPs nicht.',
	'Comment protection' => 'Kommentarschutz',
	'Stops spam comments before they reach you, and makes sure a link someone posts in a comment can never be clicked by accident — on your site, in the dashboard or in the notification email.' => 'Hält Spam-Kommentare ab, bevor sie Sie erreichen, und sorgt dafür, dass ein Link in einem Kommentar nie versehentlich angeklickt werden kann – weder auf Ihrer Website noch im Dashboard oder in der Benachrichtigungs-E-Mail.',
	'Spam bots stopped' => 'Gestoppte Spam-Bots',
	'%s this week' => '%s diese Woche',
	'In the spam folder' => 'Im Spam-Ordner',
	'Waiting for approval' => 'Warten auf Freigabe',
	'Protection' => 'Schutz',
	'Comment protection on/off' => 'Kommentarschutz an/aus',
	'Comment protection is off — spam can reach your comments and links in them are clickable.' => 'Der Kommentarschutz ist aus – Spam kann Ihre Kommentare erreichen und Links darin sind anklickbar.',
	'Keep spam bots out' => 'Spam-Bots fernhalten',
	'Comments must come from a real browser on your page. Bots that post directly are refused before anything is saved. Invisible to visitors — no CAPTCHA.' => 'Kommentare müssen aus einem echten Browser auf Ihrer Seite kommen. Bots, die direkt senden, werden abgewiesen, bevor etwas gespeichert wird. Für Besucher unsichtbar – kein CAPTCHA.',
	'Make links unclickable' => 'Links unklickbar machen',
	'Links in visitors\' comments show as plain text on the site and in the dashboard, and are broken up in notification emails. Comments by admins keep their links.' => 'Links in Besucherkommentaren erscheinen auf der Website und im Dashboard als reiner Text und werden in Benachrichtigungs-E-Mails unbrauchbar gemacht. Kommentare von Admins behalten ihre Links.',
	'Remove the “Website” field' => 'Das Feld „Website“ entfernen',
	'The field spammers use to plant a link behind their name.' => 'Das Feld, über das Spammer einen Link hinter ihrem Namen platzieren.',
	'Refuse trackbacks and pingbacks' => 'Trackbacks und Pingbacks abweisen',
	'Almost all of them are spam today.' => 'Fast alle davon sind heute Spam.',
	'Links allowed per comment' => 'Erlaubte Links pro Kommentar',
	'More than this and the comment goes straight to spam. 0 = no links at all.' => 'Bei mehr Links landet der Kommentar direkt im Spam. 0 = gar keine Links.',
	'Empty spam after' => 'Spam leeren nach',
	'Spam is deleted for good after this. 0 = keep it.' => 'Danach wird Spam endgültig gelöscht. 0 = behalten.',
	'Clean up' => 'Aufräumen',
	'Find spam already in your comments' => 'Vorhandenen Spam in Ihren Kommentaren finden',
	'Checks approved and waiting comments against the rules on the left. Matches are moved to the spam folder, where you can still restore them.' => 'Prüft freigegebene und wartende Kommentare anhand der Regeln links. Treffer werden in den Spam-Ordner verschoben, wo Sie sie noch wiederherstellen können.',
	'Scan comments' => 'Kommentare prüfen',
	'Empty the spam folder' => 'Spam-Ordner leeren',
	'Deletes every comment in the spam folder for good.' => 'Löscht jeden Kommentar im Spam-Ordner endgültig.',
	'Empty spam' => 'Spam leeren',
	'Don\'t need comments at all?' => 'Brauchen Sie gar keine Kommentare?',
	'Most business sites don\'t. Closing them everywhere is the most complete protection — nothing can be posted. Click Save to apply.' => 'Die meisten Firmenwebsites nicht. Sie überall zu schließen ist der vollständigste Schutz – es kann nichts gepostet werden. Zum Übernehmen auf Speichern klicken.',
	'Your comment looked automated, so it was not sent. If you wrote it yourself, make sure JavaScript is switched on, wait a moment and send it again.' => 'Ihr Kommentar wirkte automatisiert und wurde deshalb nicht gesendet. Wenn Sie ihn selbst geschrieben haben, aktivieren Sie JavaScript, warten Sie einen Moment und senden Sie ihn erneut.',
	'Comment not sent' => 'Kommentar nicht gesendet',
	'Leave this field empty' => 'Dieses Feld leer lassen',
	'Could not keep a copy of the original, so the image was left as it is.' => 'Es konnte keine Kopie des Originals behalten werden, daher wurde das Bild unverändert gelassen.',
	'No spam found in your comments.' => 'Kein Spam in Ihren Kommentaren gefunden.',
	'%s comments look like spam' => '%s Kommentare sehen nach Spam aus',
	'Move %s to spam' => '%s in den Spam verschieben',
	'Approved' => 'Freigegeben',
	'Waiting' => 'Wartend',
	'…and %s more.' => '…und %s weitere.',
	'Moved %s comments to the spam folder.' => '%s Kommentare in den Spam-Ordner verschoben.',
	'Delete all %s spam comments for good? This cannot be undone.' => 'Alle %s Spam-Kommentare endgültig löschen? Das kann nicht rückgängig gemacht werden.',
	'Deleted %s spam comments.' => '%s Spam-Kommentare gelöscht.',
	'When an image becomes WebP, Velox keeps its original JPG/PNG so nothing is ever lost — and every image wider than 1000 px always has a full-size original saved, even one that was uploaded as WebP. Choose where the originals live.' => 'Wenn ein Bild zu WebP wird, behält Velox das originale JPG/PNG, damit nichts verloren geht – und für jedes Bild, das breiter als 1000 px ist, wird immer ein Original in voller Größe gesichert, auch wenn es als WebP hochgeladen wurde. Wählen Sie, wo die Originale liegen.',
	'Originals: a JPG or PNG is always kept, and every image wider than 1000 px always has a full-size original saved — re-convert builds from it. Smaller WebPs are not backed up.' => 'Originale: Ein JPG oder PNG wird immer behalten, und für jedes Bild, das breiter als 1000 px ist, wird immer ein Original in voller Größe gesichert – das Neukonvertieren baut darauf auf. Kleinere WebPs werden nicht gesichert.',
	'%s large images still being backed up' => '%s große Bilder werden noch gesichert',
	'Back up %s now' => '%s jetzt sichern',
	'Backing up… %s left' => 'Wird gesichert … noch %s',
	'Backed up %s — %s could not be copied. Check that the uploads folder is writable.' => '%s gesichert – %s konnten nicht kopiert werden. Prüfen Sie, ob der Uploads-Ordner beschreibbar ist.',
	'Backed up %s large images.' => '%s große Bilder gesichert.',
	'Malicious code' => 'Schadcode',
	'Attackers upload a PHP file disguised among your images, then open it in a browser to control the site. Quarantine moves it where it can\'t run.' => 'Angreifer laden eine PHP-Datei getarnt zwischen Ihren Bildern hoch und rufen sie dann im Browser auf, um die Website zu steuern. Die Quarantäne verschiebt sie dorthin, wo sie nicht ausgeführt werden kann.',
	'Disguised file' => 'Getarnte Datei',
	'A name like photo.php.jpg looks like an image but some servers run it as code.' => 'Ein Name wie foto.php.jpg sieht aus wie ein Bild, aber manche Server führen ihn als Code aus.',
	'Server rules in uploads' => 'Serverregeln in Uploads',
	'Tells the server to run files in the media folder as code, so an uploaded "image" becomes a back door.' => 'Weist den Server an, Dateien im Medienordner als Code auszuführen – so wird ein hochgeladenes „Bild“ zur Hintertür.',
	'Added to a plugin' => 'Einem Plugin hinzugefügt',
	'Hackers drop extra PHP files into plugin folders where nobody looks. The plugin never shipped this file.' => 'Hacker legen zusätzliche PHP-Dateien in Plugin-Ordner, in die niemand schaut. Das Plugin wurde nie mit dieser Datei ausgeliefert.',
	'Added to WordPress' => 'WordPress hinzugefügt',
	'wp-admin and wp-includes belong to WordPress alone. A file WordPress didn\'t ship was put there by someone.' => 'wp-admin und wp-includes gehören allein WordPress. Eine Datei, die WordPress nicht mitliefert, hat jemand dort abgelegt.',
	'WordPress file changed' => 'WordPress-Datei verändert',
	'Malware often injects itself into a core file so it loads on every page. Restore puts back the original from WordPress.org.' => 'Schadsoftware schleust sich oft in eine Kerndatei ein, damit sie auf jeder Seite geladen wird. „Original wiederherstellen“ setzt das Original von WordPress.org zurück.',
	'WordPress file missing' => 'WordPress-Datei fehlt',
	'Usually harmless, but sometimes a sign files were tampered with. Restore puts it back from WordPress.org.' => 'Meist harmlos, manchmal aber ein Zeichen, dass Dateien manipuliert wurden. „Original wiederherstellen“ holt sie von WordPress.org zurück.',
	'Plugin file changed' => 'Plugin-Datei verändert',
	'Malware hides by adding a few lines to a file that otherwise looks normal. Restore puts back the original from WordPress.org.' => 'Schadsoftware versteckt sich, indem sie einer sonst normal aussehenden Datei ein paar Zeilen hinzufügt. „Original wiederherstellen“ setzt das Original von WordPress.org zurück.',
	'Injected into a page' => 'In eine Seite eingeschleust',
	'Code planted in a page\'s content runs in every visitor\'s browser — typically redirecting them to spam or scam sites.' => 'Im Seiteninhalt platzierter Code läuft im Browser jedes Besuchers – meist leitet er auf Spam- oder Betrugsseiten weiter.',
	'Site address changed' => 'Website-Adresse geändert',
	'Fix it under Settings → General, then change all passwords.' => 'Korrigieren Sie es unter Einstellungen → Allgemein und ändern Sie danach alle Passwörter.',
	'Code hidden in settings' => 'In Einstellungen versteckter Code',
	'Needs removing directly in the database — ask your host or a developer, and give them the setting name shown.' => 'Muss direkt in der Datenbank entfernt werden – fragen Sie Ihren Hoster oder einen Entwickler und nennen Sie den angezeigten Einstellungsnamen.',
	'New administrator' => 'Neuer Administrator',
	'If you don\'t recognise it, delete the account (attribute its content to yourself), then sign everyone out and change passwords.' => 'Wenn Sie es nicht kennen, löschen Sie das Konto (Inhalte sich selbst zuordnen), melden Sie dann alle ab und ändern Sie die Passwörter.',
	'Hidden redirect' => 'Versteckte Weiterleitung',
	'Remove that line in Performance → .htaccess (switch on Risky mode to see it).' => 'Entfernen Sie diese Zeile unter Performance → .htaccess (zum Anzeigen den Risiko-Modus einschalten).',
	'Hidden loader' => 'Versteckter Lader',
	'Remove that line in Performance → .htaccess (Risky mode), then quarantine the file it loads.' => 'Entfernen Sie diese Zeile unter Performance → .htaccess (Risiko-Modus) und stellen Sie dann die geladene Datei unter Quarantäne.',
	'Images run as code' => 'Bilder werden als Code ausgeführt',
	'Remove that line in Performance → .htaccess (Risky mode).' => 'Entfernen Sie diese Zeile unter Performance → .htaccess (Risiko-Modus).',
	'Updates waiting' => 'Updates ausstehend',
	'File editor on' => 'Dateieditor aktiv',
	'Errors shown to visitors' => 'Fehler für Besucher sichtbar',
	'"admin" account' => 'Konto „admin“',
	'Malicious or suspicious code' => 'Schädlicher oder verdächtiger Code',
	'Changed WordPress and plugin files' => 'Veränderte WordPress- und Plugin-Dateien',
	'Pages, settings and accounts' => 'Seiten, Einstellungen und Konten',
	'Server rules (.htaccess)' => 'Serverregeln (.htaccess)',
	'Hardening tips — not a hack, but how hacks get in' => 'Härtungstipps – kein Hack, aber so kommen Hacks herein',
	'Serious' => 'Ernst',
	'Check' => 'Prüfen',
	'Tip' => 'Tipp',
	'Quarantined' => 'In Quarantäne',
	'Restored' => 'Wiederhergestellt',
	'Cleaned' => 'Bereinigt',
	'%1$s WordPress files, %2$s plugin files, %3$s other code files, %4$s uploads and %5$s pages checked' => '%1$s WordPress-Dateien, %2$s Plugin-Dateien, %3$s weitere Code-Dateien, %4$s Uploads und %5$s Seiten geprüft',
	'Security scan' => 'Sicherheitsscan',
	'Finds out whether the site has been hacked: WordPress and plugin files are checked against the originals on WordPress.org, everything else is read for backdoors, and pages, settings, accounts and server rules are checked for the common hacks. Every finding says what it is, how it works and how to fix it.' => 'Findet heraus, ob die Website gehackt wurde: WordPress- und Plugin-Dateien werden mit den Originalen auf WordPress.org verglichen, alles andere wird nach Hintertüren durchsucht, und Seiten, Einstellungen, Konten und Serverregeln werden auf die gängigen Hacks geprüft. Jeder Fund erklärt, was er ist, wie er funktioniert und wie man ihn behebt.',
	'A scan is in progress' => 'Ein Scan läuft',
	'Not scanned yet' => 'Noch nicht gescannt',
	'%d serious problem found' => '%d ernstes Problem gefunden',
	'%d serious problems found' => '%d ernste Probleme gefunden',
	'%d thing to check' => '%d Punkt zu prüfen',
	'%d things to check' => '%d Punkte zu prüfen',
	'No signs of a hack' => 'Keine Anzeichen für einen Hack',
	'The first scan takes a minute or two. You can keep working while it runs.' => 'Der erste Scan dauert ein bis zwei Minuten. Sie können währenddessen weiterarbeiten.',
	'Click Scan now to watch it finish.' => 'Klicken Sie auf „Jetzt scannen“, um ihn zu Ende laufen zu sehen.',
	'Your site shows signs of a hack. Fix the findings below, then follow the steps.' => 'Ihre Website zeigt Anzeichen eines Hacks. Beheben Sie die Funde unten und folgen Sie dann den Schritten.',
	'Last scan %s ago' => 'Letzter Scan vor %s',
	'Scan again' => 'Erneut scannen',
	'Scan now' => 'Jetzt scannen',
	'What to do now' => 'Was jetzt zu tun ist',
	'Fix every serious finding below.' => 'Beheben Sie jeden ernsten Fund unten.',
	'Restore changed files from WordPress.org and quarantine the ones that don\'t belong. Nothing is deleted — you can put any file back.' => 'Stellen Sie veränderte Dateien von WordPress.org wieder her und schieben Sie nicht dazugehörige in die Quarantäne. Nichts wird gelöscht – jede Datei lässt sich zurückholen.',
	'Sign everyone out.' => 'Alle abmelden.',
	'Makes every stolen login cookie useless. You stay signed in.' => 'Macht jedes gestohlene Login-Cookie wertlos. Sie bleiben angemeldet.',
	'Sign everyone out' => 'Alle abmelden',
	'Change every administrator password' => 'Ändern Sie jedes Administrator-Passwort',
	'— and your hosting and FTP passwords too.' => '– und auch Ihre Hosting- und FTP-Passwörter.',
	'Administrators' => 'Administratoren',
	'Update WordPress, plugins and themes' => 'Aktualisieren Sie WordPress, Plugins und Themes',
	'— the hole they came through is usually an old plugin.' => '– die Lücke, durch die sie kamen, ist meist ein altes Plugin.',
	'until nothing serious is left.' => 'bis nichts Ernstes mehr übrig ist.',
	'Still finding problems after that? Restore a backup from before the hack (Utilities → Backup & restore) or ask your host — some infections live outside WordPress where no plugin can reach.' => 'Danach immer noch Probleme? Spielen Sie ein Backup von vor dem Hack ein (Werkzeuge → Backup & Wiederherstellung) oder fragen Sie Ihren Hoster – manche Infektionen liegen außerhalb von WordPress, wo kein Plugin hinkommt.',
	'Inside it: %s' => 'Darin: %s',
	'Fixed' => 'Behoben',
	'Line %d' => 'Zeile %d',
	'Restore original' => 'Original wiederherstellen',
	'Quarantine' => 'Quarantäne',
	'Remove injected code' => 'Eingeschleusten Code entfernen',
	'Open .htaccess' => '.htaccess öffnen',
	'Files moved out of the site. They can\'t run in here. Put one back if something stopped working; delete them for good once you\'re sure.' => 'Aus der Website entfernte Dateien. Hier drin können sie nicht ausgeführt werden. Holen Sie eine zurück, wenn etwas nicht mehr funktioniert; löschen Sie sie endgültig, sobald Sie sicher sind.',
	'replaced by the original' => 'durch das Original ersetzt',
	'Put back' => 'Zurückholen',
	'Delete for good' => 'Endgültig löschen',
	'Automatic scans' => 'Automatische Scans',
	'Scan by itself' => 'Selbstständig scannen',
	'Every week' => 'Jede Woche',
	'Every night' => 'Jede Nacht',
	'Only when I click' => 'Nur wenn ich klicke',
	'Next scan: %s (runs at night, site time).' => 'Nächster Scan: %s (läuft nachts, Website-Zeit).',
	'Runs at night, site time, when your site has visitors to trigger it.' => 'Läuft nachts (Website-Zeit), sobald Besucher die Website aufrufen und ihn so anstoßen.',
	'Email me about new serious problems' => 'Mich per E-Mail über neue ernste Probleme informieren',
	'Sent to %s — only when an automatic scan finds something new.' => 'Geht an %s – nur wenn ein automatischer Scan etwas Neues findet.',
	'What no scanner can promise' => 'Was kein Scanner versprechen kann',
	'WordPress and plugin files from WordPress.org are checked exactly — a changed file is certain. Everything else (your theme, premium plugins like Oxygen) can only be read for the tricks backdoors use, so brand-new malware can slip past, just as it can with Wordfence.' => 'WordPress- und Plugin-Dateien von WordPress.org werden exakt geprüft – eine veränderte Datei ist eindeutig. Alles andere (Ihr Theme, Premium-Plugins wie Oxygen) kann nur auf die Tricks von Hintertüren durchsucht werden, daher kann brandneue Schadsoftware durchrutschen – genau wie bei Wordfence.',
	'And a scanner running inside a hacked site can be fooled by malware that hides outside WordPress or tampers with the scanner itself. "No signs of a hack" is strong evidence, not proof. Keep backups and keep everything updated.' => 'Und ein Scanner innerhalb einer gehackten Website kann von Schadsoftware getäuscht werden, die sich außerhalb von WordPress versteckt oder den Scanner selbst manipuliert. „Keine Anzeichen für einen Hack“ ist ein starkes Indiz, kein Beweis. Halten Sie Backups und alles aktuell.',
	'That finding is no longer in the report. Scan again.' => 'Dieser Fund ist nicht mehr im Bericht. Bitte erneut scannen.',
	'This one has already been dealt with.' => 'Das wurde bereits erledigt.',
	'This one needs to be fixed by hand — follow the steps shown with it.' => 'Das muss von Hand behoben werden – folgen Sie den angezeigten Schritten.',
	'Could not move the file — the server did not allow it. Ask your host to remove it, or delete it over FTP.' => 'Die Datei konnte nicht verschoben werden – der Server hat es nicht erlaubt. Bitten Sie Ihren Hoster, sie zu entfernen, oder löschen Sie sie per FTP.',
	'The file is no longer there.' => 'Die Datei ist nicht mehr vorhanden.',
	'This file is needed for the site to start, so Velox won\'t move it. Open it over FTP or your host\'s file manager and remove the code shown here.' => 'Diese Datei wird zum Starten der Website gebraucht, daher verschiebt Velox sie nicht. Öffnen Sie sie per FTP oder im Dateimanager Ihres Hosters und entfernen Sie den hier gezeigten Code.',
	'Moved to quarantine. It can no longer run — and you can put it back below if something stops working.' => 'In die Quarantäne verschoben. Sie kann nicht mehr ausgeführt werden – und Sie können sie unten zurückholen, falls etwas nicht mehr funktioniert.',
	'The quarantined copy is gone.' => 'Die Quarantäne-Kopie ist nicht mehr da.',
	'The original location is not inside this site any more.' => 'Der ursprüngliche Ort liegt nicht mehr innerhalb dieser Website.',
	'A file with that name is back in that place already, so nothing was overwritten.' => 'An dieser Stelle liegt bereits wieder eine Datei mit diesem Namen, daher wurde nichts überschrieben.',
	'Could not put the file back — the server did not allow it.' => 'Die Datei konnte nicht zurückgelegt werden – der Server hat es nicht erlaubt.',
	'Put back where it was.' => 'An ihren Platz zurückgelegt.',
	'Not found in quarantine.' => 'Nicht in der Quarantäne gefunden.',
	'Deleted for good.' => 'Endgültig gelöscht.',
	'Could not write the clean file — the server did not allow it.' => 'Die saubere Datei konnte nicht geschrieben werden – der Server hat es nicht erlaubt.',
	'Replaced with the verified original from WordPress.org. The changed file was kept in quarantine.' => 'Durch das geprüfte Original von WordPress.org ersetzt. Die veränderte Datei liegt in der Quarantäne.',
	'Unexpected path.' => 'Unerwarteter Pfad.',
	'Could not download the original from WordPress.org. Try again later, or reinstall WordPress from Dashboard → Updates.' => 'Das Original konnte nicht von WordPress.org geladen werden. Versuchen Sie es später erneut oder installieren Sie WordPress unter Dashboard → Aktualisierungen neu.',
	'The downloaded file did not match WordPress.org\'s checksum, so it was not used. Reinstall WordPress from Dashboard → Updates instead.' => 'Die geladene Datei passte nicht zur Prüfsumme von WordPress.org und wurde daher nicht verwendet. Installieren Sie WordPress stattdessen unter Dashboard → Aktualisierungen neu.',
	'Could not get a verified copy of this file from WordPress.org. Delete the plugin and install it again from Plugins → Add New — that replaces every file.' => 'Es konnte keine geprüfte Kopie dieser Datei von WordPress.org geladen werden. Löschen Sie das Plugin und installieren Sie es unter Plugins → Neues Plugin hinzufügen erneut – das ersetzt jede Datei.',
	'That post no longer exists.' => 'Dieser Beitrag existiert nicht mehr.',
	'Nothing could be removed automatically — open the post and delete the code shown here by hand.' => 'Es konnte nichts automatisch entfernt werden – öffnen Sie den Beitrag und löschen Sie den hier gezeigten Code von Hand.',
	'Injected code removed. The previous version is saved as a revision.' => 'Eingeschleuster Code entfernt. Die vorherige Version ist als Revision gespeichert.',
	'Signed out %d account(s) everywhere — every stolen login is now useless. You stay signed in here.' => '%d Konto/Konten überall abgemeldet – jedes gestohlene Login ist jetzt wertlos. Sie bleiben hier angemeldet.',
	'Fetching the checksums for your version' => 'Prüfsummen für Ihre Version werden geladen',
	'Checking WordPress core files' => 'WordPress-Kerndateien werden geprüft',
	'Looking for files that do not belong' => 'Suche nach Dateien, die nicht dazugehören',
	'Checking plugins against WordPress.org' => 'Plugins werden mit WordPress.org verglichen',
	'Reading themes and other code for backdoors' => 'Themes und weiterer Code werden nach Hintertüren durchsucht',
	'Checking uploads for runnable code' => 'Uploads werden auf ausführbaren Code geprüft',
	'Checking server rules (.htaccess)' => 'Serverregeln (.htaccess) werden geprüft',
	'Checking posts, settings and accounts' => 'Beiträge, Einstellungen und Konten werden geprüft',
	'Looking for open doors' => 'Suche nach offenen Türen',
	'Differs from %1$s %2$s as published on WordPress.org.' => 'Weicht von %1$s %2$s ab, wie es auf WordPress.org veröffentlicht ist.',
	'A PHP file that %s never shipped with.' => 'Eine PHP-Datei, mit der %s nie ausgeliefert wurde.',
	'%s very large code files (over 3 MB) were skipped.' => '%s sehr große Code-Dateien (über 3 MB) wurden übersprungen.',
	'Runs code that is hidden by encoding (eval of decoded text). This is how almost every PHP backdoor disguises itself.' => 'Führt Code aus, der durch Kodierung versteckt ist (eval von dekodiertem Text). So tarnt sich fast jede PHP-Hintertür.',
	'Runs whatever a visitor sends in the address or a form. That lets anyone on the internet run commands on your server.' => 'Führt aus, was ein Besucher in der Adresse oder einem Formular sendet. Damit kann jeder im Internet Befehle auf Ihrem Server ausführen.',
	'Calls a function whose name AND input both come from the visitor. A classic one-line backdoor.' => 'Ruft eine Funktion auf, deren Name UND Eingabe vom Besucher stammen. Eine klassische Einzeilen-Hintertür.',
	'Uses the old "/e" trick to make a text replacement run code — only ever used to hide a backdoor.' => 'Nutzt den alten „/e“-Trick, damit eine Textersetzung Code ausführt – wird nur zum Verstecken einer Hintertür verwendet.',
	'Contains the signature of a known web shell — a full remote-control panel for attackers.' => 'Enthält die Signatur einer bekannten Web-Shell – eine komplette Fernsteuerung für Angreifer.',
	'Loads another file whose name is written in hidden hex code, so nobody reading the file can see what it loads.' => 'Lädt eine andere Datei, deren Name in verstecktem Hex-Code geschrieben ist, sodass niemand beim Lesen sieht, was geladen wird.',
	'Lets a visitor upload a file to any place on the server they name — how attackers install more malware.' => 'Lässt einen Besucher eine Datei an jeden beliebigen Ort auf dem Server hochladen – so installieren Angreifer weitere Schadsoftware.',
	'Hides variable names behind hex codes.' => 'Versteckt Variablennamen hinter Hex-Codes.',
	'Builds text out of a long chain of character codes — a way to hide words like "eval".' => 'Baut Text aus einer langen Kette von Zeichencodes zusammen – eine Methode, Wörter wie „eval“ zu verstecken.',
	'Holds a very long block of encoded data.' => 'Enthält einen sehr langen Block kodierter Daten.',
	'Assembles a function name by stripping junk characters out of a string — a common way to hide "base64_decode" or "eval".' => 'Setzt einen Funktionsnamen zusammen, indem Füllzeichen aus einem Text entfernt werden – ein gängiger Weg, „base64_decode“ oder „eval“ zu verstecken.',
	'Switches off all error messages and time limits right at the start — typical of shells that must not be noticed.' => 'Schaltet gleich zu Beginn alle Fehlermeldungen und Zeitlimits ab – typisch für Shells, die nicht auffallen sollen.',
	'Calls a function named by the visitor.' => 'Ruft eine vom Besucher benannte Funktion auf.',
	'An icon file that contains PHP code. Hackers hide their code in .ico files and load it from elsewhere, because nobody opens icons.' => 'Eine Icon-Datei, die PHP-Code enthält. Hacker verstecken ihren Code in .ico-Dateien und laden ihn von woanders, weil niemand Icons öffnet.',
	'Line %1$d sends visitors to %3$s, but only when their %2$s matches — so you never see it yourself.' => 'Zeile %1$d schickt Besucher zu %3$s, aber nur, wenn ihr(e) %2$s passt – deshalb sehen Sie es selbst nie.',
	'referring search engine' => 'verweisende Suchmaschine',
	'device' => 'Gerät',
	'Line %d makes the server run an extra file before every page — a way to load malware on every request.' => 'Zeile %d lässt den Server vor jeder Seite eine zusätzliche Datei ausführen – ein Weg, Schadsoftware bei jedem Aufruf zu laden.',
	'Line %d tells the server to run image or text files as PHP. That is how a "picture" becomes a back door.' => 'Zeile %d weist den Server an, Bild- oder Textdateien als PHP auszuführen. So wird ein „Bild“ zur Hintertür.',
	'Line %1$d sends visitors who hit a missing page to %2$s.' => 'Zeile %1$d schickt Besucher, die auf eine fehlende Seite stoßen, zu %2$s.',
	'The WordPress address (%1$s) and the site address (%2$s) point at different domains. Hackers change one of them to send your visitors elsewhere.' => 'Die WordPress-Adresse (%1$s) und die Website-Adresse (%2$s) zeigen auf unterschiedliche Domains. Hacker ändern eine davon, um Ihre Besucher woandershin zu schicken.',
	'This setting stores encoded code that runs itself — a payload hidden in the database, where file scanners never look.' => 'Diese Einstellung speichert kodierten Code, der sich selbst ausführt – eine in der Datenbank versteckte Nutzlast, wo Datei-Scanner nie hinschauen.',
	'A new administrator account, created %s ago. If you did not add it, an attacker did — it is how they keep coming back.' => 'Ein neues Administrator-Konto, erstellt vor %s. Wenn Sie es nicht angelegt haben, war es ein Angreifer – so kommen sie immer wieder zurück.',
	'Contains a hidden script that decodes and runs code in your visitors\' browsers — usually a redirect to spam or a fake "update your browser" page.' => 'Enthält ein verstecktes Skript, das Code im Browser Ihrer Besucher dekodiert und ausführt – meist eine Weiterleitung zu Spam oder einer gefälschten „Browser aktualisieren“-Seite.',
	'Loads a script from %s. If you did not put it there, it was injected.' => 'Lädt ein Skript von %s. Wenn Sie es nicht dort platziert haben, wurde es eingeschleust.',
	'Contains an invisible frame that silently loads another website in your visitors\' browsers.' => 'Enthält einen unsichtbaren Rahmen, der unbemerkt eine andere Website im Browser Ihrer Besucher lädt.',
	'%1$d plugin and %2$d theme updates are waiting%3$s. Out-of-date plugins are the most common way WordPress sites get hacked.' => '%1$d Plugin- und %2$d Theme-Updates stehen aus%3$s. Veraltete Plugins sind der häufigste Weg, wie WordPress-Websites gehackt werden.',
	', plus a WordPress update' => ', dazu ein WordPress-Update',
	'The built-in theme and plugin editor is switched on. Anyone who steals an admin login can write PHP through it. Add define( \'DISALLOW_FILE_EDIT\', true ); to wp-config.php to close it.' => 'Der eingebaute Theme- und Plugin-Editor ist eingeschaltet. Wer ein Admin-Login stiehlt, kann darüber PHP schreiben. Fügen Sie define( \'DISALLOW_FILE_EDIT\', true ); in die wp-config.php ein, um ihn zu schließen.',
	'Error messages are shown to visitors. They reveal file paths and versions that help an attacker.' => 'Fehlermeldungen werden Besuchern angezeigt. Sie verraten Dateipfade und Versionen, die einem Angreifer helfen.',
	'An account is called "admin" — the first name every password-guessing bot tries. Login protection (Security → Login protection) blocks those bots.' => 'Ein Konto heißt „admin“ – der erste Name, den jeder Passwort-Rate-Bot probiert. Der Login-Schutz (Sicherheit → Login-Schutz) blockiert diese Bots.',
	'Not on WordPress.org, so checked by reading their code instead of by checksum: %s.' => 'Nicht auf WordPress.org, daher durch Lesen des Codes statt per Prüfsumme geprüft: %s.',
	'The automatic Velox security scan of %1$s found %2$d new serious problem(s):' => 'Der automatische Velox-Sicherheitsscan von %1$s hat %2$d neue(s) ernste(s) Problem(e) gefunden:',
	'Open the report to see how each one works and fix it:' => 'Öffnen Sie den Bericht, um zu sehen, wie jedes funktioniert, und es zu beheben:',
	'[%1$s] Security scan: %2$d serious problem(s) found' => '[%1$s] Sicherheitsscan: %2$d ernste(s) Problem(e) gefunden',
	'%s found so far' => '%s bisher gefunden',
	'Move this file into quarantine? If it belongs to your theme or a plugin, that part of the site may stop working until you put it back — the button to do that appears below.' => 'Diese Datei in die Quarantäne verschieben? Gehört sie zu Ihrem Theme oder einem Plugin, funktioniert dieser Teil der Website eventuell nicht mehr, bis Sie sie zurückholen – die Schaltfläche dafür erscheint unten.',
	'Remove the injected code from this page? The current version is saved as a revision first.' => 'Den eingeschleusten Code von dieser Seite entfernen? Die aktuelle Version wird vorher als Revision gespeichert.',
	'Delete this file for good? This cannot be undone.' => 'Diese Datei endgültig löschen? Das kann nicht rückgängig gemacht werden.',
	'Sign every user out on every device? You stay signed in here.' => 'Jeden Benutzer auf jedem Gerät abmelden? Sie bleiben hier angemeldet.',
	'Malware & hacks' => 'Malware & Hacks',
	'Find out if the site is hacked: WordPress and plugin files are checked against WordPress.org, themes and other code are read for backdoors, and posts, settings, accounts and .htaccess are checked for the common hacks. Every finding explains what it is and how to fix it — restore the original, quarantine the file, or clean the post — and a weekly scan emails you if anything new turns up.' => 'Finden Sie heraus, ob die Website gehackt ist: WordPress- und Plugin-Dateien werden mit WordPress.org verglichen, Themes und weiterer Code werden nach Hintertüren durchsucht, und Beiträge, Einstellungen, Konten und .htaccess werden auf die gängigen Hacks geprüft. Jeder Fund erklärt, was er ist und wie man ihn behebt – Original wiederherstellen, Datei in Quarantäne verschieben oder Beitrag bereinigen – und ein wöchentlicher Scan schickt Ihnen eine E-Mail, wenn etwas Neues auftaucht.',
