	'Rules for this class only, including states such as :hover. Properties the builder does not understand are dropped on save.' => 'Regeln nur für diese Klasse, einschließlich Zuständen wie :hover. Eigenschaften, die der Builder nicht versteht, werden beim Speichern verworfen.',
	'Responsive rules are kept when they use one of the site breakpoints:' => 'Responsive Regeln bleiben erhalten, wenn sie einen der Breakpoints der Website verwenden:',
	'Media queries at other widths are not understood and are dropped.' => 'Media Queries mit anderen Breiten werden nicht verstanden und verworfen.',
