	'%s is a Velox starter class: elements get it automatically when you add them, and it carries their default look. Deleting it strips those styles from every page that uses it. To confirm, type the class name:' => '%s ist eine Velox-Startklasse: Elemente erhalten sie automatisch, wenn Sie sie hinzufügen, und sie bestimmt ihr Standard-Aussehen. Wenn Sie sie löschen, verlieren alle Seiten, die sie verwenden, diese Stile. Geben Sie zur Bestätigung den Klassennamen ein:',
