	'Search pages' => 'Seiten durchsuchen',
	'Saved changes that visitors do not see yet. Open it and press Publish to put them live.' => 'Gespeicherte Änderungen, die Besucher noch nicht sehen. Öffnen Sie das Dokument und klicken Sie auf „Veröffentlichen“, um sie live zu schalten.',
	'Unpublished changes' => 'Unveröffentlichte Änderungen',
	'Published — Velox uses this template wherever it applies.' => 'Veröffentlicht — Velox verwendet diese Vorlage überall, wo sie greift.',
	'Published — shown wherever it is placed.' => 'Veröffentlicht — wird überall angezeigt, wo der Block platziert ist.',
	'Drafts are not used on the site. Publish it to put it to work.' => 'Entwürfe werden auf der Website nicht verwendet. Veröffentlichen Sie das Dokument, damit es wirkt.',
