	'Could not change type' => 'Typ konnte nicht geändert werden',
	'Take this page off your site? The layout is kept and can be published again.' => 'Diese Seite von Ihrer Website nehmen? Das Layout bleibt erhalten und kann erneut veröffentlicht werden.',
	'Unpublish this template? Pages stop using it until you publish it again. The layout is kept.' => 'Veröffentlichung dieser Vorlage aufheben? Seiten verwenden sie erst wieder, wenn Sie sie erneut veröffentlichen. Das Layout bleibt erhalten.',
	'Unpublish this reusable? Pages that place it stop showing it until you publish it again.' => 'Veröffentlichung dieses wiederverwendbaren Blocks aufheben? Seiten, die ihn enthalten, zeigen ihn erst wieder, wenn Sie ihn erneut veröffentlichen.',
	'Delete “%s”? This also trashes the WordPress page it is bound to.' => '„%s“ löschen? Dadurch wird auch die verknüpfte WordPress-Seite in den Papierkorb verschoben.',
	'Delete “%s”? This cannot be undone.' => '„%s“ löschen? Dies kann nicht rückgängig gemacht werden.',
	'“%s” is a published page. As a template or reusable it is no longer served at its address, so visitors would see your theme there instead. Change the type anyway?' => '„%s“ ist eine veröffentlichte Seite. Als Vorlage oder wiederverwendbarer Block wird sie nicht mehr unter ihrer Adresse ausgeliefert, Besucher sähen dort stattdessen Ihr Theme. Typ trotzdem ändern?',
	'Editing one updates every page and template it appears in. Only published reusables are shown on the site.' => 'Eine Änderung wirkt auf jede Seite und Vorlage, in der der Block vorkommt. Nur veröffentlichte wiederverwendbare Blöcke werden auf der Website angezeigt.',
	'Used in:' => 'Verwendet in:',
	'Used in 1 place' => 'An 1 Stelle verwendet',
	'Used in %d places' => 'An %d Stellen verwendet',
	'Draft — not shown on the site until published' => 'Entwurf — erst nach Veröffentlichung auf der Website sichtbar',
	'Delete this reusable?' => 'Diesen wiederverwendbaren Block löschen?',
	'This reusable is used in 1 place. Deleting it removes the block from there. Continue?' => 'Dieser wiederverwendbare Block wird an 1 Stelle verwendet. Beim Löschen verschwindet er dort. Fortfahren?',
	'This reusable is used in %s places. Deleting it removes the block from all of them. Continue?' => 'Dieser wiederverwendbare Block wird an %s Stellen verwendet. Beim Löschen verschwindet er überall dort. Fortfahren?',
	'Leave a width empty to use the default shown in the field. Changing a breakpoint rewrites the media queries in every page stylesheet. Republish a page if it looks stale.' => 'Lassen Sie eine Breite leer, um den im Feld angezeigten Standardwert zu verwenden. Eine Änderung an einem Breakpoint schreibt die Media Queries in jedem Seiten-Stylesheet neu. Veröffentlichen Sie eine Seite erneut, falls sie veraltet aussieht.',
	'Not set — inherits' => 'Nicht gesetzt — wird geerbt',
	'Catch-all means: used for anything no more specific template claims. If no template matches a page at all, the site default is used. Only published templates are used on the site.' => 'Auffangvorlage bedeutet: Sie wird für alles verwendet, was keine spezifischere Vorlage beansprucht. Passt gar keine Vorlage zu einer Seite, wird der Standard der Website verwendet. Auf der Website werden nur veröffentlichte Vorlagen verwendet.',
	'Used for any page no other template claims.' => 'Wird für jede Seite verwendet, die keine andere Vorlage beansprucht.',
	'Used on the site wherever this template applies.' => 'Wird auf der Website überall verwendet, wo diese Vorlage greift.',
	'Draft — not used on the site until published' => 'Entwurf — erst nach Veröffentlichung auf der Website aktiv',
	'Use this template for any page no other template claims.' => 'Diese Vorlage für jede Seite verwenden, die keine andere Vorlage beansprucht.',
	'Make default' => 'Als Standard festlegen',
	'New templates start as a draft. Publish it once it is ready — until then the site does not use it.' => 'Neue Vorlagen beginnen als Entwurf. Veröffentlichen Sie die Vorlage, sobald sie fertig ist — bis dahin verwendet die Website sie nicht.',
	'Give it a name first.' => 'Geben Sie zuerst einen Namen ein.',
	'Creating…' => 'Wird erstellt…',
	'Could not create it' => 'Konnte nicht erstellt werden',
	'Delete this template? Pages using it fall back to whatever matches next.' => 'Diese Vorlage löschen? Seiten, die sie verwenden, greifen auf die nächste passende Vorlage zurück.',
	'Could not make it the default' => 'Konnte nicht als Standard festgelegt werden',
	'Not saved' => 'Nicht gespeichert',
	// Velox Builder drafts, archive templates
	'Back to the published version.' => 'Zurück zur veröffentlichten Version.',
	'Discard unpublished changes' => 'Unveröffentlichte Änderungen verwerfen',
	'Not on the site yet.' => 'Noch nicht auf der Website.',
	'Publish changes' => 'Änderungen veröffentlichen',
	'Save — only you see it until you publish' => 'Speichern – nur Sie sehen es, bis Sie veröffentlichen',
	'Saved. Visitors still see the published version until you publish.' => 'Gespeichert. Besucher sehen weiterhin die veröffentlichte Version, bis Sie veröffentlichen.',
	'This holds one item’s content. Remove the item in the element’s Settings.' => 'Dies enthält den Inhalt eines Eintrags. Entfernen Sie den Eintrag in den Einstellungen des Elements.',
	'This holds one item’s content. Reorder items in the element’s Settings.' => 'Dies enthält den Inhalt eines Eintrags. Ändern Sie die Reihenfolge in den Einstellungen des Elements.',
	'Throw away every change that is not published yet, and go back to the version visitors see?' => 'Alle noch nicht veröffentlichten Änderungen verwerfen und zur Version zurückkehren, die Besucher sehen?',
	'Visitors see exactly this version.' => 'Besucher sehen genau diese Version.',
	'Your saved changes are not live yet. Publish puts them on the site.' => 'Ihre gespeicherten Änderungen sind noch nicht live. „Veröffentlichen“ bringt sie auf die Website.',
