	'Your session expired. Reload the page — your changes are kept in this browser.' => 'Ihre Sitzung ist abgelaufen. Laden Sie die Seite neu – Ihre Änderungen bleiben in diesem Browser erhalten.',
	'click to remove' => 'zum Entfernen klicken',
	'mixed' => 'gemischt',
	'set here to override' => 'hier setzen zum Überschreiben',
	'“%s” is a published page. Changing its type unlinks it from its WordPress page (visitors see your theme at that address) and turns it into an unpublished draft — publish it again to use it. Change the type anyway?' => '„%s“ ist eine veröffentlichte Seite. Wenn Sie den Typ ändern, wird sie von ihrer WordPress-Seite gelöst (Besucher sehen unter dieser Adresse Ihr Theme) und zu einem unveröffentlichten Entwurf – veröffentlichen Sie sie erneut, um sie zu verwenden. Typ trotzdem ändern?',
	'Which template a page gets: the one chosen on the page itself; otherwise a template made for it (Front page, then Posts or Pages); otherwise the site default; otherwise a Catch-all template. 404, Search and Archives templates are used for those screens.' => 'Welche Vorlage eine Seite bekommt: die auf der Seite selbst gewählte; sonst eine dafür erstellte (Startseite, dann Beiträge oder Seiten); sonst die Standardvorlage der Website; sonst eine Auffang-Vorlage. 404-, Such- und Archiv-Vorlagen werden für diese Ansichten verwendet.',
	'Only published templates are used on the site.' => 'Nur veröffentlichte Vorlagen werden auf der Website verwendet.',
	'(draft — not used until published)' => '(Entwurf – erst nach dem Veröffentlichen verwendet)',
	'Used right now:' => 'Aktuell verwendet:',
	'no template' => 'keine Vorlage',
