	'Tab %d' => 'Tab %d',
	// Media editor 4.19.1
	'%d row loaded from %s. Check it below, then apply.' => '%d Zeile aus %s geladen. Prüfen Sie sie unten und wenden Sie sie dann an.',
	'Upload a text file' => 'Textdatei hochladen',
