	'The zip file came out incomplete. Please try again.' => 'Die Zip-Datei ist unvollständig. Bitte versuchen Sie es erneut.',
	// Fonts (OMGF-style) + Velox Performance bar 4.20.0
	'Fonts rebuilt (%1$d stylesheet(s)). %2$s New fonts on other pages are still added when those pages are visited.' => 'Schriften neu erstellt (%1$d Stylesheet(s)). %2$s Neue Schriften auf anderen Seiten werden weiterhin ergänzt, sobald diese Seiten aufgerufen werden.',
	'Cache status' => 'Cache-Status',
	'Save &amp; optimize' => 'Speichern &amp; optimieren',
	'Refresh cache (and keep settings)' => 'Cache erneuern (Einstellungen behalten)',
	'Empty cache' => 'Cache leeren',
	'Optimize local fonts' => 'Lokale Schriften optimieren',
	'%1$s preloads a font file before the page renders — only use it for fonts visible above the fold. %2$s stops a font Velox found from loading at all, to save bandwidth. Click %3$s to apply.' => '%1$s lädt eine Schriftdatei vor, bevor die Seite dargestellt wird – nur für Schriften verwenden, die ohne Scrollen sichtbar sind. %2$s verhindert, dass eine gefundene Schrift überhaupt geladen wird, und spart Bandbreite. Klicken Sie auf %3$s, um es anzuwenden.',
	'Load early' => 'Früh laden',
	'Don\'t load' => 'Nicht laden',
	'Used Subset(s)' => 'Verwendete Zeichensätze',
	'A subset is a (limited) set of characters belonging to an alphabet. Default: latin, latin-ext. Limit the selection to subsets your site actually uses. Selecting too many subsets can negatively impact performance! Latin Extended and Vietnamese are add-ons for Latin and can\'t be used by themselves.' => 'Ein Zeichensatz (Subset) ist ein begrenzter Satz von Zeichen eines Alphabets. Standard: latin, latin-ext. Wählen Sie nur die Zeichensätze, die Ihre Website wirklich nutzt. Zu viele Zeichensätze können die Leistung verschlechtern! Latin Extended und Vietnamesisch ergänzen Latin und funktionieren nicht allein.',
	'Used subsets' => 'Verwendete Zeichensätze',
	'Download log' => 'Protokoll herunterladen',
	'Delete log' => 'Protokoll löschen',
	'Velox Performance' => 'Velox Performance',
	'Performance settings' => 'Performance-Einstellungen',
	'Clear all cache' => 'Gesamten Cache leeren',
	'Clear minified CSS / JS' => 'Minifiziertes CSS / JS leeren',
	'Clear Cloudflare cache' => 'Cloudflare-Cache leeren',
	'Clear Velox cache' => 'Velox-Cache leeren',
	'Optimize fonts on this page' => 'Schriften auf dieser Seite optimieren',
