	'Cache removed' => 'Cache geleert',
	'Could not clear the cache' => 'Der Cache konnte nicht geleert werden',
	'OK' => 'OK',
	'The server did not answer. Please try again.' => 'Der Server hat nicht geantwortet. Bitte versuchen Sie es erneut.',
	'Google Fonts optimization completed. Return to the settings screen to see the results.' => 'Google-Fonts-Optimierung abgeschlossen. Kehren Sie zu den Einstellungen zurück, um das Ergebnis zu sehen.',
	'not a font file' => 'keine Schriftdatei',
	'Velox could not load your front page: %s' => 'Velox konnte Ihre Startseite nicht laden: %s',
	'Velox could not load your front page: %1$d %2$s' => 'Velox konnte Ihre Startseite nicht laden: %1$d %2$s',
	'Optimization completed successfully.' => 'Optimierung erfolgreich abgeschlossen.',
	'Optimization ran, but no Google Fonts were found on your front page.' => 'Die Optimierung lief, aber auf Ihrer Startseite wurden keine Google Fonts gefunden.',
	'Cache directory successfully emptied.' => 'Cache-Ordner erfolgreich geleert.',
	'Found' => 'Gefunden',
	'Unloaded' => 'Nicht geladen',
	'Stale' => 'Veraltet',
	'Unused' => 'Unbenutzt',
	'Switch on "Host Google Fonts locally" above, then click Save & optimize.' => 'Schalten Sie oben „Google Fonts lokal hosten“ ein und klicken Sie dann auf „Speichern & optimieren“.',
	'Let\'s get started!' => 'Los geht’s!',
	'Click Save & optimize: Velox loads your front page, downloads every Google Font it uses and lists them below. The list grows on its own as other pages are visited.' => 'Klicken Sie auf „Speichern & optimieren“: Velox lädt Ihre Startseite, lädt jede verwendete Google-Schrift herunter und listet sie unten auf. Die Liste wächst von selbst, wenn weitere Seiten aufgerufen werden.',
	'Test Mode is on: only logged-in administrators (or URLs with ?vxfonts=1) get the local fonts.' => 'Der Testmodus ist aktiv: Nur angemeldete Administratoren (oder URLs mit ?vxfonts=1) erhalten die lokalen Schriften.',
	'The cached stylesheets don\'t reflect the current settings. Refresh the cache to apply them.' => 'Die gespeicherten Stylesheets entsprechen nicht mehr den aktuellen Einstellungen. Erneuern Sie den Cache, um sie anzuwenden.',
	'Some font files could not be downloaded:' => 'Einige Schriftdateien konnten nicht heruntergeladen werden:',
	'Dismiss' => 'Ausblenden',
	'Velox wasn\'t able to process all Google Fonts on your site.' => 'Velox konnte nicht alle Google Fonts Ihrer Website verarbeiten.',
	'These were still loaded from Google (for example by a script or an @import):' => 'Diese wurden weiterhin von Google geladen (zum Beispiel durch ein Skript oder ein @import):',
	'Mark as fixed' => 'Als behoben markieren',
	'All Google Fonts on your site are stored on your server.' => 'Alle Google Fonts Ihrer Website liegen auf Ihrem Server.',
	'No Google Fonts were found on your front page yet. If your site uses them, open a page that does (they are added as they are found), or check the debug log.' => 'Auf Ihrer Startseite wurden noch keine Google Fonts gefunden. Wenn Ihre Website welche nutzt, öffnen Sie eine Seite, die sie verwendet (sie werden beim Finden ergänzt), oder prüfen Sie das Debug-Protokoll.',
	'Nothing cached yet.' => 'Noch nichts im Cache.',
	'Configure' => 'Konfigurieren',
	'After clicking Save & optimize, this section lists every Google Font requested on your site, with its styles and weights. The list grows as other Google Fonts stylesheets are found on other pages.' => 'Nach einem Klick auf „Speichern & optimieren“ listet dieser Bereich jede Google-Schrift Ihrer Website mit Stilen und Stärken auf. Die Liste wächst, wenn auf anderen Seiten weitere Google-Fonts-Stylesheets gefunden werden.',
	'Stylesheet handle:' => 'Stylesheet-Handle:',
	'In most situations you can safely unload all italic styles. Modern browsers can mimic italics.' => 'Meist können Sie alle kursiven Stile bedenkenlos abwählen. Moderne Browser können Kursivschrift nachbilden.',
	'Unload italics' => 'Kursive nicht laden',
