	'Use templates on pages not built with Velox' => 'Vorlagen auch für Seiten ohne Velox-Layout verwenden',
	'Pages and posts made in the WordPress editor get your template (navbar, footer) with their content in its Inner Content slot. Off: they keep the theme.' => 'Seiten und Beiträge aus dem WordPress-Editor erhalten Ihre Vorlage (Navigation, Footer), ihr Inhalt landet im Inner-Content-Bereich. Aus: Sie behalten das Theme.',
