	'Tokens' => 'Tokens',
	'Unit or design token' => 'Einheit oder Design-Token',
	'The fluid scales (--text-xs … --text-5xl, --space-3xs … --space-3xl) and custom tokens are set under Velox Builder → Global styles → Design tokens. Every size field lists them in its unit menu.' => 'Die fließenden Skalen (--text-xs … --text-5xl, --space-3xs … --space-3xl) und eigene Tokens stellen Sie unter Velox Builder → Globale Stile → Design-Tokens ein. Jedes Größenfeld zeigt sie in seinem Einheiten-Menü.',
	'Open Global styles' => 'Globale Stile öffnen',
	'Design tokens' => 'Design-Tokens',
	'Named values every page can use as var(--name). In the editor, each size field lists the tokens that fit it in its unit menu. Change a token here and every place that uses it follows.' => 'Benannte Werte, die jede Seite als var(--name) nutzen kann. Im Editor zeigt jedes Größenfeld die passenden Tokens in seinem Einheiten-Menü. Ändern Sie hier ein Token, folgt jede Stelle, die es nutzt.',
	'Fluid type scale' => 'Fließende Schriftskala',
	'Output the --text-* tokens' => 'Die --text-*-Tokens ausgeben',
	'Font sizes that grow smoothly from the small to the large screen: no breakpoints needed. Each step is the step below times the ratio.' => 'Schriftgrößen, die vom kleinen zum großen Bildschirm stufenlos wachsen – ohne Breakpoints. Jede Stufe ist die Stufe darunter mal dem Verhältnis.',
