	'Show this element only to some visitors, on some pages or at some times. Without conditions it always shows.' => 'Zeigen Sie dieses Element nur bestimmten Besuchern, auf bestimmten Seiten oder zu bestimmten Zeiten. Ohne Bedingungen ist es immer sichtbar.',
	'Add condition' => 'Bedingung hinzufügen',
