	'Lists what the page is showing: the posts of a category, tag, author, date or search. Use it in archive and search templates. The editor previews the latest posts.' => 'Listet, was die Seite gerade zeigt: die Beiträge einer Kategorie, eines Schlagworts, Autors, Datums oder einer Suche. Für Archiv- und Suchvorlagen. Der Editor zeigt als Vorschau die neuesten Beiträge.',
