	// Velox Builder 4.31
	'Which template is used here?' => 'Welche Vorlage wird hier verwendet?',
	'Paste any address on this site to see which template it gets, and why.' => 'Fügen Sie eine Adresse dieser Website ein, um zu sehen, welche Vorlage sie bekommt – und warum.',
	'Address to check' => 'Zu prüfende Adresse',
	'Which template a page gets: the one chosen on the page itself; otherwise a template whose “Where to use” rules match; otherwise a template made for it (Front page, then Posts or Pages); otherwise the site default; otherwise a Catch-all template. 404, Search and Archives templates are used for those screens.' => 'Welche Vorlage eine Seite bekommt: die auf der Seite selbst gewählte; sonst eine Vorlage, deren „Wo verwenden“-Regeln passen; sonst eine Vorlage, die dafür gemacht ist (Startseite, dann Beiträge oder Seiten); sonst der Website-Standard; sonst eine Auffang-Vorlage. Vorlagen für 404, Suche und Archive gelten für diese Ansichten.',
	'Choose exactly where this template is used' => 'Genau festlegen, wo diese Vorlage verwendet wird',
	'Where to use' => 'Wo verwenden',
	'Where to use this template' => 'Wo diese Vorlage verwendet wird',
	'Use on' => 'Verwenden auf',
	'Add a place' => 'Ort hinzufügen',
	'But not on' => 'Aber nicht auf',
	'Add an exception' => 'Ausnahme hinzufügen',
	'For' => 'Für',
	'Everyone' => 'Alle',
	'Logged-in visitors only' => 'Nur angemeldete Besucher',
	'Logged-out visitors only' => 'Nur abgemeldete Besucher',
	'When two templates match the same page, the higher priority wins; on a tie, the more specific rule wins (a single page beats a post type, which beats the entire site). A template chosen on the page itself always wins.' => 'Passen zwei Vorlagen auf dieselbe Seite, gewinnt die höhere Priorität; bei Gleichstand die genauere Regel (eine einzelne Seite schlägt einen Inhaltstyp, der die ganze Website schlägt). Eine auf der Seite selbst gewählte Vorlage gewinnt immer.',
	'Rules apply once the template is published. With no “Use on” rules, the template works by its purpose as before.' => 'Die Regeln gelten, sobald die Vorlage veröffentlicht ist. Ohne „Verwenden auf“-Regeln richtet sich die Vorlage wie bisher nach ihrem Zweck.',
	'IDs, e.g. 12, 40' => 'IDs, z. B. 12, 40',
