	'Editable in each copy' => 'In jeder Kopie bearbeitbar',
	'Component' => 'Komponente',
	'This component no longer exists.' => 'Diese Komponente gibt es nicht mehr.',
	'Used on 1 page' => 'Auf 1 Seite verwendet',
	'Edit component' => 'Komponente bearbeiten',
	'Nothing in this component can be changed per copy yet. Open it, select an element and tick “Editable in each copy” in its Settings tab.' => 'In dieser Komponente lässt sich pro Kopie noch nichts ändern. Öffnen Sie sie, wählen Sie ein Element und haken Sie im Tab „Einstellungen“ „In jeder Kopie bearbeitbar“ an.',
