	'Reset this copy to the component' => 'Diese Kopie auf die Komponente zurücksetzen',
	'Empty fields use the component’s own content. Changing the component updates every copy; what you set here stays.' => 'Leere Felder nutzen den Inhalt der Komponente. Änderungen an der Komponente gelten für jede Kopie; was Sie hier festlegen, bleibt erhalten.',
	'Component property' => 'Komponenten-Eigenschaft',
