	// Velox Builder 4.34
	'Who can use the builder' => 'Wer den Builder nutzen darf',
	'Administrators can always do everything. Give other roles access to the pages they may edit in WordPress:' => 'Administratoren dürfen immer alles. Geben Sie anderen Rollen Zugriff auf die Seiten, die sie in WordPress bearbeiten dürfen:',
	'Client' => 'Kunde',
	'changes text, images, links and component fields. Layout and styles stay as they are.' => 'ändert Texte, Bilder, Links und Komponenten-Felder. Layout und Stile bleiben, wie sie sind.',
	'Designer' => 'Designer',
	'changes layout, styles and element settings, and can start a Velox layout for a page. No custom CSS or JavaScript.' => 'ändert Layout, Stile und Element-Einstellungen und kann für eine Seite ein Velox-Layout anlegen. Kein eigenes CSS oder JavaScript.',
	'Templates, components, global styles, fonts and these settings stay with administrators.' => 'Vorlagen, Komponenten, globale Stile, Schriften und diese Einstellungen bleiben bei den Administratoren.',
	'Builder access for %s' => 'Builder-Zugriff für %s',
	'No access' => 'Kein Zugriff',
	'May publish' => 'Darf veröffentlichen',
	'Without “May publish”, their changes are saved and wait for an administrator to publish them. Every save is kept under History → Saved versions.' => 'Ohne „Darf veröffentlichen“ werden ihre Änderungen gespeichert und warten darauf, dass ein Administrator sie veröffentlicht. Jedes Speichern bleibt unter Verlauf → Gespeicherte Versionen erhalten.',
	'You are not allowed to edit this with Velox Builder.' => 'Sie dürfen dies nicht mit dem Velox Builder bearbeiten.',
	'You are not allowed to edit this.' => 'Sie dürfen dies nicht bearbeiten.',
	'Your role may save changes but not publish them. An administrator publishes them.' => 'Ihre Rolle darf Änderungen speichern, aber nicht veröffentlichen. Ein Administrator veröffentlicht sie.',
	'Your role can change text, images and links. Layout and styles stay as they are.' => 'Ihre Rolle darf Texte, Bilder und Links ändern. Layout und Stile bleiben, wie sie sind.',
	'Custom CSS and JavaScript are managed by an administrator.' => 'Eigenes CSS und JavaScript verwaltet ein Administrator.',
	'Double-click the text on the page to change it.' => 'Doppelklicken Sie auf den Text auf der Seite, um ihn zu ändern.',
	'Describe the image' => 'Beschreiben Sie das Bild',
	'Nothing to change here. Select a text, an image or a button.' => 'Hier gibt es nichts zu ändern. Wählen Sie einen Text, ein Bild oder einen Button.',
