	'Popups' => 'Popups',
	'Every popup and slide-in panel on the site: when it appears, how often, and where it lives. A popup in a template or component shows on every page that uses it.' => 'Jedes Popup und jedes Einblend-Panel der Website: wann es erscheint, wie oft und wo es liegt. Ein Popup in einer Vorlage oder Komponente erscheint auf jeder Seite, die sie nutzt.',
	'No popups yet' => 'Noch keine Popups',
	'In the editor, open Add → Interactive and pick “Popup / modal” or one of the ready-made popups. Put it in a template to show it across the site.' => 'Öffnen Sie im Editor Hinzufügen → Interaktiv und wählen Sie „Popup / Modal“ oder eines der fertigen Popups. Legen Sie es in eine Vorlage, um es auf der ganzen Website zu zeigen.',
