	'Stay in the loop' => 'Bleiben Sie auf dem Laufenden',
	'One short email a month. No spam, unsubscribe any time.' => 'Eine kurze E-Mail im Monat. Kein Spam, jederzeit abbestellbar.',
	'Put your sign-up form here: paste its shortcode from Velox → Forms.' => 'Setzen Sie hier Ihr Anmeldeformular ein: Fügen Sie seinen Shortcode aus Velox → Formulare ein.',
	'Before you go…' => 'Bevor Sie gehen …',
	'Take 10% off your first order with the code WELCOME10.' => 'Sparen Sie 10 % bei Ihrer ersten Bestellung mit dem Code WELCOME10.',
