	// Velox Builder 4.37
	'Then go to this page' => 'Danach zu dieser Seite gehen',
	'Optional. Leave empty to stay on the page and show the message.' => 'Optional. Leer lassen, um auf der Seite zu bleiben und die Meldung zu zeigen.',
	'Send the answers to a webhook' => 'Antworten an einen Webhook senden',
	'Optional. Each entry is posted there as JSON (Zapier, Make, n8n, a CRM). Signed with the %s header so the receiver can check it came from this site.' => 'Optional. Jeder Eintrag wird dorthin als JSON gesendet (Zapier, Make, n8n, ein CRM). Signiert mit dem Header %s, damit der Empfänger prüfen kann, dass er von dieser Website kommt.',
	'Block forms sent within seconds' => 'Formulare blockieren, die in Sekunden abgeschickt werden',
	'People need a few seconds to fill in a form; spam bots send it instantly. Works together with the hidden honeypot field, invisibly.' => 'Menschen brauchen ein paar Sekunden, um ein Formular auszufüllen; Spam-Bots senden es sofort. Arbeitet unsichtbar zusammen mit dem versteckten Honeypot-Feld.',
	'This form is hidden: switch on Velox → Utilities → Mail to receive forms. (Only administrators see this.)' => 'Dieses Formular ist ausgeblendet: Schalten Sie Velox → Werkzeuge → Mail ein, um Formulare zu empfangen. (Nur Administratoren sehen das.)',
	'Form — choose which one in Settings' => 'Formular — wählen Sie es in den Einstellungen',
	'Forms are switched off. Turn on Velox → Utilities → Mail to show forms and receive entries.' => 'Formulare sind ausgeschaltet. Schalten Sie Velox → Werkzeuge → Mail ein, um Formulare zu zeigen und Einträge zu empfangen.',
	'No forms yet. Create one, then pick it here.' => 'Noch keine Formulare. Erstellen Sie eines und wählen Sie es dann hier.',
