	'This form is switched off and hidden from visitors.' => 'Dieses Formular ist ausgeschaltet und für Besucher ausgeblendet.',
	'Fields, emails, the thank-you page, webhooks and spam protection are set in the form itself. Entries arrive in Velox → Mail.' => 'Felder, E-Mails, die Danke-Seite, Webhooks und der Spamschutz werden im Formular selbst eingestellt. Einträge landen in Velox → Mail.',
