	'Import & export' => 'Import & Export',
	'Move pages, templates, components and your design system to another Velox site as one file, or keep a copy. To move a single element, copy it in the editor and paste it on the other site.' => 'Übertragen Sie Seiten, Vorlagen, Komponenten und Ihr Design-System als eine Datei auf eine andere Velox-Website, oder behalten Sie eine Kopie. Ein einzelnes Element kopieren Sie im Editor und fügen es auf der anderen Website ein.',
	'Choose what goes into the file. Components and forms that your choice uses come along by themselves.' => 'Wählen Sie, was in die Datei kommt. Komponenten und Formulare, die Ihre Auswahl nutzt, kommen von selbst mit.',
