	'Choose what to export.' => 'Wählen Sie, was exportiert werden soll.',
	'This file is larger than this server accepts (%s). Export fewer items at a time, or ask your host to raise post_max_size.' => 'Diese Datei ist größer, als dieser Server annimmt (%s). Exportieren Sie weniger auf einmal oder bitten Sie Ihren Hoster, post_max_size zu erhöhen.',
