	// Velox Builder 4.39
	'your-application-password' => 'ihr-anwendungspasswort',
	'AI agents' => 'KI-Agenten',
	'Let AI tools such as Claude, ChatGPT or Cursor read your design system and build pages with Velox Builder. They work in drafts; you check and publish.' => 'Lassen Sie KI-Werkzeuge wie Claude, ChatGPT oder Cursor Ihr Design-System lesen und Seiten mit Velox Builder bauen. Sie arbeiten in Entwürfen; Sie prüfen und veröffentlichen.',
	'Let AI agents work on this site' => 'KI-Agenten auf dieser Website arbeiten lassen',
	'An agent signs in as a WordPress user and can only do what that user may do in the builder.' => 'Ein Agent meldet sich als WordPress-Benutzer an und darf nur, was dieser Benutzer im Builder darf.',
	'WordPress 6.9 or newer' => 'WordPress 6.9 oder neuer',
	'This WordPress can describe what plugins can do to AI tools (the Abilities API).' => 'Dieses WordPress kann KI-Werkzeugen beschreiben, was Plugins können (die Abilities-API).',
	'Update WordPress to use AI agents.' => 'Aktualisieren Sie WordPress, um KI-Agenten zu nutzen.',
	'MCP Adapter plugin' => 'Plugin „MCP Adapter“',
	'Installed and active. AI tools connect through it.' => 'Installiert und aktiv. KI-Werkzeuge verbinden sich darüber.',
	'The official WordPress plugin that connects AI tools (over MCP). Install and activate it.' => 'Das offizielle WordPress-Plugin, das KI-Werkzeuge verbindet (über MCP). Installieren und aktivieren Sie es.',
	'Find it in Plugins' => 'Unter Plugins finden',
	'Connect your AI tool' => 'Ihr KI-Werkzeug verbinden',
	'Once, on the computer where the AI tool runs.' => 'Einmalig, auf dem Computer, auf dem das KI-Werkzeug läuft.',
	'Create an application password' => 'Ein Anwendungspasswort erstellen',
	'In your profile, under Application Passwords, give it a name such as “Claude” and copy the password it shows. You can revoke it there at any time.' => 'Geben Sie in Ihrem Profil unter „Anwendungspasswörter“ einen Namen wie „Claude“ ein und kopieren Sie das angezeigte Passwort. Sie können es dort jederzeit widerrufen.',
	'Open my profile' => 'Mein Profil öffnen',
	'Add this server to the AI tool' => 'Diesen Server im KI-Werkzeug eintragen',
	'In Claude Desktop: Settings → Developer → Edit config. Other tools have a similar MCP settings file. Put the application password in place of the placeholder. Node.js must be installed.' => 'In Claude Desktop: Einstellungen → Entwickler → Konfiguration bearbeiten. Andere Werkzeuge haben eine ähnliche MCP-Einstellungsdatei. Setzen Sie das Anwendungspasswort anstelle des Platzhalters ein. Node.js muss installiert sein.',
	'Ask for something' => 'Etwas erbitten',
	'For example: “Look at the Velox design system, then build a landing page for our spring offer with a hero, three benefits and a contact form.”' => 'Zum Beispiel: „Sieh dir das Velox-Design-System an und baue dann eine Landingpage für unser Frühlingsangebot mit Hero, drei Vorteilen und einem Kontaktformular.“',
	'What an agent can do' => 'Was ein Agent kann',
	'It works only in drafts: nothing changes for visitors until a person publishes. Every change is kept under History → Saved versions, marked “By AI”.' => 'Er arbeitet nur in Entwürfen: Für Besucher ändert sich nichts, bis ein Mensch veröffentlicht. Jede Änderung bleibt unter Verlauf → Gespeicherte Versionen erhalten, markiert mit „Von KI“.',
	'Read the design system and build pages, templates and components with Velox Builder. Changes are saved as drafts.' => 'Das Design-System lesen und Seiten, Vorlagen und Komponenten mit Velox Builder bauen. Änderungen werden als Entwürfe gespeichert.',
	'Get the design system' => 'Design-System lesen',
