	'Style a class' => 'Eine Klasse gestalten',
	'Give it a title.' => 'Geben Sie einen Titel an.',
	'There is no element with that parent_id in this document.' => 'In diesem Dokument gibt es kein Element mit dieser parent_id.',
	'That element cannot hold other elements. Use a section, div, columns or grid.' => 'Dieses Element kann keine anderen Elemente enthalten. Nutzen Sie section, div, columns oder grid.',
	'There is no element with that id in this document.' => 'In diesem Dokument gibt es kein Element mit dieser ID.',
	'A template needs its Inner Content element; it cannot be removed.' => 'Eine Vorlage braucht ihr Inner-Content-Element; es kann nicht entfernt werden.',
	'Class names start with a dot and use letters, numbers, - and _.' => 'Klassennamen beginnen mit einem Punkt und bestehen aus Buchstaben, Ziffern, - und _.',
	'Too many elements at once. Add them in smaller parts.' => 'Zu viele Elemente auf einmal. Fügen Sie sie in kleineren Teilen hinzu.',
	'Unknown element type. Use one of: %s' => 'Unbekannter Elementtyp. Nutzen Sie einen von: %s',
	'component_id must be the id of a component (see velox/list-documents).' => 'component_id muss die ID einer Komponente sein (siehe velox/list-documents).',
	'A %s cannot hold other elements. Use a section, div, columns or grid.' => 'Ein(e) %s kann keine anderen Elemente enthalten. Nutzen Sie section, div, columns oder grid.',
	'This element can use these tags: %s' => 'Dieses Element kann diese Tags nutzen: %s',
	'That link is not allowed. Use an address (https://…, /page/ or #section), mailto: or tel:.' => 'Dieser Link ist nicht erlaubt. Nutzen Sie eine Adresse (https://…, /seite/ oder #abschnitt), mailto: oder tel:.',
	'There is no form with that id (see the forms in velox/get-design-system).' => 'Es gibt kein Formular mit dieser ID (siehe die Formulare in velox/get-design-system).',
