	'Every section, columns block and div block starts with these. In the style panel they show greyed out; typing a value there changes that element or class only.' => 'Jede Sektion, jeder Spalten-Block und jeder Div-Block startet mit diesen Werten. Im Stil-Panel erscheinen sie ausgegraut; ein dort getippter Wert ändert nur dieses Element bzw. diese Klasse.',
