	'Adds “Velox Shop” to the admin menu: orders, products, coupons, customers and all shop settings in one place.' => 'Fügt „Velox Shop“ zum Admin-Menü hinzu: Bestellungen, Produkte, Gutscheine, Kunden und alle Shop-Einstellungen an einem Ort.',
	'Open Velox Shop' => 'Velox Shop öffnen',
