	'We confirm your order and send you the payment details by email.' => 'Wir bestätigen Ihre Bestellung und senden Ihnen die Zahlungsdaten per E-Mail.',
	'We will email you the payment details.' => 'Wir senden Ihnen die Zahlungsdaten per E-Mail.',
	'Your order is reserved until then.' => 'Ihre Bestellung ist bis dahin reserviert.',
	'Product photos in the grid' => 'Produktfotos im Raster',
	'Portrait 4:5' => 'Hochformat 4:5',
	'Their own shape' => 'Originalformat',
	'Cropped photos line up evenly; “their own shape” never cuts anything off (best for art).' => 'Zugeschnittene Fotos stehen gleichmäßig; „Originalformat“ schneidet nie etwas ab (am besten für Kunst).',
	// 4.54 — appearance switch and accessibility menu
	'All of Velox' => 'Ganz Velox',
	'Same as Velox' => 'Wie Velox',
	'This screen' => 'Dieser Bildschirm',
	'Only for you — everyone chooses their own.' => 'Nur für Sie — jede Person wählt selbst.',
	'Switch between light and dark' => 'Zwischen hell und dunkel wechseln',
	'Appearance settings' => 'Darstellung einstellen',
	'Accessibility menu' => 'Barrierefreiheitsmenü',
	'Visitor display aids' => 'Anzeigehilfen für Besucher',
	'A button on every page that opens display aids for visitors: bigger text, more spacing, contrast, a readable font, highlighted links, no animations, a reading guide and read-aloud. Each visitor\'s choice is remembered in their browser.' => 'Ein Button auf jeder Seite, der Anzeigehilfen für Besucher öffnet: größere Schrift, mehr Abstand, Kontrast, eine gut lesbare Schrift, hervorgehobene Links, keine Animationen, eine Lesehilfe und Vorlesen. Die Auswahl jedes Besuchers bleibt in seinem Browser gespeichert.',
	'One click sets several aids at once: low vision, dyslexia friendly, seizure safe, focus.' => 'Ein Klick stellt mehrere Hilfen auf einmal ein: Sehschwäche, Legasthenie, Epilepsie, Konzentration.',
	'Text size' => 'Schriftgröße',
	'Three steps up to +50 %.' => 'Drei Stufen bis +50 %.',
	'More line, letter and word spacing.' => 'Mehr Zeilen-, Buchstaben- und Wortabstand.',
	'Contrast' => 'Kontrast',
	'Dark, light or greyscale.' => 'Dunkel, hell oder Graustufen.',
	'Readable font' => 'Lesbare Schrift',
	'A plain, wide font instead of the design font.' => 'Eine schlichte, breite Schrift statt der Design-Schrift.',
	'Highlight links' => 'Links hervorheben',
	'Every link underlined and outlined.' => 'Jeder Link unterstrichen und umrandet.',
	'Stop animations' => 'Animationen stoppen',
	'Animations, transitions and videos stop.' => 'Animationen, Übergänge und Videos halten an.',
	'Hide images' => 'Bilder ausblenden',
	'Pictures and background images fade out; the layout stays.' => 'Bilder und Hintergrundbilder werden ausgeblendet; das Layout bleibt.',
	'Big cursor' => 'Großer Mauszeiger',
	'A large, high-contrast mouse pointer.' => 'Ein großer Mauszeiger mit starkem Kontrast.',
	'Reading guide' => 'Lesehilfe',
	'Dims the page except a band around the pointer.' => 'Dunkelt die Seite ab, bis auf einen Streifen um den Mauszeiger.',
	'Read aloud' => 'Vorlesen',
	'Clicked text is read out by the browser\'s own voice. Hidden in browsers without one.' => 'Angeklickter Text wird mit der Stimme des Browsers vorgelesen. In Browsern ohne Stimme ausgeblendet.',
	'A button on every page of your site that opens display aids for your visitors. Each visitor\'s choice is remembered in their own browser — nothing is stored on your server.' => 'Ein Button auf jeder Seite Ihrer Website, der Anzeigehilfen für Ihre Besucher öffnet. Die Auswahl bleibt im Browser des jeweiligen Besuchers gespeichert — auf Ihrem Server wird nichts gespeichert.',
	'Accessibility menu for visitors' => 'Barrierefreiheitsmenü für Besucher',
	'On — visitors see the button on every page.' => 'An — Besucher sehen den Button auf jeder Seite.',
	'Off — visitors do not see it. Switch it on whenever you like.' => 'Aus — Besucher sehen ihn nicht. Schalten Sie ihn jederzeit ein.',
	'See it on your site' => 'Auf der Website ansehen',
	'Look and place' => 'Aussehen und Platz',
	'Pick the corner your cookie or chat button does not use.' => 'Wählen Sie die Ecke, die Ihr Cookie- oder Chat-Button nicht belegt.',
	'Use a strong colour: the white icon needs good contrast on it.' => 'Nehmen Sie eine kräftige Farbe: Das weiße Symbol braucht darauf guten Kontrast.',
	'Show on phones' => 'Auf Smartphones zeigen',
	'Phones have their own zoom and accessibility settings; switch this off if the button gets in the way there.' => 'Smartphones haben eigene Zoom- und Bedienungshilfen; schalten Sie das aus, wenn der Button dort stört.',
	'Accessibility statement' => 'Erklärung zur Barrierefreiheit',
	'Shops that fall under the BFSG need one. Linked at the bottom of the menu.' => 'Shops, die unter das BFSG fallen, brauchen eine. Wird unten im Menü verlinkt.',
	'What the menu offers' => 'Was das Menü anbietet',
	'What this menu is — and is not' => 'Was dieses Menü ist — und was nicht',
	'It lets visitors adjust how your pages look. It does not make a site accessible or BFSG / WCAG compliant on its own: that comes from the pages themselves — real headings, alt texts, enough contrast, labelled form fields, everything usable by keyboard. Velox Builder\'s page check finds most of these.' => 'Es lässt Besucher anpassen, wie Ihre Seiten aussehen. Barrierefrei oder BFSG-/WCAG-konform wird eine Website dadurch allein nicht: Das kommt von den Seiten selbst — echte Überschriften, Alt-Texte, genug Kontrast, beschriftete Formularfelder, alles per Tastatur bedienbar. Der Seiten-Check im Velox Builder findet das meiste davon.',
	'Adjust this website to how you read best. Your choice is saved in this browser.' => 'Passen Sie diese Website so an, wie Sie am besten lesen. Ihre Auswahl wird in diesem Browser gespeichert.',
	'Adjustments' => 'Anpassungen',
