	// 4.56 — customer accounts
	'Email or password is not right. Please try again.' => 'E-Mail oder Passwort stimmt nicht. Bitte versuchen Sie es noch einmal.',
	'Too many attempts. Please wait a few minutes.' => 'Zu viele Versuche. Bitte warten Sie ein paar Minuten.',
	'Creating accounts is switched off for this shop.' => 'In diesem Shop können keine Konten angelegt werden.',
	'There is already an account for this email. Sign in or reset your password.' => 'Für diese E-Mail gibt es schon ein Konto. Melden Sie sich an oder setzen Sie Ihr Passwort zurück.',
	'Please choose a password with at least 8 characters.' => 'Bitte wählen Sie ein Passwort mit mindestens 8 Zeichen.',
	'Please enter your first and last name.' => 'Bitte geben Sie Vor- und Nachnamen ein.',
	'Please confirm that you have read the privacy policy.' => 'Bitte bestätigen Sie, dass Sie die Datenschutzerklärung gelesen haben.',
	'The account could not be created. Please try again.' => 'Das Konto konnte nicht angelegt werden. Bitte versuchen Sie es noch einmal.',
	'Welcome! Your account is ready.' => 'Willkommen! Ihr Konto ist eingerichtet.',
	'If there is an account for this address, a link to set a new password is on its way. Please check your inbox.' => 'Wenn es zu dieser Adresse ein Konto gibt, ist ein Link zum Festlegen eines neuen Passworts unterwegs. Bitte schauen Sie in Ihr Postfach.',
	'This link is no longer valid. Please ask for a new one.' => 'Dieser Link ist nicht mehr gültig. Bitte fordern Sie einen neuen an.',
	'Your new password is set. You can sign in now.' => 'Ihr neues Passwort ist gespeichert. Sie können sich jetzt anmelden.',
	'The two passwords do not match.' => 'Die beiden Passwörter stimmen nicht überein.',
	'Your current password is not right.' => 'Ihr aktuelles Passwort stimmt nicht.',
	'Your password has been changed.' => 'Ihr Passwort wurde geändert.',
	'Your email address has been changed.' => 'Ihre E-Mail-Adresse wurde geändert.',
	'This email address belongs to another account.' => 'Diese E-Mail-Adresse gehört zu einem anderen Konto.',
	'Your account has been deleted. Orders are kept as long as the law requires.' => 'Ihr Konto wurde gelöscht. Bestellungen werden so lange aufbewahrt, wie es das Gesetz verlangt.',
	'Please tick the box to confirm.' => 'Bitte setzen Sie zur Bestätigung den Haken.',
	'The page had expired. Please try again.' => 'Die Seite war abgelaufen. Bitte versuchen Sie es noch einmal.',
	'You are signed out.' => 'Sie sind abgemeldet.',
