	'On the account page: sign in, create an account, forgotten password — without WordPress’s own login page. Customers never see the dashboard.' => 'Auf der Konto-Seite: anmelden, Konto anlegen, Passwort vergessen — ohne die WordPress-Anmeldeseite. Kunden sehen das Dashboard nie.',
