	'%1$d items %2$s.' => '%1$d Einträge %2$s.',
	'Only %d left' => 'Nur noch %d übrig',
	// 4.57 — sold items, reopen orders
	'This order cannot be reopened: %s is no longer in stock. It has probably been sold again in the meantime.' => 'Diese Bestellung lässt sich nicht wieder öffnen: %s ist nicht mehr vorrätig. Wahrscheinlich wurde es inzwischen noch einmal verkauft.',
	'Reopened — the order is active again and its items are reserved.' => 'Wieder geöffnet — die Bestellung ist wieder aktiv und die Artikel sind reserviert.',
	'Order active again' => 'Bestellung wieder aktiv',
	'To the customer when you reopen a cancelled order.' => 'An den Kunden, wenn Sie eine stornierte Bestellung wieder öffnen.',
	'Your order %s is active again' => 'Ihre Bestellung %s ist wieder aktiv',
	'good news: your order is active again and the items are reserved for you.' => 'gute Nachrichten: Ihre Bestellung ist wieder aktiv und die Artikel sind für Sie reserviert.',
	'Reopened. The items are reserved again and the customer has been told.' => 'Wieder geöffnet. Die Artikel sind wieder reserviert und der Kunde ist informiert.',
	'Reopened. The items are reserved again.' => 'Wieder geöffnet. Die Artikel sind wieder reserviert.',
	'Reopen order' => 'Bestellung wieder öffnen',
	'This order is cancelled' => 'Diese Bestellung ist storniert',
	'Its items are back in the shop. Cancelled by mistake? Reopen it and the items are reserved again.' => 'Die Artikel sind wieder im Shop. Aus Versehen storniert? Öffnen Sie die Bestellung wieder, dann sind die Artikel erneut reserviert.',
	'Reopen this order?' => 'Bestellung wieder öffnen?',
	'The order is active again and its items are taken out of stock again.' => 'Die Bestellung ist wieder aktiv und die Artikel werden wieder aus dem Bestand genommen.',
	'It waits for payment like a new order.' => 'Sie wartet wie eine neue Bestellung auf die Zahlung.',
