	'Hide them' => 'Ausblenden',
	'A cancelled order puts its items back, and they show up as available again.' => 'Eine stornierte Bestellung gibt ihre Artikel zurück, sie erscheinen dann wieder als verfügbar.',
	// 4.58 — customer management
