	'Create an account and the customer gets an email to choose a password. Their orders show up in it right away.' => 'Legen Sie ein Konto an: Der Kunde bekommt eine E-Mail, um ein Passwort zu wählen. Seine Bestellungen erscheinen sofort darin.',
