	'Staff' => 'Mitarbeiter',
	'The account and saved address are deleted for good. Orders are kept (tax law), but no longer linked to an account. This cannot be undone.' => 'Konto und gespeicherte Adresse werden endgültig gelöscht. Bestellungen bleiben erhalten (Steuerrecht), sind aber mit keinem Konto mehr verbunden. Das lässt sich nicht rückgängig machen.',
	'The customer cannot sign in. Orders still work as a guest.' => 'Der Kunde kann sich nicht anmelden. Als Gast bestellen geht weiterhin.',
	'The customer gets an email with a link to choose a new password. The link works for 24 hours; the current password keeps working until then.' => 'Der Kunde bekommt eine E-Mail mit einem Link zum Wählen eines neuen Passworts. Der Link gilt 24 Stunden; das jetzige Passwort funktioniert bis dahin weiter.',
	'The customer is signed out and cannot sign in until you unlock the account. Orders and data stay.' => 'Der Kunde wird abgemeldet und kann sich erst wieder anmelden, wenn Sie das Konto entsperren. Bestellungen und Daten bleiben.',
