	'%d recovery codes left' => '%d Wiederherstellungscodes übrig',
	'As soon as you order, you can follow it here.' => 'Sobald Sie bestellen, können Sie die Bestellung hier verfolgen.',
	'Besides your password, a 6-digit code from an app on your phone. Even someone who knows your password cannot get in.' => 'Zusätzlich zum Passwort ein 6-stelliger Code aus einer App auf Ihrem Handy. Selbst wer Ihr Passwort kennt, kommt dann nicht hinein.',
	'Browser' => 'Browser',
	'Cannot scan? Enter this key:' => 'Scannen klappt nicht? Geben Sie diesen Schlüssel ein:',
	'Code from the app' => 'Code aus der App',
	'Confirm and sign in' => 'Bestätigen und anmelden',
	'Customer since %s' => 'Kunde seit %s',
	'Downloads always at hand' => 'Downloads immer griffbereit',
	'Each code works once, if you ever cannot use your phone. Save them now — they are shown only this one time.' => 'Jeder Code funktioniert einmal, falls Sie Ihr Handy einmal nicht nutzen können. Speichern Sie sie jetzt — sie werden nur dieses eine Mal angezeigt.',
	'Enter the code' => 'Code eingeben',
	'Everything you bought at %s, in one place.' => 'Alles, was Sie bei %s gekauft haben, an einem Ort.',
	'For a customer who lost their phone and their recovery codes. Make sure it really is them — for example by replying to an email from their address. They are signed out and can sign in with their password again.' => 'Für Kunden, die Handy und Wiederherstellungscodes verloren haben. Stellen Sie sicher, dass es wirklich die Person ist — zum Beispiel per Antwort auf eine E-Mail von ihrer Adresse. Sie wird abgemeldet und kann sich wieder mit ihrem Passwort anmelden.',
	'How we address you, and the name on new invoices.' => 'Wie wir Sie ansprechen, und der Name auf neuen Rechnungen.',
	'In progress' => 'In Bearbeitung',
	'Latest order' => 'Letzte Bestellung',
	'Make new codes' => 'Neue Codes erstellen',
	'Makes 10 new codes; the old ones stop working.' => 'Erstellt 10 neue Codes; die alten funktionieren dann nicht mehr.',
	'New here? Create an account' => 'Neu hier? Konto anlegen',
	'New password' => 'Neues Passwort',
	'New recovery codes' => 'Neue Wiederherstellungscodes',
	'New recovery codes are ready. The old ones no longer work.' => 'Neue Wiederherstellungscodes sind bereit. Die alten funktionieren nicht mehr.',
	'No orders yet' => 'Noch keine Bestellungen',
	'No phone at hand? Enter one of your recovery codes instead.' => 'Kein Handy zur Hand? Geben Sie stattdessen einen Ihrer Wiederherstellungscodes ein.',
	'Not saved yet' => 'Noch nicht gespeichert',
	'Open your authenticator app and enter the 6-digit code for this shop.' => 'Öffnen Sie Ihre Authenticator-App und geben Sie den 6-stelligen Code für diesen Shop ein.',
	'Ordered' => 'Bestellt',
	'Orders, invoices and downloads in one place — and faster checkout.' => 'Bestellungen, Rechnungen und Downloads an einem Ort — und schneller zur Kasse.',
	'Orders, invoices and tracking at any time' => 'Bestellungen, Rechnungen und Sendungsverfolgung jederzeit',
	'Password only' => 'Nur Passwort',
	'Profile' => 'Profil',
	'Protect your account' => 'Schützen Sie Ihr Konto',
	'Protected with two-factor sign-in if you like' => 'Auf Wunsch mit Zwei-Faktor-Anmeldung geschützt',
	'Scan the code' => 'Code scannen',
	'Set up two-factor sign-in' => 'Zwei-Faktor-Anmeldung einrichten',
	'Sign out on all other devices' => 'Auf allen anderen Geräten abmelden',
	'Signed in %s' => 'Angemeldet %s',
	'Signed in with a recovery code. It cannot be used again.' => 'Mit einem Wiederherstellungscode angemeldet. Er kann nicht noch einmal verwendet werden.',
	'Signed-in devices' => 'Angemeldete Geräte',
	'So every page that does not come from the page cache — cart, checkout, customer account, and everything while you are signed in — compiles WordPress and all plugins from scratch (about %s of PHP code). That costs roughly 0.3 to 0.5 seconds per page.' => 'Deshalb übersetzt jede Seite, die nicht aus dem Seiten-Cache kommt — Warenkorb, Kasse, Kundenkonto und alles, solange Sie angemeldet sind — WordPress und alle Plugins jedes Mal neu (etwa %s PHP-Code). Das kostet pro Seite etwa 0,3 bis 0,5 Sekunden.',
	'That code is not right. Please try again — use the newest code from your app.' => 'Dieser Code stimmt nicht. Bitte versuchen Sie es noch einmal — mit dem neuesten Code aus Ihrer App.',
	'This account uses two-factor sign-in. Please sign in on the shop’s account page.' => 'Dieses Konto nutzt die Zwei-Faktor-Anmeldung. Bitte melden Sie sich auf der Konto-Seite des Shops an.',
	'This is a server setting. In Plesk: Tools & Settings → PHP Settings → PHP %s → raise opcache.memory_consumption to 256 and opcache.interned_strings_buffer to 32, switch opcache.enable on, then restart PHP-FPM. On shared hosting, ask your host to do it.' => 'Das ist eine Server-Einstellung. In Plesk: Tools & Einstellungen → PHP-Einstellungen → PHP %s → opcache.memory_consumption auf 256 und opcache.interned_strings_buffer auf 32 erhöhen, opcache.enable einschalten, dann PHP-FPM neu starten. Bei Shared Hosting bitten Sie Ihren Hoster darum.',
	'Too much time has passed. Please sign in again.' => 'Es ist zu viel Zeit vergangen. Bitte melden Sie sich noch einmal an.',
	'Turn off' => 'Ausschalten',
	'Turn off two-factor sign-in' => 'Zwei-Faktor-Anmeldung ausschalten',
	'Turn off two-factor sign-in?' => 'Zwei-Faktor-Anmeldung ausschalten?',
	'Turn on' => 'Einschalten',
	'Two-factor sign-in' => 'Zwei-Faktor-Anmeldung',
	'Two-factor sign-in is off for this customer. They sign in with their password and can set it up again.' => 'Die Zwei-Faktor-Anmeldung ist für diesen Kunden aus. Er meldet sich mit seinem Passwort an und kann sie neu einrichten.',
	'Two-factor sign-in is off.' => 'Die Zwei-Faktor-Anmeldung ist aus.',
	'Two-factor sign-in is on' => 'Zwei-Faktor-Anmeldung ist an',
	'Two-factor sign-in is on. Keep your recovery codes somewhere safe.' => 'Die Zwei-Faktor-Anmeldung ist an. Bewahren Sie Ihre Wiederherstellungscodes sicher auf.',
	'Use one you do not use anywhere else — at least 8 characters.' => 'Nutzen Sie eines, das Sie sonst nirgends verwenden — mindestens 8 Zeichen.',
	'Velox: PHP opcache is on, but keeps nothing.' => 'Velox: PHP-Opcache ist an, speichert aber nichts.',
	'Velox: PHP opcache is switched off.' => 'Velox: PHP-Opcache ist ausgeschaltet.',
	'Welcome back' => 'Willkommen zurück',
	'Where your account is signed in right now. Something you do not recognise? Sign out everywhere else and change your password.' => 'Wo Ihr Konto gerade angemeldet ist. Etwas, das Sie nicht kennen? Melden Sie sich überall sonst ab und ändern Sie Ihr Passwort.',
	'With two-factor sign-in, a code from your phone is needed besides your password.' => 'Mit der Zwei-Faktor-Anmeldung braucht es zusätzlich zum Passwort einen Code von Ihrem Handy.',
	'You are signed out on all other devices.' => 'Sie sind auf allen anderen Geräten abgemeldet.',
	'You sign in with it and get order emails there. Your old address is told about the change.' => 'Damit melden Sie sich an und erhalten dorthin Bestell-E-Mails. Ihre alte Adresse wird über die Änderung informiert.',
