	'Buy bar on product pages' => 'Kaufleiste auf Produktseiten',
	'Price and button stay in reach once the visitor scrolls past them — at the bottom on phones, floating on larger screens.' => 'Preis und Button bleiben griffbereit, sobald man daran vorbeiscrollt — unten auf dem Handy, schwebend auf größeren Bildschirmen.',
	'Shop page' => 'Shopseite',
	'Products before “Show more”' => 'Produkte vor „Mehr anzeigen“',
	'“New” badge' => 'Badge „Neu“',
	'First 7 days' => 'Die ersten 7 Tage',
	'First 14 days' => 'Die ersten 14 Tage',
	'First 30 days' => 'Die ersten 30 Tage',
	'First 60 days' => 'Die ersten 60 Tage',
	'Sale, sold and few-left badges come first.' => 'Sale-, Verkauft- und Nur-noch-wenige-Badges haben Vorrang.',
	'Sort menu' => 'Sortiermenü',
	'Recommended, newest, price up or down, name.' => 'Empfohlen, neueste, Preis auf- oder absteigend, Name.',
	'Search field' => 'Suchfeld',
	'Worth it from about 30 products.' => 'Lohnt sich ab etwa 30 Produkten.',
	'On the shop page the product count, categories, sorting and search sit above the grid. Every choice stays in the address, so Back and shared links land in the same place.' => 'Auf der Shopseite stehen Produktanzahl, Kategorien, Sortierung und Suche über dem Raster. Jede Auswahl bleibt in der Adresse, so landen Zurück und geteilte Links an derselben Stelle.',
	'Photos open full screen' => 'Fotos öffnen im Vollbild',
	'Click or tap a photo; arrows, swipe and Esc work.' => 'Foto anklicken oder antippen; Pfeiltasten, Wischen und Esc funktionieren.',
	'Under products without hand-picked suggestions.' => 'Unter Produkten ohne handverlesene Vorschläge.',
	'Reasons to buy' => 'Kaufgründe',
	'Free shipping from €50' => 'Kostenloser Versand ab 50 €',
	'30 days to return' => '30 Tage Rückgaberecht',
	'Secure payment with PayPal and card' => 'Sicher bezahlen mit PayPal und Karte',
	'One per line, up to six, under the buy button. The icon follows the words: shipping, returns, payment, gift, handmade.' => 'Einer pro Zeile, bis zu sechs, unter dem Kaufen-Button. Das Symbol richtet sich nach den Worten: Versand, Rückgabe, Bezahlung, Geschenk, handgemacht.',
	'Notice bar' => 'Hinweisleiste',
	'A slim bar across the top of every page' => 'Eine schmale Leiste oben auf jeder Seite',
	'Free shipping, a sale, holidays. Visitors can close it.' => 'Kostenloser Versand, ein Sale, Betriebsferien. Besucher können sie schließen.',
	'Free shipping in Germany from €50' => 'Kostenloser Versand in Deutschland ab 50 €',
	'Several lines take turns every five seconds.' => 'Mehrere Zeilen wechseln sich alle fünf Sekunden ab.',
	'Optional — the whole message becomes a link.' => 'Optional — die ganze Nachricht wird zum Link.',
	'Buttons and links in emails and on invoices.' => 'Buttons und Links in E-Mails und auf Rechnungen.',
	'The storefront’s colours, fonts and layout are under Design.' => 'Farben, Schriften und Aufbau des Shops finden Sie unter Design.',
	'Solid block' => 'Fläche',
	'More from the same category' => 'Mehr aus derselben Kategorie',
	'Product pages: photos, buy box and details from Velox Shop, between your header and footer.' => 'Produktseiten: Fotos, Kaufbox und Details aus Velox Shop, zwischen Ihrem Header und Footer.',
	// 4.62 — account security by email, order editing, payouts
	'+ Add a product…' => '+ Produkt hinzufügen …',
	'A refund takes the money from the same place: from Stripe or PayPal, or by bank transfer from you.' => 'Eine Erstattung kommt vom selben Ort: von Stripe oder PayPal – oder per Überweisung von Ihnen.',
	'Afterwards every device is signed out, this one too.' => 'Danach werden alle Geräte abgemeldet, auch dieses.',
	'Almost done: we sent a link to your new address. Your email changes as soon as you click it (within one hour).' => 'Fast geschafft: Wir haben einen Link an Ihre neue Adresse geschickt. Ihre E-Mail-Adresse ändert sich, sobald Sie darauf klicken (innerhalb einer Stunde).',
	'An invoice exists for this order; invoices must not change afterwards. Cancel it and take a new order instead.' => 'Zu dieser Bestellung gibt es bereits eine Rechnung, und Rechnungen dürfen sich nachträglich nicht ändern. Stornieren Sie sie und legen Sie eine neue Bestellung an.',
	'An order needs at least one item. Cancel it instead.' => 'Eine Bestellung braucht mindestens einen Artikel. Stornieren Sie sie stattdessen.',
	'Arrives' => 'Kommt an',
	'At PayPal' => 'Bei PayPal',
	'At Stripe' => 'Bei Stripe',
	'Automatically, every %s' => 'Automatisch, jeden %s',
	'Automatically, every working day' => 'Automatisch, an jedem Werktag',
	'Automatically, on day %d of each month' => 'Automatisch, am %d. jedes Monats',
	'Bank account & schedule in Stripe' => 'Bankkonto & Rhythmus bei Stripe',
	'Cancel the change' => 'Änderung abbrechen',
	'Card, Apple Pay, Google Pay, SEPA and Klarna payments are collected by Stripe. Stripe keeps its fee and pays the rest out to your bank account — automatically, on a schedule you choose.' => 'Zahlungen per Karte, Apple Pay, Google Pay, SEPA und Klarna sammelt Stripe ein. Stripe behält seine Gebühr und zahlt den Rest auf Ihr Bankkonto aus – automatisch, in einem Rhythmus, den Sie wählen.',
	'Cards (with Apple Pay and Google Pay)' => 'Karten (mit Apple Pay und Google Pay)',
	'Change quantities or prices, remove or add products. Stock, VAT and the total are worked out again; the customer can get the updated order by email.' => 'Mengen oder Preise ändern, Produkte entfernen oder hinzufügen. Bestand, MwSt. und Summe werden neu berechnet; die Kundin oder der Kunde kann die geänderte Bestellung per E-Mail bekommen.',
	'Change your password' => 'Passwort ändern',
	'Check it and save — then it is filled in at every checkout.' => 'Prüfen und speichern – dann ist sie an jeder Kasse ausgefüllt.',
	'Choose payment methods' => 'Zahlungsarten wählen',
	'Code from your authenticator app' => 'Code aus Ihrer Authenticator-App',
	'Confirm my new address' => 'Neue Adresse bestätigen',
	'Confirm your new email address' => 'Bestätigen Sie Ihre neue E-Mail-Adresse',
	'Customers pay to your account after the goods arrive.' => 'Kunden zahlen nach Erhalt der Ware auf Ihr Konto.',
	'Customers transfer the money straight to your account.' => 'Kunden überweisen das Geld direkt auf Ihr Konto.',
	'Edit order' => 'Bestellung bearbeiten',
	'Email me a link to change it' => 'Link zum Ändern per E-Mail senden',
	'Email the customer the updated order' => 'Die geänderte Bestellung per E-Mail an den Kunden senden',
	'Every device is signed out; you sign in again with the new password.' => 'Alle Geräte werden abgemeldet; Sie melden sich mit dem neuen Passwort wieder an.',
	'For your safety the password is changed through your inbox: only someone who can read your email can set a new one.' => 'Zu Ihrer Sicherheit wird das Passwort über Ihr Postfach geändert: Nur wer Ihre E-Mails lesen kann, kann ein neues festlegen.',
	'For your tax office: the invoices are in each order, and Revenue exports a CSV for your accountant.' => 'Fürs Finanzamt: Die Rechnungen liegen in jeder Bestellung, und unter Umsatz gibt es einen CSV-Export für Ihre Steuerberatung.',
	'Friday' => 'Freitag',
	'From your latest order' => 'Aus Ihrer letzten Bestellung',
	'If this was not you, reply to this email right away so we can lock the account.' => 'Waren Sie das nicht? Antworten Sie sofort auf diese E-Mail, damit wir das Konto sperren können.',
	'If you did not ask for this, ignore this email — your account stays as it is.' => 'Wenn Sie das nicht angefordert haben, ignorieren Sie diese E-Mail – Ihr Konto bleibt, wie es ist.',
	'Larger orders do not see this method.' => 'Bei größeren Bestellungen wird diese Zahlungsart nicht angeboten.',
	'Last changed on %s' => 'Zuletzt geändert am %s',
	'Monday' => 'Montag',
	'New total' => 'Neue Summe',
	'No items — add one below.' => 'Keine Artikel – fügen Sie unten einen hinzu.',
	'No one in between: mark these orders as paid when the money is there.' => 'Niemand dazwischen: Markieren Sie diese Bestellungen als bezahlt, sobald das Geld da ist.',
	'No payouts yet. The first one usually comes 7 days after the first payment.' => 'Noch keine Auszahlungen. Die erste kommt meist 7 Tage nach der ersten Zahlung.',
	'Nothing ticked = whatever is switched on in your Stripe dashboard. A method Stripe cannot offer for an order (not active, other currency) is left out automatically — the checkout always works.' => 'Nichts angehakt = alles, was in Ihrem Stripe-Dashboard eingeschaltet ist. Eine Zahlungsart, die Stripe für eine Bestellung nicht anbieten kann (nicht aktiv, andere Währung), fällt automatisch weg – die Kasse funktioniert immer.',
	'On its way' => 'Unterwegs',
	'On the way' => 'Unterwegs',
	'On your bank' => 'Auf Ihrem Konto',
	'Only up to an order value of' => 'Nur bis zu einem Bestellwert von',
	'Only when you start a payout' => 'Nur wenn Sie eine Auszahlung starten',
	'Open my PayPal money' => 'Mein PayPal-Guthaben öffnen',
	'Open the email we sent there and click the link. It works for one hour.' => 'Öffnen Sie die E-Mail, die wir dorthin geschickt haben, und klicken Sie auf den Link. Er gilt eine Stunde.',
	'Open the order' => 'Bestellung öffnen',
	'Order changed: %1$s → %2$s.' => 'Bestellung geändert: %1$s → %2$s.',
	'Pay out' => 'Auszahlen',
	'Pay out %s now' => '%s jetzt auszahlen',
	'Pay out to your bank now?' => 'Jetzt auf Ihr Konto auszahlen?',
	'PayPal balance' => 'PayPal-Guthaben',
	'PayPal keeps its fee per payment. To get the money to your bank, transfer it in PayPal — usually free and there in 1–2 working days.' => 'PayPal behält pro Zahlung seine Gebühr. Damit das Geld auf Ihr Konto kommt, überweisen Sie es in PayPal – meist kostenlos und in 1–2 Werktagen da.',
	'PayPal payments land in your PayPal account. From there you transfer them to your bank in PayPal (usually free, 1–2 working days).' => 'PayPal-Zahlungen landen in Ihrem PayPal-Konto. Von dort überweisen Sie sie in PayPal auf Ihr Bankkonto (meist kostenlos, 1–2 Werktage).',
	'PayPal through Stripe' => 'PayPal über Stripe',
	'Payments land in your PayPal account. Velox cannot read the balance yet: in the PayPal developer dashboard, open your app and switch on “Balances” (or “Transaction search”) under features.' => 'Zahlungen landen in Ihrem PayPal-Konto. Velox kann das Guthaben noch nicht lesen: Öffnen Sie im PayPal-Developer-Dashboard Ihre App und schalten Sie unter „Features“ „Balances“ (oder „Transaction search“) ein.',
	'Payout' => 'Auszahlung',
	'Payout started: %s. It usually reaches your bank in 1–3 working days.' => 'Auszahlung gestartet: %s. Sie ist meist in 1–3 Werktagen auf Ihrem Konto.',
	'Payouts' => 'Auszahlungen',
	'Please confirm that this is the new email address for your customer account at %s. Until you do, nothing changes. The link works for one hour.' => 'Bitte bestätigen Sie, dass dies die neue E-Mail-Adresse für Ihr Kundenkonto bei %s ist. Bis dahin ändert sich nichts. Der Link gilt eine Stunde.',
	'Please wait a little before asking for another email.' => 'Bitte warten Sie etwas, bevor Sie eine weitere E-Mail anfordern.',
	'Prepared' => 'Vorbereitet',
	'Price each' => 'Preis pro Stück',
	'Received' => 'Eingenommen',
	'Refresh' => 'Aktualisieren',
	'Reopen the order first, then change it.' => 'Öffnen Sie die Bestellung zuerst wieder, dann können Sie sie ändern.',
	'SEPA Direct Debit' => 'SEPA-Lastschrift',
	'Saturday' => 'Samstag',
	'Saved. The customer has the updated order.' => 'Gespeichert. Der Kunde hat die geänderte Bestellung bekommen.',
	'Send confirmation link' => 'Bestätigungslink senden',
	'Send the link again' => 'Link erneut senden',
	'Set in your Stripe account' => 'In Ihrem Stripe-Konto festgelegt',
	'Set up PayPal' => 'PayPal einrichten',
	'Set up Stripe' => 'Stripe einrichten',
	'Set when the account was created' => 'Beim Anlegen des Kontos festgelegt',
	'Someone signed in to your customer account asked to change its email address to %s. The change happens only once it is confirmed from that inbox.' => 'Jemand, der in Ihrem Kundenkonto angemeldet ist, möchte die E-Mail-Adresse auf %s ändern. Die Änderung passiert erst, wenn sie aus diesem Postfach bestätigt wird.',
	'Still to come in' => 'Steht noch aus',
	'Stop the change' => 'Änderung stoppen',
	'Straight to your account' => 'Direkt auf Ihr Konto',
	'Stripe and PayPal keep their fee before paying out; the amounts here are what is left for you.' => 'Stripe und PayPal behalten ihre Gebühr vor der Auszahlung; die Beträge hier sind das, was für Sie bleibt.',
	'Stripe did not answer:' => 'Stripe hat nicht geantwortet:',
	'Stripe is not set up.' => 'Stripe ist nicht eingerichtet.',
	'Stripe pays out automatically on your schedule — there is nothing to start by hand.' => 'Stripe zahlt automatisch in Ihrem Rhythmus aus – von Hand ist nichts zu starten.',
	'Stripe sends the whole available balance to the bank account set in Stripe. It usually arrives in 1–3 working days.' => 'Stripe überweist das gesamte verfügbare Guthaben auf das bei Stripe hinterlegte Bankkonto. Es kommt meist in 1–3 Werktagen an.',
	'Sunday' => 'Sonntag',
	'Test mode: these are test amounts, no real money moves.' => 'Testmodus: Das sind Testbeträge, es fließt kein echtes Geld.',
	'That is already your email address.' => 'Das ist bereits Ihre E-Mail-Adresse.',
	'The change of email address was cancelled. Nothing has changed.' => 'Die Änderung der E-Mail-Adresse wurde abgebrochen. Es hat sich nichts geändert.',
	'The customer was sent to pay online with the old total. Switch the payment method to bank transfer or invoice in a new order, or wait until it is paid or cancelled.' => 'Der Kunde wurde zur Online-Zahlung mit der alten Summe geschickt. Legen Sie eine neue Bestellung mit Überweisung oder Rechnung an, oder warten Sie, bis sie bezahlt oder storniert ist.',
	'The parcel service collects the money at the door and pays it out to you.' => 'Der Paketdienst kassiert an der Tür und zahlt das Geld an Sie aus.',
	'The password of your customer account has just been changed, and every device was signed out.' => 'Das Passwort Ihres Kundenkontos wurde gerade geändert, und alle Geräte wurden abgemeldet.',
	'There is no available balance to pay out yet.' => 'Es gibt noch kein verfügbares Guthaben zum Auszahlen.',
	'This confirmation link is no longer valid. Please start the change again.' => 'Dieser Bestätigungslink ist nicht mehr gültig. Bitte starten Sie die Änderung neu.',
	'This order can no longer be changed.' => 'Diese Bestellung kann nicht mehr geändert werden.',
	'This order has already been shipped.' => 'Diese Bestellung wurde bereits versendet.',
	'This order is paid, so its items can no longer change. Refund the difference, or cancel it and take a new order.' => 'Diese Bestellung ist bezahlt, ihre Artikel können sich nicht mehr ändern. Erstatten Sie die Differenz, oder stornieren Sie sie und legen Sie eine neue an.',
	'Thursday' => 'Donnerstag',
	'Tuesday' => 'Dienstag',
	'Two-factor sign-in is on for this account, so the code is needed too. A recovery code works as well.' => 'Für dieses Konto ist die Zwei-Faktor-Anmeldung an, deshalb braucht es auch den Code. Ein Wiederherstellungscode funktioniert ebenfalls.',
	'Waiting for confirmation: %s' => 'Wartet auf Bestätigung: %s',
	'Was this not you? Stop it with the button below — then change your password.' => 'Waren Sie das nicht? Stoppen Sie es mit dem Button unten – und ändern Sie danach Ihr Passwort.',
	'We email a link to %s.' => 'Wir schicken einen Link an %s.',
	'We have sent you an email with a link to change your password. It works for 24 hours.' => 'Wir haben Ihnen eine E-Mail mit einem Link zum Ändern des Passworts geschickt. Er gilt 24 Stunden.',
	'We have updated your order as agreed. Here is how it looks now:' => 'Wir haben Ihre Bestellung wie besprochen angepasst. So sieht sie jetzt aus:',
	'Wednesday' => 'Mittwoch',
	'What customers can choose' => 'Was Kunden wählen können',
	'What customers see at Stripe' => 'Was Kunden bei Stripe sehen',
	'When: %s' => 'Wann: %s',
	'Where your money is, and how it reaches your bank' => 'Wo Ihr Geld ist und wie es auf Ihr Konto kommt',
	'You asked to change the password of your customer account. Choose the new one with the button below. The link works for 24 hours; afterwards every device is signed out.' => 'Sie möchten das Passwort Ihres Kundenkontos ändern. Wählen Sie das neue mit dem Button unten. Der Link gilt 24 Stunden; danach werden alle Geräte abgemeldet.',
	'You choose the new password there and enter the code from your app.' => 'Dort wählen Sie das neue Passwort und geben den Code aus Ihrer App ein.',
	'You choose the new password there.' => 'Dort wählen Sie das neue Passwort.',
	'You sign in with it and get order emails there. A new address only counts once you confirm it from that inbox; your current address gets a note with a link to stop the change.' => 'Damit melden Sie sich an und bekommen dorthin Bestell-E-Mails. Eine neue Adresse gilt erst, wenn Sie sie aus diesem Postfach bestätigen; Ihre bisherige Adresse bekommt einen Hinweis mit einem Link, um die Änderung zu stoppen.',
	'Your bank' => 'Ihre Bank',
	'Your customer account now uses %s. Order emails go there from now on.' => 'Ihr Kundenkonto nutzt jetzt %s. Bestell-E-Mails gehen ab sofort dorthin.',
	'Your email address is about to change' => 'Ihre E-Mail-Adresse soll geändert werden',
	'Your email address was changed' => 'Ihre E-Mail-Adresse wurde geändert',
	'Your new password is set. For your safety you were signed out on every device — sign in with the new password.' => 'Ihr neues Passwort ist gesetzt. Zu Ihrer Sicherheit wurden Sie auf allen Geräten abgemeldet – melden Sie sich mit dem neuen Passwort an.',
	'Your order %s was updated' => 'Ihre Bestellung %s wurde geändert',
	'Your password was changed' => 'Ihr Passwort wurde geändert',
	'as set in Stripe' => 'wie bei Stripe hinterlegt',
	'available to transfer' => 'verfügbar zum Überweisen',
