	'recent payments, still held by Stripe' => 'neue Zahlungen, noch bei Stripe',
	'when you transfer it' => 'wenn Sie es überweisen',
	// 4.63 — filters, swatches, wishlist, back in stock, reviews, cart reminders
	'%d customers are waiting for this to be back.' => '%d Kunden warten darauf, dass es wieder da ist.',
	'1 customer is waiting for this to be back.' => '1 Kunde wartet darauf, dass es wieder da ist.',
	'%s is available again' => '%s ist wieder verfügbar',
	'%s out of 5 stars' => '%s von 5 Sternen',
	'%d review' => '%d Bewertung',
	'%d reviews' => '%d Bewertungen',
	'%d star' => '%d Stern',
	'%d stars' => '%d Sterne',
	'2 days' => '2 Tage',
	'3 hours' => '3 Stunden',
	'A heart on every product. Guests keep the list in their browser; with an account it is saved there, on all devices.' => 'Ein Herz an jedem Produkt. Gäste behalten die Liste in ihrem Browser; mit Kundenkonto wird sie dort gespeichert – auf allen Geräten.',
	'Almost done: please confirm the link we just emailed you.' => 'Fast geschafft: Bitte bestätigen Sie den Link, den wir Ihnen gerade gemailt haben.',
	'Available now' => 'Sofort verfügbar',
	'Be the first to review' => 'Als Erste:r bewerten',
	'Cart reminders' => 'Warenkorb-Erinnerung',
	'Check reviews before they appear' => 'Bewertungen vor dem Erscheinen prüfen',
	'Clear all filters' => 'Alle Filter zurücksetzen',
	'Reset filters' => 'Filter zurücksetzen',
	'Reduced price' => 'Reduziert',
	'Colour dots on product cards' => 'Farbpunkte auf Produktkarten',
	'Colour for' => 'Farbe für',
	'Complete my order' => 'Bestellung abschließen',
	'Confirmed — we email you once as soon as it is available again.' => 'Bestätigt – wir mailen Ihnen einmal, sobald es wieder verfügbar ist.',
	'Coupon in the email' => 'Gutschein in der E-Mail',
	'Customers write them on the product page. Ask happy customers for one — it helps the next buyer most.' => 'Kunden schreiben sie auf der Produktseite. Bitten Sie zufriedene Kunden darum – das hilft den nächsten Käufern am meisten.',
	'Done — we email you as soon as it is back.' => 'Erledigt – wir mailen Ihnen, sobald es wieder da ist.',
	'Done — you will not get a notification.' => 'Erledigt – Sie bekommen keine Benachrichtigung.',
	'Edit reply' => 'Antwort bearbeiten',
	'Email (not shown)' => 'E-Mail (wird nicht angezeigt)',
	'Email me once when it is available again. My address is used for nothing else and deleted afterwards (%s).' => 'Mailen Sie mir einmal, wenn es wieder verfügbar ist. Meine Adresse wird für nichts anderes genutzt und danach gelöscht (%s).',
	'Email me once when it is available again. My address is used for nothing else and deleted afterwards.' => 'Mailen Sie mir einmal, wenn es wieder verfügbar ist. Meine Adresse wird für nichts anderes genutzt und danach gelöscht.',
	'Filters with counts' => 'Filter mit Anzahl',
	'For products with a colour option. Pointing at a dot shows that colour’s photo.' => 'Für Produkte mit einer Farb-Option. Beim Zeigen auf einen Punkt erscheint das Foto dieser Farbe.',
	'Forget my cart' => 'Meinen Warenkorb vergessen',
	'Good news — it is available right now.' => 'Gute Nachricht – es ist gerade verfügbar.',
	'Hidden again.' => 'Wieder ausgeblendet.',
	'How we check reviews: anyone can write one. Reviews marked “Verified purchase” come from an email address we found in a paid order for this product.' => 'So prüfen wir Bewertungen: Jede:r kann eine schreiben. Bewertungen mit „Verifizierter Kauf“ stammen von einer E-Mail-Adresse, die wir in einer bezahlten Bestellung dieses Produkts gefunden haben.',
	'How we check reviews: only customers who bought this product with us can write one; we match the email address against our orders.' => 'So prüfen wir Bewertungen: Nur Kunden, die dieses Produkt bei uns gekauft haben, können eine schreiben; wir gleichen die E-Mail-Adresse mit unseren Bestellungen ab.',
	'If you did not ask for this, ignore this email — you will not hear from us.' => 'Wenn Sie das nicht angefordert haben, ignorieren Sie diese E-Mail – Sie hören nichts mehr von uns.',
	'It disappears from the product page. You can restore it under Comments → Trash in WordPress.' => 'Sie verschwindet von der Produktseite. Wiederherstellen können Sie sie in WordPress unter Kommentare → Papierkorb.',
	'Move this review to the trash?' => 'Diese Bewertung in den Papierkorb verschieben?',
	'Moved to the trash. It can be restored under Comments → Trash.' => 'In den Papierkorb verschoben. Wiederherstellen unter Kommentare → Papierkorb.',
	'My review and the name above may be published. The email is only used to check it (%s).' => 'Meine Bewertung und der Name oben dürfen veröffentlicht werden. Die E-Mail dient nur zur Prüfung (%s).',
	'My review and the name above may be published. The email is only used to check it.' => 'Meine Bewertung und der Name oben dürfen veröffentlicht werden. Die E-Mail dient nur zur Prüfung.',
	'Name (shown)' => 'Name (wird angezeigt)',
	'New reviews show up here first, when “Check reviews before they appear” is on.' => 'Neue Bewertungen erscheinen zuerst hier, wenn „Bewertungen vor dem Erscheinen prüfen“ an ist.',
	'New reviews wait under Reviews until you publish them.' => 'Neue Bewertungen warten unter „Bewertungen“, bis Sie sie veröffentlichen.',
	'No products match these filters.' => 'Keine Produkte passen zu diesen Filtern.',
	'No reviews yet' => 'Noch keine Bewertungen',
	'No reviews yet. Tell others what you think of it.' => 'Noch keine Bewertungen. Erzählen Sie anderen, was Sie davon halten.',
	'Nothing saved yet' => 'Noch nichts gemerkt',
	'Nothing waiting' => 'Nichts wartet',
	'Notify me' => 'Benachrichtigen',
	'On your wishlist' => 'Auf Ihrer Merkliste',
	'One email, only to customers who tick “Remind me” at checkout — an advertising email needs consent in Germany. The button in it restores the cart.' => 'Eine E-Mail, nur an Kunden, die an der Kasse „Erinnern“ ankreuzen – Werbe-E-Mails brauchen in Deutschland eine Einwilligung. Der Button darin stellt den Warenkorb wieder her.',
	'Only buyers may review' => 'Nur Käufer dürfen bewerten',
	'Only customers who bought this product can review it. Use the email address from your order.' => 'Nur Kunden, die dieses Produkt gekauft haben, können es bewerten. Nutzen Sie die E-Mail-Adresse aus Ihrer Bestellung.',
	'Open Reviews' => 'Bewertungen öffnen',
	'Optional. Create codes under Coupons.' => 'Optional. Codes legen Sie unter Gutscheine an.',
	'Please choose 1 to 5 stars.' => 'Bitte wählen Sie 1 bis 5 Sterne.',
	'Please confirm that your review may be published.' => 'Bitte bestätigen Sie, dass Ihre Bewertung veröffentlicht werden darf.',
	'Please confirm your notification' => 'Bitte bestätigen Sie Ihre Benachrichtigung',
	'Please enter your name and a valid email address.' => 'Bitte geben Sie Ihren Namen und eine gültige E-Mail-Adresse ein.',
	'Please tick the box so we may email you.' => 'Bitte setzen Sie das Häkchen, damit wir Ihnen mailen dürfen.',
	'Please try again later.' => 'Bitte versuchen Sie es später noch einmal.',
	'Please write a few words (at least 10 characters).' => 'Bitte schreiben Sie ein paar Worte (mindestens 10 Zeichen).',
	'Previous' => 'Zurück',
	'Price, your product options (colour, size …), available now and on sale — each shows how many products it leaves.' => 'Preis, Ihre Produktoptionen (Farbe, Größe …), sofort verfügbar und reduziert – jeder Filter zeigt, wie viele Produkte übrig bleiben.',
	'Remind customers of a cart they left' => 'Kunden an einen verlassenen Warenkorb erinnern',
	'Remind me by email once if I do not finish my order. I can say no to it in that email.' => 'Erinnern Sie mich einmal per E-Mail, falls ich meine Bestellung nicht abschließe. In dieser E-Mail kann ich widersprechen.',
	'Remove filter: %s' => 'Filter entfernen: %s',
	'Removed from your wishlist' => 'Von Ihrer Merkliste entfernt',
	'Reply from %s' => 'Antwort von %s',
	'Reply removed.' => 'Antwort entfernt.',
	'Reply saved — it shows under the review.' => 'Antwort gespeichert – sie erscheint unter der Bewertung.',
	'Reply to the review' => 'Auf die Bewertung antworten',
	'Reviews are switched off.' => 'Bewertungen sind ausgeschaltet.',
	'Save %s to your wishlist' => '%s auf die Merkliste setzen',
	'Save reply' => 'Antwort speichern',
	'Save to your wishlist' => 'Auf die Merkliste',
	'Saved in this browser.' => 'In diesem Browser gespeichert.',
	'Saved to your wishlist' => 'Auf Ihrer Merkliste gespeichert',
	'Send after' => 'Senden nach',
	'Send review' => 'Bewertung senden',
	'Sent: %1$d · Orders afterwards: %2$d (%3$s) · Waiting: %4$d' => 'Gesendet: %1$d · Bestellungen danach: %2$d (%3$s) · Wartend: %4$d',
	'Sign in to keep it on all your devices' => 'Anmelden, um sie auf allen Geräten zu behalten',
	'Sold-out products (and sold-out variants) offer an email field. After a confirmation click, the customer gets exactly one email when it can be bought again; the address is then deleted.' => 'Ausverkaufte Produkte (und ausverkaufte Varianten) bieten ein E-Mail-Feld an. Nach einem Bestätigungsklick bekommt der Kunde genau eine E-Mail, sobald es wieder kaufbar ist; danach wird die Adresse gelöscht.',
	'Star reviews on product pages' => 'Sterne-Bewertungen auf Produktseiten',
	'Stars on product cards' => 'Sterne auf Produktkarten',
	'Tap the heart on a product to keep it here for later.' => 'Tippen Sie auf das Herz an einem Produkt, um es hier für später zu behalten.',
	'Tell me when it is back' => 'Benachrichtigen, wenn wieder da',
	'“Tell me when it is back”' => '„Benachrichtigen, wenn wieder da“',
	'Thank you for your review!' => 'Danke für Ihre Bewertung!',
	'Thank you! Your review appears as soon as we have checked it.' => 'Danke! Ihre Bewertung erscheint, sobald wir sie geprüft haben.',
	'Thank you! Your review is online.' => 'Danke! Ihre Bewertung ist online.',
	'That did not work. Please try again.' => 'Das hat nicht geklappt. Bitte versuchen Sie es noch einmal.',
	'The email address must belong to a paid order with this product. Without it, those reviews are marked “Verified purchase”.' => 'Die E-Mail-Adresse muss zu einer bezahlten Bestellung mit diesem Produkt gehören. Ist das aus, werden solche Bewertungen als „Verifizierter Kauf“ markiert.',
	'The product page says how reviews are checked, as German law (§ 5b UWG) requires. Manage them under Reviews.' => 'Die Produktseite sagt, wie Bewertungen geprüft werden – wie es § 5b UWG verlangt. Verwalten Sie sie unter „Bewertungen“.',
	'The review could not be saved. Please try again.' => 'Die Bewertung konnte nicht gespeichert werden. Bitte versuchen Sie es noch einmal.',
	'The review could not be sent. Please check the form and try again.' => 'Die Bewertung konnte nicht gesendet werden. Bitte prüfen Sie das Formular und versuchen Sie es erneut.',
	'They get one email as soon as it can be bought again.' => 'Sie bekommen eine E-Mail, sobald es wieder kaufbar ist.',
	'This link is no longer valid.' => 'Dieser Link ist nicht mehr gültig.',
	'This review does not exist.' => 'Diese Bewertung gibt es nicht.',
	'This was the one email you asked for; your address has been deleted.' => 'Das war die eine E-Mail, um die Sie gebeten haben; Ihre Adresse wurde gelöscht.',
	'Title (optional)' => 'Titel (optional)',
	'Verified purchase' => 'Verifizierter Kauf',
	'View it now' => 'Jetzt ansehen',
	'View wishlist' => 'Merkliste ansehen',
	'What customers say about your products' => 'Was Kunden über Ihre Produkte sagen',
	'Wishlist' => 'Merkliste',
	'Wishlist & back in stock' => 'Merkliste & wieder verfügbar',
	'With the average under the product name and in Google’s search results.' => 'Mit dem Durchschnitt unter dem Produktnamen und in den Google-Suchergebnissen.',
	'With the code %s you get a little thank-you at checkout.' => 'Mit dem Code %s gibt es an der Kasse ein kleines Dankeschön.',
	'Write a review' => 'Bewertung schreiben',
	'Yes, notify me' => 'Ja, benachrichtigen',
	'You asked us to tell you when “%s” is available again. Please confirm with the button — then we send you exactly one email when it is back.' => 'Sie möchten erfahren, wann „%s“ wieder verfügbar ist. Bitte bestätigen Sie mit dem Button – dann schicken wir Ihnen genau eine E-Mail, sobald es wieder da ist.',
	'You asked us to tell you: it is back in the shop. Stock is limited, so do not wait too long.' => 'Sie wollten es wissen: Es ist wieder im Shop. Der Bestand ist begrenzt – warten Sie nicht zu lange.',
	'You get this one reminder because you ticked the box at checkout. We will not send another.' => 'Sie bekommen diese eine Erinnerung, weil Sie an der Kasse das Häkchen gesetzt haben. Wir schicken keine weitere.',
	'You have already reviewed this product. Thank you!' => 'Sie haben dieses Produkt bereits bewertet. Danke!',
	'You left a few things in your cart. We kept them for you — continue right where you stopped:' => 'In Ihrem Warenkorb liegen noch ein paar Dinge. Wir haben sie für Sie aufbewahrt – machen Sie genau dort weiter, wo Sie aufgehört haben:',
	'Your cart is waiting for you' => 'Ihr Warenkorb wartet auf Sie',
	'Your email' => 'Ihre E-Mail',
	'Your reply' => 'Ihre Antwort',
	'Your reply shows under the review on the product page, with your shop’s name. Leave it empty to remove it.' => 'Ihre Antwort erscheint unter der Bewertung auf der Produktseite, mit dem Namen Ihres Shops. Leer lassen, um sie zu entfernen.',
	'Your review' => 'Ihre Bewertung',
	'Your saved cart has been deleted. You will not hear from us about it.' => 'Ihr gespeicherter Warenkorb wurde gelöscht. Sie hören dazu nichts mehr von uns.',
	'Your wishlist' => 'Ihre Merkliste',
	'to' => 'bis',
	// 4.64 — Claude in the editor
	'Build and change pages by chatting with Claude right in the editor. Everything it does is a draft you check and publish.' => 'Seiten bauen und ändern, indem Sie direkt im Editor mit Claude schreiben. Alles, was Claude macht, ist ein Entwurf, den Sie prüfen und veröffentlichen.',
	'Claude in the editor' => 'Claude im Editor',
	'Your site talks to Claude with your own Anthropic account. You pay Anthropic directly for what you use.' => 'Ihre Website spricht mit Claude über Ihr eigenes Anthropic-Konto. Was Sie nutzen, bezahlen Sie direkt bei Anthropic.',
	'Connected' => 'Verbunden',
	'Not connected' => 'Nicht verbunden',
	'The saved key can no longer be read, because the site\'s secret keys (in wp-config.php) changed. Enter the key again.' => 'Der gespeicherte Schlüssel kann nicht mehr gelesen werden, weil sich die geheimen Schlüssel der Website (in der wp-config.php) geändert haben. Geben Sie den Schlüssel erneut ein.',
	'Create an API key' => 'API-Schlüssel erstellen',
	'Sign in to the Claude Console (or create an account), add a little credit under Billing, then create a key named after this site.' => 'Melden Sie sich in der Claude Console an (oder legen Sie ein Konto an), laden Sie unter „Billing“ etwas Guthaben auf und erstellen Sie dann einen Schlüssel mit dem Namen dieser Website.',
	'Open the Claude Console' => 'Claude Console öffnen',
	'Paste it here' => 'Hier einfügen',
	'Velox checks the key, then stores it encrypted. It is never shown again or sent to the browser.' => 'Velox prüft den Schlüssel und speichert ihn dann verschlüsselt. Er wird nie wieder angezeigt und nie an den Browser geschickt.',
	'Anthropic API key' => 'Anthropic-API-Schlüssel',
	'Connect' => 'Verbinden',
	'Ending in …%s, stored encrypted.' => 'Endet auf …%s, verschlüsselt gespeichert.',
	'Remove key' => 'Schlüssel entfernen',
	'Model' => 'Modell',
	'Monthly limit' => 'Monatslimit',
	'The assistant stops for the rest of the month when Velox counts this much. 0 means no limit. Your Anthropic account can have its own limit too.' => 'Der Assistent pausiert für den Rest des Monats, sobald Velox so viel gezählt hat. 0 heißt kein Limit. Auch Ihr Anthropic-Konto kann ein eigenes Limit haben.',
	'Monthly limit in US dollars' => 'Monatslimit in US-Dollar',
	'About %1$s in %2$s requests (counted by Velox from Anthropic\'s prices).' => 'Etwa %1$s für %2$s Anfragen (von Velox anhand der Preise von Anthropic gezählt).',
	'Open any page in the editor and click Claude in the top bar. Designers and administrators can use it; it can only do what their role allows.' => 'Öffnen Sie eine beliebige Seite im Editor und klicken Sie oben auf „Claude“. Designer und Administratoren können es nutzen; es kann nur, was ihre Rolle erlaubt.',
	'Your own AI tools (advanced)' => 'Eigene KI-Werkzeuge (für Fortgeschrittene)',
	'Let tools such as Claude Desktop, ChatGPT or Cursor work on this site from your computer, over MCP.' => 'Lassen Sie Werkzeuge wie Claude Desktop, ChatGPT oder Cursor von Ihrem Computer aus über MCP an dieser Website arbeiten.',
	'What an agent can do. It works only in drafts: nothing changes for visitors until a person publishes. Every change is kept under History → Saved versions, marked “By AI”.' => 'Was ein Agent kann. Er arbeitet nur in Entwürfen: Für Besucher ändert sich nichts, bis ein Mensch veröffentlicht. Jede Änderung wird unter Verlauf → Gespeicherte Versionen aufbewahrt, markiert mit „Von KI“.',
	'Checking the key…' => 'Schlüssel wird geprüft …',
	'Paste your API key first.' => 'Fügen Sie zuerst Ihren API-Schlüssel ein.',
	'Remove the API key? The assistant stops working until a key is added again.' => 'API-Schlüssel entfernen? Der Assistent funktioniert erst wieder, wenn ein Schlüssel hinterlegt ist.',
	'No answer from the server. Check your connection and try again.' => 'Keine Antwort vom Server. Prüfen Sie Ihre Verbindung und versuchen Sie es erneut.',
	'Best results. Recommended.' => 'Beste Ergebnisse. Empfohlen.',
	'Faster and about half the price.' => 'Schneller und etwa zum halben Preis.',
	'Your server could not reach Claude. Your host may block outgoing connections.' => 'Ihr Server konnte Claude nicht erreichen. Möglicherweise blockiert Ihr Hoster ausgehende Verbindungen.',
	'No answer from Claude in time. Please try again.' => 'Claude hat nicht rechtzeitig geantwortet. Bitte versuchen Sie es erneut.',
	'Claude sent an answer Velox could not read. Please try again.' => 'Claude hat eine Antwort geschickt, die Velox nicht lesen konnte. Bitte versuchen Sie es erneut.',
	'The API key was not accepted. Check it, or create a new one.' => 'Der API-Schlüssel wurde nicht akzeptiert. Prüfen Sie ihn oder erstellen Sie einen neuen.',
	'This API key may not use Claude. Check its permissions in the Claude Console.' => 'Dieser API-Schlüssel darf Claude nicht nutzen. Prüfen Sie seine Berechtigungen in der Claude Console.',
	'This model is not available for your account.' => 'Dieses Modell ist für Ihr Konto nicht verfügbar.',
	'The conversation is too long. Start a new chat.' => 'Die Unterhaltung ist zu lang. Starten Sie einen neuen Chat.',
	'Too many requests for your Anthropic account right now. Wait a minute and try again.' => 'Gerade zu viele Anfragen für Ihr Anthropic-Konto. Warten Sie eine Minute und versuchen Sie es erneut.',
	'Claude is busy right now. Try again in a moment.' => 'Claude ist gerade ausgelastet. Versuchen Sie es gleich noch einmal.',
	'Claude could not handle this request.' => 'Claude konnte diese Anfrage nicht bearbeiten.',
	'Your Anthropic account has no credit left. Add credit in the Claude Console.' => 'Ihr Anthropic-Konto hat kein Guthaben mehr. Laden Sie in der Claude Console Guthaben auf.',
	'Find images in the media library' => 'Bilder in der Mediathek finden',
	'You may not do that with your role, or on this document.' => 'Das dürfen Sie mit Ihrer Rolle oder in diesem Dokument nicht.',
	'Save the page first.' => 'Speichern Sie die Seite zuerst.',
	'You may not edit this document.' => 'Sie dürfen dieses Dokument nicht bearbeiten.',
	'Claude is not connected yet. An administrator can connect it under Velox Builder → AI agents.' => 'Claude ist noch nicht verbunden. Ein Administrator kann es unter Velox Builder → KI-Agenten verbinden.',
	'Your role may not use the AI assistant.' => 'Ihre Rolle darf den KI-Assistenten nicht nutzen.',
	'Write what Claude should do.' => 'Schreiben Sie, was Claude tun soll.',
	'Claude is still working on your last message.' => 'Claude arbeitet noch an Ihrer letzten Nachricht.',
	'This chat has become too long. Start a new chat.' => 'Dieser Chat ist zu lang geworden. Starten Sie einen neuen Chat.',
	'The last step did not finish (the server may have stopped it). Send your message again, or say “continue”.' => 'Der letzte Schritt wurde nicht fertig (der Server hat ihn womöglich abgebrochen). Schicken Sie Ihre Nachricht noch einmal oder schreiben Sie „weiter“.',
	'Stopped. What Claude did so far stays; Undo takes it back.' => 'Gestoppt. Was Claude bisher gemacht hat, bleibt; Rückgängig nimmt es zurück.',
	'Claude is still working. Stop it first.' => 'Claude arbeitet noch. Stoppen Sie es zuerst.',
	'This server cannot store the key safely (the PHP OpenSSL extension is missing). Ask your host to enable it.' => 'Dieser Server kann den Schlüssel nicht sicher speichern (die PHP-Erweiterung OpenSSL fehlt). Bitten Sie Ihren Hoster, sie zu aktivieren.',
	'No key saved, or the site\'s secret keys changed since. Enter the key again.' => 'Kein Schlüssel gespeichert, oder die geheimen Schlüssel der Website haben sich seitdem geändert. Geben Sie den Schlüssel erneut ein.',
	'Connected. Claude is ready in the editor.' => 'Verbunden. Claude ist im Editor bereit.',
	'The monthly limit of $%s for the AI assistant is reached. An administrator can raise it under Velox Builder → AI agents.' => 'Das Monatslimit von %s $ für den KI-Assistenten ist erreicht. Ein Administrator kann es unter Velox Builder → KI-Agenten erhöhen.',
	'Claude paused after many steps. Say “continue” to let it go on.' => 'Claude hat nach vielen Schritten pausiert. Schreiben Sie „weiter“, damit es fortfährt.',
	'Claude declined this request. Try putting it differently.' => 'Claude hat diese Anfrage abgelehnt. Versuchen Sie es anders zu formulieren.',
	'The answer was cut off. Say “continue” to let Claude finish.' => 'Die Antwort wurde abgeschnitten. Schreiben Sie „weiter“, damit Claude sie beendet.',
	'Read the design system' => 'Designsystem gelesen',
