	'Used a tool' => 'Ein Werkzeug benutzt',
	'Claude: build and change with words' => 'Claude: mit Worten bauen und ändern',
	'Claude is working on this page. Wait a moment or press Stop.' => 'Claude arbeitet an dieser Seite. Warten Sie einen Moment oder drücken Sie Stopp.',
	'Claude’s changes are saved as a draft. Undo takes them all back.' => 'Die Änderungen von Claude sind als Entwurf gespeichert. Rückgängig nimmt sie alle zurück.',
	'Claude could not start. Try again.' => 'Claude konnte nicht starten. Versuchen Sie es erneut.',
	'New chat' => 'Neuer Chat',
	'Build pages by describing them' => 'Seiten bauen, indem Sie sie beschreiben',
	'Connect Claude once with your Anthropic API key, then tell it what to build or change on this page.' => 'Verbinden Sie Claude einmal mit Ihrem Anthropic-API-Schlüssel – dann sagen Sie ihm, was es auf dieser Seite bauen oder ändern soll.',
	'Connect Claude' => 'Claude verbinden',
	'Ask an administrator to connect it under Velox Builder → AI agents.' => 'Bitten Sie einen Administrator, es unter Velox Builder → KI-Agenten zu verbinden.',
	'Build a landing page with a hero, three benefits, customer quotes and a contact form' => 'Baue eine Landingpage mit Hero, drei Vorteilen, Kundenstimmen und Kontaktformular',
	'Make the selected section look more modern and give it more air' => 'Lass den ausgewählten Bereich moderner aussehen und gib ihm mehr Luft',
	'Check this page on phones and fix what looks off' => 'Prüfe diese Seite auf dem Handy und behebe, was nicht passt',
	'What should Claude do on this page?' => 'Was soll Claude auf dieser Seite tun?',
	'It uses your classes and design tokens, works in drafts and saves every change as a version. You check and publish.' => 'Es nutzt Ihre Klassen und Design-Tokens, arbeitet in Entwürfen und speichert jede Änderung als Version. Sie prüfen und veröffentlichen.',
