	'Enter sends · Shift+Enter for a new line' => 'Enter sendet · Umschalt+Enter für eine neue Zeile',
	// 4.65
	'Other carrier…' => 'Anderer Versanddienst …',
	'Carrier name' => 'Name des Versanddienstes',
	'e.g. GO! Express' => 'z. B. GO! Express',
	'Tracking link' => 'Link zur Sendungsverfolgung',
	'{code} is replaced by the tracking number.' => '{code} wird durch die Sendungsnummer ersetzt.',
	'Enter the carrier’s name.' => 'Geben Sie den Namen des Versanddienstes ein.',
	'The tracking link must start with https://' => 'Der Link zur Sendungsverfolgung muss mit https:// beginnen.',
