	'Create the missing page' => 'Fehlende Seite anlegen',
	'Without these the shop cannot work.' => 'Ohne diese Seiten funktioniert der Shop nicht.',
	'Add your legal pages: they are linked at checkout.' => 'Legen Sie Ihre Rechtstexte fest: Sie werden an der Kasse verlinkt.',
	'Everything is in place.' => 'Alles ist vorhanden.',
	'Code block' => 'Code-Block',
	'Code block — write HTML, CSS and JavaScript in Settings.' => 'Code-Block – schreiben Sie HTML, CSS und JavaScript unter Einstellungen.',
	'JavaScript runs on the page, not in the editor' => 'JavaScript läuft auf der Seite, nicht im Editor',
	'Only administrators can change code that runs on the page.' => 'Nur Administratoren können Code ändern, der auf der Seite ausgeführt wird.',
	'JavaScript (runs on the page; `el` is this block)' => 'JavaScript (läuft auf der Seite; `el` ist dieser Block)',
	'Unpin the element settings — they float over the canvas while something is selected' => 'Element-Einstellungen lösen – sie schweben über der Arbeitsfläche, solange etwas ausgewählt ist',
	'Pin the element settings — they get their own column' => 'Element-Einstellungen anheften – sie bekommen eine eigene Spalte',
	// 4.66
	'Build and change pages by chatting with Claude, with your own Claude account. Everything it does is a draft you check and publish.' => 'Seiten bauen und ändern, indem Sie mit Claude chatten – mit Ihrem eigenen Claude-Konto. Alles, was Claude tut, ist ein Entwurf, den Sie prüfen und veröffentlichen.',
	'Claude with your Claude account' => 'Claude mit Ihrem Claude-Konto',
	'Add this site to Claude as a connector. You chat in Claude (web, desktop app or Claude Code) and it works on your pages. Your Claude plan covers it: no API key, no extra costs.' => 'Fügen Sie diese Website in Claude als Connector hinzu. Sie chatten in Claude (Web, Desktop-App oder Claude Code), und Claude arbeitet an Ihren Seiten. Ihr Claude-Abo deckt das ab: kein API-Schlüssel, keine Zusatzkosten.',
	'Let Claude work on this site' => 'Claude an dieser Website arbeiten lassen',
	'Claude signs in with your WordPress account, can only do what you may do, and only on the pages you allow.' => 'Claude meldet sich mit Ihrem WordPress-Konto an, darf nur, was Sie dürfen, und nur auf den Seiten, die Sie freigeben.',
	'Claude only connects to https addresses. Switch the site to https first.' => 'Claude verbindet sich nur mit https-Adressen. Stellen Sie die Website zuerst auf https um.',
	'Connector address' => 'Connector-Adresse',
	'Where you use Claude' => 'Wo Sie Claude nutzen',
	'Claude (web and app)' => 'Claude (Web und App)',
	'Claude Code' => 'Claude Code',
	'Other apps' => 'Andere Apps',
	'Open the connectors in Claude' => 'Connectors in Claude öffnen',
	'On claude.ai or in the Claude app: Customize → Connectors (in some versions Settings → Connectors). Click + and choose “Add custom connector”.' => 'Auf claude.ai oder in der Claude-App: Anpassen → Connectors (in manchen Versionen Einstellungen → Connectors). Klicken Sie auf + und wählen Sie „Benutzerdefinierten Connector hinzufügen“.',
	'Open Claude' => 'Claude öffnen',
	'Paste the address' => 'Adresse einfügen',
	'Name: %s. Address: the connector address above. Leave the advanced settings empty, then click Add.' => 'Name: %s. Adresse: die Connector-Adresse oben. Lassen Sie die erweiterten Einstellungen leer und klicken Sie auf Hinzufügen.',
	'Sign in and allow' => 'Anmelden und erlauben',
	'Click Connect. This site\'s sign-in opens: sign in, choose the whole site or single pages, and click Allow.' => 'Klicken Sie auf Verbinden. Die Anmeldung dieser Website öffnet sich: Melden Sie sich an, wählen Sie die ganze Website oder einzelne Seiten und klicken Sie auf Zugriff erlauben.',
	'Chat' => 'Chatten',
	'In a chat, switch the connector on in the tools menu and say what to build. In the editor, “Work on this page in Claude” starts a chat about the page you have open.' => 'Schalten Sie den Connector in einem Chat im Werkzeug-Menü ein und sagen Sie, was entstehen soll. Im Editor startet „Diese Seite in Claude bearbeiten“ einen Chat über die geöffnete Seite.',
	'The connector works in the browser, the desktop app and the mobile app alike. Free plans can add one custom connector. In Team and Enterprise plans an owner adds it for the organisation first.' => 'Der Connector funktioniert im Browser, in der Desktop-App und in der Handy-App. Im kostenlosen Tarif ist ein eigener Connector möglich. In Team- und Enterprise-Tarifen fügt ihn zuerst ein Owner für die Organisation hinzu.',
	'Add the server' => 'Server hinzufügen',
	'Run this in a terminal:' => 'Führen Sie dies in einem Terminal aus:',
	'In Claude Code type /mcp, choose the server and Authenticate. Your browser opens this site\'s sign-in.' => 'Geben Sie in Claude Code /mcp ein, wählen Sie den Server und „Authenticate“. Ihr Browser öffnet die Anmeldung dieser Website.',
	'Apps that connect to remote MCP servers with a sign-in (Cursor, VS Code, ChatGPT and others) take the connector address above. For an app that is set up with a configuration file, add the lines below to it. Node.js must be installed. Claude Desktop does not need this: the connector you add in Claude works there too.' => 'Apps, die sich mit Anmeldung zu entfernten MCP-Servern verbinden (Cursor, VS Code, ChatGPT und andere), nehmen die Connector-Adresse oben. Für eine App, die über eine Konfigurationsdatei eingerichtet wird, fügen Sie die Zeilen unten hinzu. Node.js muss installiert sein. Claude Desktop braucht das nicht: Der Connector, den Sie in Claude hinzufügen, funktioniert dort auch.',
	'Where it goes' => 'Wohin es gehört',
	'The file is one pair of curly braces with entries separated by commas. Keep everything that is in it.' => 'Die Datei ist ein Paar geschweifter Klammern mit Einträgen, die durch Kommas getrennt sind. Lassen Sie alles stehen, was schon darin ist.',
	'what is already in the file' => 'was schon in der Datei steht',
	'The file has no "mcpServers" yet' => 'Die Datei hat noch kein "mcpServers"',
	'Put a comma after the last entry, then paste the whole block before the last closing brace.' => 'Setzen Sie ein Komma hinter den letzten Eintrag und fügen Sie dann den ganzen Block vor der letzten schließenden Klammer ein.',
	'Copy the block' => 'Block kopieren',
	'It already has "mcpServers"' => 'Sie hat schon "mcpServers"',
	'Paste only the entry inside its braces, with a comma after the entry before it.' => 'Fügen Sie nur den Eintrag in dessen Klammern ein, mit einem Komma hinter dem Eintrag davor.',
	'Copy the entry' => 'Eintrag kopieren',
	'Claude Desktop\'s file, if you want it anyway: Windows %APPDATA%\\Claude\\claude_desktop_config.json (type it into the Explorer address bar), Mac ~/Library/Application Support/Claude/claude_desktop_config.json. Restart the app after saving.' => 'Die Datei von Claude Desktop, falls Sie sie trotzdem möchten: Windows %APPDATA%\\Claude\\claude_desktop_config.json (in die Adressleiste des Explorers eingeben), Mac ~/Library/Application Support/Claude/claude_desktop_config.json. Starten Sie die App nach dem Speichern neu.',
	'Check the connection' => 'Verbindung prüfen',
	'Checks from this server what Claude will see.' => 'Prüft von diesem Server aus, was Claude sieht.',
	'Connected apps' => 'Verbundene Apps',
	'Who is connected, and to which pages. Disconnecting signs the app out at once.' => 'Wer verbunden ist und mit welchen Seiten. Trennen meldet die App sofort ab.',
	'Claude inside the editor (with an API key)' => 'Claude im Editor (mit API-Schlüssel)',
	'Optional: a chat panel right in the editor. It needs an Anthropic API key, and you pay Anthropic per use.' => 'Optional: ein Chat direkt im Editor. Dafür brauchen Sie einen Anthropic-API-Schlüssel und zahlen Anthropic nach Verbrauch.',
	'What Claude can do here' => 'Was Claude hier kann',
	'Nothing connected yet. Add the connector in Claude as described above.' => 'Noch nichts verbunden. Fügen Sie den Connector wie oben beschrieben in Claude hinzu.',
	'Whole site' => 'Ganze Website',
	'by %s' => 'von %s',
	'last used %s ago' => 'zuletzt vor %s genutzt',
	'not used yet' => 'noch nicht genutzt',
	'%d s' => '%d Sek.',
	'%d min' => '%d Min.',
	'%d h' => '%d Std.',
	'%d d' => '%d Tg.',
	'on a computer' => 'auf einem Computer',
	'Disconnect' => 'Trennen',
	'Disconnect this app?' => 'Diese App trennen?',
	'It is signed out at once. To use it again, connect it again in the app.' => 'Sie wird sofort abgemeldet. Um sie wieder zu nutzen, verbinden Sie sie in der App erneut.',
	'The whole site' => 'Die ganze Website',
	'Only these pages' => 'Nur diese Seiten',
	'Choose at least one page, or allow everything.' => 'Wählen Sie mindestens eine Seite oder erlauben Sie alles.',
	'About this site' => 'Über diese Website',
	'The page open in the editor' => 'Die im Editor geöffnete Seite',
	'AI app' => 'KI-App',
	'AI connections are switched off' => 'KI-Verbindungen sind ausgeschaltet',
	'An administrator can switch them on under Velox Builder → AI agents.' => 'Ein Administrator kann sie unter Velox Builder → KI-Agenten einschalten.',
	'This app is not known to the site' => 'Diese App ist der Website nicht bekannt',
	'Start the connection again from the app (for example remove the connector in Claude and add it again).' => 'Starten Sie die Verbindung in der App erneut (zum Beispiel den Connector in Claude entfernen und neu hinzufügen).',
	'The app asked to return to an address it did not register' => 'Die App will zu einer Adresse zurück, die sie nicht angemeldet hat',
	'For your safety the connection stops here. Start it again from the app.' => 'Zu Ihrer Sicherheit endet die Verbindung hier. Starten Sie sie in der App erneut.',
	'Your account may not use Velox Builder' => 'Ihr Konto darf Velox Builder nicht nutzen',
	'Sign in with an account that may edit pages in Velox Builder, or ask an administrator.' => 'Melden Sie sich mit einem Konto an, das Seiten in Velox Builder bearbeiten darf, oder fragen Sie einen Administrator.',
	'Sign in with another account' => 'Mit anderem Konto anmelden',
	'Connect %s' => '%s verbinden',
	'%1$s wants to work on %2$s' => '%1$s möchte an %2$s arbeiten',
	'Claude by Anthropic · returns to %s' => 'Claude von Anthropic · kehrt zurück zu %s',
	'An app on this computer (for example Claude Code).' => 'Eine App auf diesem Computer (zum Beispiel Claude Code).',
	'Returns to %s. Only continue if you started this connection yourself just now.' => 'Kehrt zurück zu %s. Fahren Sie nur fort, wenn Sie diese Verbindung gerade selbst gestartet haben.',
	'What may it work on?' => 'Woran darf sie arbeiten?',
	'Every page, template and component you may edit in Velox Builder, and new draft pages.' => 'Jede Seite, Vorlage und Komponente, die Sie in Velox Builder bearbeiten dürfen, und neue Entwurfsseiten.',
	'Only the pages I choose' => 'Nur die Seiten, die ich auswähle',
	'It can read the design system, but change only these.' => 'Sie kann das Designsystem lesen, ändert aber nur diese.',
	'It reads your design system, pages and media library.' => 'Sie liest Ihr Designsystem, Ihre Seiten und Ihre Mediathek.',
	'It only changes drafts. Nothing goes live until you publish it.' => 'Sie ändert nur Entwürfe. Nichts geht online, bevor Sie es veröffentlichen.',
	'Every change is saved as a version marked “By AI”, one click to undo.' => 'Jede Änderung wird als Version „Von KI“ gespeichert, mit einem Klick rückgängig zu machen.',
	'You can disconnect it at any time under Velox Builder → AI agents.' => 'Sie können die Verbindung jederzeit unter Velox Builder → KI-Agenten trennen.',
	'It works as %1$s (%2$s) and can only do what you may do.' => 'Sie arbeitet als %1$s (%2$s) und darf nur, was Sie dürfen.',
	'Not you?' => 'Nicht Sie?',
	'Allow access' => 'Zugriff erlauben',
	'That connection no longer exists.' => 'Diese Verbindung gibt es nicht mehr.',
	'Secure address (https)' => 'Sichere Adresse (https)',
	'Yes.' => 'Ja.',
	'Connections switched on' => 'Verbindungen eingeschaltet',
	'Switch on “Let Claude work on this site” first.' => 'Schalten Sie zuerst „Claude an dieser Website arbeiten lassen“ ein.',
	'The site can reach itself' => 'Die Website erreicht sich selbst',
	'The server could not call its own address, so Velox cannot check the rest from here. That does not mean Claude cannot connect: just try it.' => 'Der Server konnte seine eigene Adresse nicht aufrufen, deshalb kann Velox den Rest von hier nicht prüfen. Das heißt nicht, dass Claude sich nicht verbinden kann: Probieren Sie es einfach.',
	'Claude finds the sign-in' => 'Claude findet die Anmeldung',
	'The discovery addresses answer.' => 'Die Erkennungs-Adressen antworten.',
	'The discovery address answered with status %d. A security plugin or the server may block /.well-known/ addresses.' => 'Die Erkennungs-Adresse antwortete mit Status %d. Ein Sicherheits-Plugin oder der Server blockiert womöglich /.well-known/-Adressen.',
	'Sign-in settings' => 'Anmelde-Einstellungen',
	'Not reachable. A security plugin may block the REST API for visitors.' => 'Nicht erreichbar. Ein Sicherheits-Plugin blockiert womöglich die REST-API für Besucher.',
	'The endpoint asks Claude to sign in' => 'Der Endpunkt fordert Claude zur Anmeldung auf',
	'It answered with status %d instead of asking to sign in.' => 'Er antwortete mit Status %d, statt zur Anmeldung aufzufordern.',
	'Sign-in tokens reach WordPress' => 'Anmelde-Tokens erreichen WordPress',
	'Yes: the server passes the Authorization header on.' => 'Ja: Der Server gibt den Authorization-Header weiter.',
	'The server drops the Authorization header before WordPress sees it. Your host can fix this (Apache: CGIPassAuth On).' => 'Der Server verwirft den Authorization-Header, bevor WordPress ihn sieht. Ihr Hoster kann das beheben (Apache: CGIPassAuth On).',
	'Work on this page in Claude' => 'Diese Seite in Claude bearbeiten',
	'Claude is connected to this site with your Claude account. Say what to do: Claude opens in a new tab and knows which page you mean.' => 'Claude ist mit Ihrem Claude-Konto mit dieser Website verbunden. Sagen Sie, was zu tun ist: Claude öffnet sich in einem neuen Tab und weiß, welche Seite Sie meinen.',
	'What it changes shows up here live, as a draft. Undo takes it back.' => 'Was Claude ändert, erscheint hier live als Entwurf. Rückgängig nimmt es zurück.',
	'%1$s was active %2$s ago' => '%1$s war vor %2$s aktiv',
	'Connect Claude once' => 'Claude einmal verbinden',
	'Add this site to Claude as a connector, with your own Claude account. No API key, no extra costs.' => 'Fügen Sie diese Website in Claude als Connector hinzu, mit Ihrem eigenen Claude-Konto. Kein API-Schlüssel, keine Zusatzkosten.',
	'In Claude: Customize → Connectors → Add custom connector, then paste this address:' => 'In Claude: Anpassen → Connectors → Benutzerdefinierten Connector hinzufügen, dann diese Adresse einfügen:',
	'Step by step' => 'Schritt für Schritt',
	'Work on this page with Claude, using your own Claude account. It is switched on once under Velox Builder → AI agents.' => 'Bearbeiten Sie diese Seite mit Claude und Ihrem eigenen Claude-Konto. Das wird einmal unter Velox Builder → KI-Agenten eingeschaltet.',
	'Set up Claude' => 'Claude einrichten',
	'Ask an administrator to switch it on under Velox Builder → AI agents.' => 'Bitten Sie einen Administrator, es unter Velox Builder → KI-Agenten einzuschalten.',
	'Copy the request, for Claude Desktop or Claude Code' => 'Anfrage kopieren, für Claude Desktop oder Claude Code',
	'Open in Claude' => 'In Claude öffnen',
	'Enter opens Claude · Shift+Enter for a new line' => 'Enter öffnet Claude · Umschalt+Enter für eine neue Zeile',
	'the page' => 'der Seite',
	'the template' => 'der Vorlage',
	'the component' => 'der Komponente',
	'Use the Velox connector for my website “%s”.' => 'Nutze den Velox-Connector für meine Website „%s“.',
	'Work on %1$s “%2$s” (Velox document %3$s), which I have open in the editor.' => 'Arbeite an %1$s „%2$s“ (Velox-Dokument %3$s), geöffnet bei mir im Editor.',
	'Copy failed' => 'Kopieren fehlgeschlagen',
	'Save the page first: Claude works on the saved version.' => 'Speichern Sie die Seite zuerst: Claude arbeitet mit der gespeicherten Fassung.',
	'Claude changed this page while you have unsaved changes.' => 'Claude hat diese Seite geändert, während Sie ungespeicherte Änderungen haben.',
	'If you keep yours, saving replaces Claude’s changes. They stay under History → Saved versions.' => 'Wenn Sie Ihre behalten, ersetzt das Speichern die Änderungen von Claude. Sie bleiben unter Verlauf → Gespeicherte Versionen erhalten.',
	'Keep mine' => 'Meine behalten',
	'Load Claude’s version' => 'Fassung von Claude laden',
	'Claude changed this page. Undo takes it back.' => 'Claude hat diese Seite geändert. Rückgängig nimmt es zurück.',
