	// 4.68
	'Test page: the design choices you have not saved yet. Visitors still see the saved design.' => 'Testseite: die noch nicht gespeicherten Design-Einstellungen. Besucher sehen weiterhin das gespeicherte Design.',
	'Shop and product pages' => 'Shop- und Produktseiten',
	'Cart and checkout' => 'Warenkorb und Kasse',
	'Wishlist, reviews and alerts' => 'Merkliste, Bewertungen und Benachrichtigungen',
	'Emails and order states' => 'E-Mails und Bestellstatus',
	'“%1$s” must keep its placeholders (%2$s): they are filled in with a number or a name.' => '„%1$s“ muss seine Platzhalter behalten (%2$s): Sie werden durch eine Zahl oder einen Namen ersetzt.',
	'The choices above style the shop everywhere. For full control, open a shop page in Velox Builder: the shop parts are elements there (product grid, cart, checkout, account), and you can place, size and style them like anything else.' => 'Die Einstellungen oben gestalten den Shop überall. Für volle Kontrolle öffnen Sie eine Shop-Seite in Velox Builder: Die Shop-Teile sind dort Elemente (Produktraster, Warenkorb, Kasse, Kundenkonto), die Sie wie alles andere platzieren, in der Größe ändern und gestalten.',
	'This page does not exist yet. Create it under Pages & legal.' => 'Diese Seite gibt es noch nicht. Legen Sie sie unter Seiten & Recht an.',
	'Try it on the real shop, before saving:' => 'Vor dem Speichern im echten Shop ansehen:',
	'A product' => 'Ein Produkt',
	'Categories above the products' => 'Kategorien über den Produkten',
	'Rounded buttons' => 'Abgerundete Buttons',
	'Underlined words' => 'Unterstrichene Wörter',
	'Solid blocks' => 'Volle Blöcke',
	'Sorting, search and filters are switched on under Storefront.' => 'Sortierung, Suche und Filter schalten Sie unter Storefront ein.',
	'Tabs on top' => 'Tabs oben',
	'List at the side' => 'Liste an der Seite',
	'On phones the menu is always on top.' => 'Auf dem Handy steht das Menü immer oben.',
	'Build it yourself' => 'Selbst bauen',
	'Back to the original' => 'Zurück zum Original',
	'Texts' => 'Texte',
	'Every text your customers see: buttons, notes, the account, the checkout and the emails. Type your own wording on the right; empty keeps the text shown in grey. Words like %s or %d stay in: they are filled in with a number or a name.' => 'Jeder Text, den Ihre Kunden sehen: Buttons, Hinweise, das Kundenkonto, die Kasse und die E-Mails. Tragen Sie rechts Ihre eigene Formulierung ein; leer lässt den grau angezeigten Text stehen. Zeichen wie %s oder %d bleiben drin: Sie werden durch eine Zahl oder einen Namen ersetzt.',
	'Search texts' => 'Texte durchsuchen',
	'No text matches.' => 'Kein Text passt.',
	'%d unsaved changes' => '%d ungespeicherte Änderungen',
	'Save texts' => 'Texte speichern',
	'Texts saved. They show on the site right away.' => 'Texte gespeichert. Sie erscheinen sofort auf der Website.',
	'Loading the shop’s texts…' => 'Die Texte des Shops werden geladen …',
	// 4.69 — tours and help
	'Help' => 'Hilfe',
	'A short tour of the builder, and answers to the questions that come up most.' => 'Eine kurze Tour durch den Builder und Antworten auf die häufigsten Fragen.',
	'Start the tour' => 'Tour starten',
	'Tour and help' => 'Tour und Hilfe',
	'The short tour of the builder, and answers to common questions.' => 'Die kurze Tour durch den Builder und Antworten auf häufige Fragen.',
	'Open the help' => 'Hilfe öffnen',
	'Skip the tour' => 'Tour überspringen',
	'You can start the tour again here at any time.' => 'Hier können Sie die Tour jederzeit erneut starten.',
	'Search the help' => 'Hilfe durchsuchen',
	'Nothing found. Try another word.' => 'Nichts gefunden. Versuchen Sie ein anderes Wort.',
	'Your shop is on' => 'Ihr Shop ist an',
	'This short tour shows where everything is. It takes about a minute; you can skip it and start it again later.' => 'Diese kurze Tour zeigt, wo alles ist. Sie dauert etwa eine Minute; Sie können sie überspringen und später erneut starten.',
	'Everything in one bar' => 'Alles in einer Leiste',
	'Overview, revenue, payouts, orders, products, coupons, customers, reviews and settings: the whole shop is here, without the WordPress lists.' => 'Übersicht, Umsatz, Auszahlungen, Bestellungen, Produkte, Gutscheine, Kunden, Bewertungen und Einstellungen: der ganze Shop ist hier, ohne die WordPress-Listen.',
	'The pages your shop needs' => 'Die Seiten, die Ihr Shop braucht',
	'Shop, cart, checkout and account. Missing ones are created with one click; the legal pages are linked at checkout.' => 'Shop, Warenkorb, Kasse und Kundenkonto. Fehlende werden mit einem Klick angelegt; die Rechtstexte werden an der Kasse verlinkt.',
	'Add your products' => 'Ihre Produkte anlegen',
	'Photos, price, options like size or colour, stock and shipping weight. A product is live as soon as you publish it.' => 'Fotos, Preis, Optionen wie Größe oder Farbe, Bestand und Versandgewicht. Ein Produkt ist online, sobald Sie es veröffentlichen.',
	'New orders show up with a number here and by email. Mark them as shipped with a tracking link; invoices are made for you.' => 'Neue Bestellungen erscheinen hier mit einer Zahl und per E-Mail. Markieren Sie sie mit einem Sendungslink als versendet; Rechnungen entstehen automatisch.',
	'How customers pay' => 'Wie Kunden bezahlen',
	'Stripe (cards, Apple Pay, Google Pay, Klarna), PayPal, bank transfer or invoice. Switch on what you want to offer.' => 'Stripe (Karten, Apple Pay, Google Pay, Klarna), PayPal, Überweisung oder Rechnung. Schalten Sie ein, was Sie anbieten möchten.',
	'Where you deliver, what it costs and from which amount it is free.' => 'Wohin Sie liefern, was es kostet und ab welchem Betrag es kostenlos ist.',
	'Your shop’s design' => 'Das Design Ihres Shops',
	'Pick a template, try it on the real shop before saving, then fine-tune colours, fonts, cards and pages.' => 'Wählen Sie eine Vorlage, probieren Sie sie vor dem Speichern im echten Shop aus und passen Sie dann Farben, Schriften, Karten und Seiten an.',
	'Your own words' => 'Ihre eigenen Worte',
	'Every text customers see can be changed here: buttons, notes, emails.' => 'Jeden Text, den Kunden sehen, können Sie hier ändern: Buttons, Hinweise, E-Mails.',
	'Help and this tour' => 'Hilfe und diese Tour',
	'Answers to common questions, and the button to take this tour again.' => 'Antworten auf häufige Fragen und der Button, um diese Tour erneut zu machen.',
	'Velox Builder is on' => 'Velox Builder ist an',
	'A visual editor for your pages, templates and reusable blocks. This tour shows the main places; it takes about a minute.' => 'Ein visueller Editor für Ihre Seiten, Vorlagen und wiederverwendbaren Blöcke. Diese Tour zeigt die wichtigsten Orte; sie dauert etwa eine Minute.',
	'Start a page' => 'Eine Seite beginnen',
	'Create a page and open it in the editor. Pages you already have can be opened from the list below.' => 'Legen Sie eine Seite an und öffnen Sie sie im Editor. Vorhandene Seiten öffnen Sie aus der Liste darunter.',
	'Header, footer and layout for many pages at once. Each page fills the template’s Inner Content.' => 'Kopf, Fuß und Aufbau für viele Seiten auf einmal. Jede Seite füllt den Inner-Content-Bereich der Vorlage.',
	'Blocks you build once and place anywhere. Change them in one place, they change everywhere.' => 'Blöcke, die Sie einmal bauen und überall platzieren. Ändern Sie sie an einer Stelle, ändern sie sich überall.',
	'Your design system' => 'Ihr Designsystem',
	'Classes, global styles and fonts: style once, use on every page.' => 'Klassen, globale Stile und Schriften: einmal gestalten, auf jeder Seite nutzen.',
	'Build with Claude' => 'Mit Claude bauen',
	'Connect Claude with your own Claude account and let it build and change drafts for you.' => 'Verbinden Sie Claude mit Ihrem eigenen Claude-Konto und lassen Sie es Entwürfe für Sie bauen und ändern.',
	'In the editor' => 'Im Editor',
	'Add elements with + Add, click to select, double-click to edit text. Accordions, tabs and sliders work right on the canvas. Ctrl+K opens every command.' => 'Elemente fügen Sie mit „Element hinzufügen“ (+) ein, ein Klick wählt aus, ein Doppelklick bearbeitet Text. Akkordeons, Tabs und Slider funktionieren direkt auf der Arbeitsfläche. Strg+K öffnet jeden Befehl.',
	'Getting started' => 'Erste Schritte',
	'What do I need before the first sale?' => 'Was brauche ich vor dem ersten Verkauf?',
	'The shop pages (Overview → Pages), at least one payment method (Settings → Payments), shipping costs (Settings → Shipping), your business details (Settings → Store) and your legal pages: terms, withdrawal policy, privacy (Settings → Pages & legal).' => 'Die Shop-Seiten (Übersicht → Seiten), mindestens eine Zahlart (Einstellungen → Zahlarten), Versandkosten (Einstellungen → Versand), Ihre Firmendaten (Einstellungen → Shop) und Ihre Rechtstexte: AGB, Widerrufsbelehrung, Datenschutz (Einstellungen → Seiten & Recht).',
	'How do I see the shop like a customer?' => 'Wie sehe ich den Shop wie ein Kunde?',
	'“View shop” at the top right opens it. Signed in as an administrator you see everything customers see; test orders work with Stripe’s test mode.' => '„Shop ansehen“ oben rechts öffnet ihn. Als Administrator angemeldet sehen Sie alles, was Kunden sehen; Testbestellungen funktionieren mit dem Testmodus von Stripe.',
	'How do I add a product with sizes or colours?' => 'Wie lege ich ein Produkt mit Größen oder Farben an?',
	'Products → New product. Under Options add for example “Size” with S, M, L. Every combination becomes a variant with its own price, stock and photo if you want.' => 'Produkte → Neues Produkt. Unter Optionen fügen Sie zum Beispiel „Größe“ mit S, M, L hinzu. Jede Kombination wird eine Variante mit eigenem Preis, Bestand und auf Wunsch eigenem Foto.',
	'What happens when something is sold out?' => 'Was passiert, wenn etwas ausverkauft ist?',
	'It is marked as sold. Under Settings → Stock & products you choose whether sold products stay visible, move to the end or disappear. Customers can ask to be told when it is back (Storefront).' => 'Es wird als verkauft markiert. Unter Einstellungen → Bestand & Produkte wählen Sie, ob verkaufte Produkte sichtbar bleiben, ans Ende rücken oder verschwinden. Kunden können sich benachrichtigen lassen, wenn es wieder da ist (Storefront).',
	'Orders and shipping' => 'Bestellungen und Versand',
	'How do I ship an order?' => 'Wie versende ich eine Bestellung?',
	'Open the order and click “Mark as shipped”. Pick the carrier (or any other with your own tracking link) and enter the tracking number. The customer gets an email with the link.' => 'Öffnen Sie die Bestellung und klicken Sie auf „Als versendet markieren“. Wählen Sie den Versanddienst (oder einen anderen mit eigenem Sendungslink) und tragen Sie die Sendungsnummer ein. Der Kunde bekommt eine E-Mail mit dem Link.',
	'Where are the invoices?' => 'Wo sind die Rechnungen?',
	'Every paid order gets an invoice number and a printable invoice with all the details German law asks for. Open it in the order; your browser saves it as a PDF.' => 'Jede bezahlte Bestellung bekommt eine Rechnungsnummer und eine druckbare Rechnung mit allen Angaben, die das deutsche Recht verlangt. Öffnen Sie sie in der Bestellung; Ihr Browser speichert sie als PDF.',
	'A customer wants to withdraw. What now?' => 'Ein Kunde möchte widerrufen. Was nun?',
	'Withdrawals arrive by email and are flagged on the order. Refund it in the order: for Stripe and PayPal payments Velox sends the money back through the provider.' => 'Widerrufe kommen per E-Mail und werden an der Bestellung markiert. Erstatten Sie in der Bestellung: Bei Stripe- und PayPal-Zahlungen schickt Velox das Geld über den Anbieter zurück.',
	'Which payment methods are there?' => 'Welche Zahlarten gibt es?',
	'Stripe (cards, Apple Pay, Google Pay, SEPA, Klarna), PayPal, bank transfer and invoice. Card and PayPal payments happen on the provider’s page: no card data touches your site.' => 'Stripe (Karten, Apple Pay, Google Pay, SEPA, Klarna), PayPal, Überweisung und Rechnung. Karten- und PayPal-Zahlungen laufen auf der Seite des Anbieters: Keine Kartendaten berühren Ihre Website.',
	'When do I get the money?' => 'Wann bekomme ich das Geld?',
	'Stripe and PayPal pay out on their schedule (see Payouts). Bank transfers and invoices you mark as paid in the order.' => 'Stripe und PayPal zahlen nach ihrem Zeitplan aus (siehe Auszahlungen). Überweisungen und Rechnungen markieren Sie in der Bestellung als bezahlt.',
	'Design and texts' => 'Design und Texte',
	'How do I change how the shop looks?' => 'Wie ändere ich das Aussehen des Shops?',
	'Settings → Design: pick a template, try it on the real shop before saving, then change colours, fonts, cards, product pages and the account. “Back to the pure template” undoes your changes.' => 'Einstellungen → Design: Wählen Sie eine Vorlage, probieren Sie sie vor dem Speichern im echten Shop aus und ändern Sie dann Farben, Schriften, Karten, Produktseiten und das Kundenkonto. „Zurück zur reinen Vorlage“ macht Ihre Änderungen rückgängig.',
	'Can I change the words on buttons and in emails?' => 'Kann ich die Worte auf Buttons und in E-Mails ändern?',
	'Yes, every text customers see: Settings → Texts. Search for it, type your own wording, save.' => 'Ja, jeden Text, den Kunden sehen: Einstellungen → Texte. Suchen, eigene Formulierung eintragen, speichern.',
	'Can I place the shop parts myself?' => 'Kann ich die Shop-Teile selbst platzieren?',
	'Yes. In Velox Builder the product grid, cart, checkout and account are elements you can place and style on any page. Settings → Design → Build it yourself opens the shop pages there.' => 'Ja. In Velox Builder sind Produktraster, Warenkorb, Kasse und Kundenkonto Elemente, die Sie auf jeder Seite platzieren und gestalten können. Einstellungen → Design → Selbst bauen öffnet die Shop-Seiten dort.',
	'Law in Germany' => 'Recht in Deutschland',
	'Is the checkout legally sound?' => 'Ist die Kasse rechtssicher?',
	'It shows prices with VAT, shipping costs, the order button with “zahlungspflichtig bestellen” wording, links to terms, withdrawal policy and privacy, and the online withdrawal button. Your legal texts themselves must come from you or a lawyer.' => 'Sie zeigt Preise mit MwSt., Versandkosten, den Bestellbutton mit „zahlungspflichtig bestellen“, Links zu AGB, Widerrufsbelehrung und Datenschutz sowie den Online-Widerrufsbutton. Ihre Rechtstexte selbst müssen von Ihnen oder einem Anwalt kommen.',
	'The editor' => 'Der Editor',
	'How do I add and arrange elements?' => 'Wie füge ich Elemente ein und ordne sie an?',
	'Click + Add and pick an element; it goes into the selected container or after the selected element. Drag elements on the canvas or in the Structure panel to move them.' => 'Klicken Sie auf „Element hinzufügen“ (+) und wählen Sie ein Element; es kommt in den ausgewählten Container oder hinter das ausgewählte Element. Ziehen Sie Elemente auf der Arbeitsfläche oder im Struktur-Panel, um sie zu verschieben.',
	'How do I edit text?' => 'Wie bearbeite ich Text?',
	'Double-click it. The text tools appear: bold, italic, links, alignment, “Style selection” for a few words in their own colour or size, and Insert Data for dynamic values.' => 'Doppelklicken Sie darauf. Die Textwerkzeuge erscheinen: fett, kursiv, Links, Ausrichtung, „Auswahl gestalten“ für einzelne Wörter in eigener Farbe oder Größe und Daten einfügen für dynamische Werte.',
	'How do accordions, tabs and sliders work?' => 'Wie funktionieren Akkordeons, Tabs und Slider?',
	'Like on the page: click a header, a tab or the arrows. Double-click a title to rename it. The selected one has “+ Add” for the next item, and every item can hold any elements.' => 'Wie auf der Seite: Klicken Sie auf eine Überschrift, einen Tab oder die Pfeile. Ein Doppelklick auf einen Titel benennt ihn um. Das ausgewählte Element hat „+ … hinzufügen“ für den nächsten Eintrag, und jeder Eintrag kann beliebige Elemente aufnehmen.',
	'Styling' => 'Gestaltung',
	'Class or element styles?' => 'Klasse oder Element-Stile?',
	'Styles on a class apply to every element with that class, on every page. Use them for anything repeated (cards, buttons). Element styles are for one-offs.' => 'Stile einer Klasse gelten für jedes Element mit dieser Klasse, auf jeder Seite. Nutzen Sie sie für alles, was sich wiederholt (Karten, Buttons). Element-Stile sind für Einzelfälle.',
	'How do I style for phones?' => 'Wie gestalte ich für das Handy?',
	'Switch the screen size in the top bar. A value set on a smaller size only applies there and below.' => 'Wechseln Sie die Bildschirmgröße in der oberen Leiste. Ein Wert auf einer kleineren Größe gilt nur dort und darunter.',
	'Where are colours and fonts for the whole site?' => 'Wo sind Farben und Schriften für die ganze Website?',
	'Global styles (colours as design tokens, headings, links) and Fonts. Use tokens in any colour field, so a change there changes the whole site.' => 'Globale Stile (Farben als Design-Tokens, Überschriften, Links) und Schriften. Nutzen Sie Tokens in jedem Farbfeld, dann ändert eine Änderung dort die ganze Website.',
	'Pages and publishing' => 'Seiten und Veröffentlichen',
	'Is my work live right away?' => 'Ist meine Arbeit sofort online?',
	'No. Saving keeps a draft; visitors see the page only after Publish. Every save is a version under History, one click to go back.' => 'Nein. Speichern hält einen Entwurf fest; Besucher sehen die Seite erst nach Veröffentlichen. Jedes Speichern ist eine Version unter Verlauf, ein Klick zurück.',
	'How do templates work?' => 'Wie funktionieren Vorlagen?',
	'A template is the frame (header, footer, layout). Its Inner Content element is where each page’s own content goes. Conditions decide which pages use which template.' => 'Eine Vorlage ist der Rahmen (Kopf, Fuß, Aufbau). Ihr Inner-Content-Element ist der Platz für den eigenen Inhalt jeder Seite. Bedingungen entscheiden, welche Seiten welche Vorlage nutzen.',
	'What is a reusable?' => 'Was ist ein wiederverwendbares Element?',
	'A block you build once and place on many pages. Change it once, it changes everywhere.' => 'Ein Block, den Sie einmal bauen und auf vielen Seiten platzieren. Ändern Sie ihn einmal, ändert er sich überall.',
	'Claude and AI' => 'Claude und KI',
	'Can Claude build pages for me?' => 'Kann Claude Seiten für mich bauen?',
	'Yes. Under AI agents add the site to Claude as a connector, with your own Claude account. Then ask in Claude, or use “Work on this page in Claude” in the editor. Claude only writes drafts; you check and publish.' => 'Ja. Unter KI-Agenten fügen Sie die Website mit Ihrem eigenen Claude-Konto als Connector in Claude hinzu. Dann fragen Sie in Claude oder nutzen im Editor „Diese Seite in Claude bearbeiten“. Claude schreibt nur Entwürfe; Sie prüfen und veröffentlichen.',
	'Keyboard shortcuts?' => 'Tastenkürzel?',
	'Ctrl+K opens every command, Ctrl+S saves, Ctrl+Z undoes. The full list (and your own keys) is under Keyboard shortcuts.' => 'Strg+K öffnet jeden Befehl, Strg+S speichert, Strg+Z macht rückgängig. Die ganze Liste (und Ihre eigenen Tasten) finden Sie unter Tastenkürzel.',
	'Something looks different on the page than in the editor?' => 'Auf der Seite sieht etwas anders aus als im Editor?',
	'Check the template the page uses (View as), styles on a smaller screen size, and your theme’s CSS. Velox shows the template’s CSS in the editor too, so they should match.' => 'Prüfen Sie die Vorlage der Seite (Ansehen als), Stile auf einer kleineren Bildschirmgröße und das CSS Ihres Themes. Velox zeigt das CSS der Vorlage auch im Editor, daher sollten beide übereinstimmen.',
	'Help & tour' => 'Hilfe & Tour',
	'Tour' => 'Tour',
	'A short walk through the shop: where orders, products, payments, shipping and the design are.' => 'Ein kurzer Rundgang durch den Shop: wo Bestellungen, Produkte, Zahlarten, Versand und das Design sind.',
