	'%d colours are yours, so the shop does not look like the template’s picture.' => '%d Farben sind Ihre eigenen, deshalb sieht der Shop nicht aus wie das Bild der Vorlage.',
	'%d choices in total. The tiles below show each template as it comes.' => '%d Einstellungen insgesamt. Die Kacheln unten zeigen jede Vorlage im Original.',
	'Use %s as it comes' => '%s im Original verwenden',
